export interface CarouselMetadata {
  topic: string;
  visual_style: string;
  target_audience: string;
}

export interface Slide {
  slide_number: number;
  headline: string;
  sub_headline: string;
  visual_description: string;
  layout_hint: string;
}

export interface CarouselResponse {
  carousel_metadata: CarouselMetadata;
  slides: Slide[];
}

export enum GenerationStatus {
  IDLE = 'IDLE',
  GENERATING_SCRIPT = 'GENERATING_SCRIPT',
  GENERATING_IMAGES = 'GENERATING_IMAGES',
  COMPLETE = 'COMPLETE',
  ERROR = 'ERROR'
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { CarouselResponse } from "../types";

// Initialize Gemini Client
// @ts-ignore - Env variable is injected by the sandbox environment
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

const CAROUSEL_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    carousel_metadata: {
      type: Type.OBJECT,
      properties: {
        topic: { type: Type.STRING },
        visual_style: { type: Type.STRING },
        target_audience: { type: Type.STRING },
      },
      required: ["topic", "visual_style", "target_audience"],
    },
    slides: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          slide_number: { type: Type.INTEGER },
          headline: { type: Type.STRING },
          sub_headline: { type: Type.STRING },
          visual_description: { type: Type.STRING },
          layout_hint: { type: Type.STRING },
        },
        required: ["slide_number", "headline", "sub_headline", "visual_description", "layout_hint"],
      },
    },
  },
  required: ["carousel_metadata", "slides"],
};

export const generateCarouselScript = async (
  topic: string,
  visualStyle: string,
  targetAudience: string
): Promise<CarouselResponse> => {
  const model = "gemini-3-flash-preview";

  const systemInstruction = `
    Role: You are a Senior Social Media Strategist and Visual Designer specializing in viral LinkedIn and Instagram carousels.
    Objective: Generate a cohesive, high-value 5-slide carousel script based on the user's input.

    Structure:
    - Slide 1: High-impact hook (The "Headline").
    - Slide 2-4: Actionable value (The "Meat").
    - Slide 5: Strong Call to Action (The "Close").

    Visual Consistency:
    - Every visual description must include the user's chosen "Style Tag" (${visualStyle}) to ensure consistency.
    - Visual descriptions should be optimized for AI image generation (e.g., describing the subject, lighting, composition, background).

    Style Tag: ${visualStyle}
    Target Audience: ${targetAudience}
  `;

  const prompt = `Topic: ${topic}`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: CAROUSEL_SCHEMA,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response text from Gemini");
    return JSON.parse(text) as CarouselResponse;
  } catch (error) {
    console.error("Error generating script:", error);
    throw error;
  }
};

export const generateSlideImage = async (
  visualDescription: string,
  visualStyle: string
): Promise<string> => {
  const model = "gemini-2.5-flash-image";

  // Construct a prompt optimized for image generation
  const imagePrompt = `
    Create a high-quality social media background image.
    Style: ${visualStyle}.
    Description: ${visualDescription}.
    Constraint: NO TEXT in the image. The image should be suitable for overlaying text later.
    Aspect Ratio: 4:5 (vertical).
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: [{ text: imagePrompt }]
      },
      config: {
        // Nano banana models don't support responseMimeType or specific aspect ratio params in the same way as Imagen
        // But we can guide it via prompt.
      }
    });

    // Extract image from response
    // The model typically returns an image part or raw data
    // For gemini-2.5-flash-image, we look for inlineData in parts
    const parts = response.candidates?.[0]?.content?.parts;

    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
           return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("No image data found in response");

  } catch (error) {
    console.error("Error generating image:", error);
    throw error;
  }
};

import React from 'react';
import { Slide } from '../types';
import { Image, Type, RefreshCw } from 'lucide-react';

interface SlideCardProps {
  slide: Slide;
  imageData?: string;
  isGeneratingImage: boolean;
  onGenerateImage: (slideNumber: number) => void;
}

const SlideCard: React.FC<SlideCardProps> = ({ 
  slide, 
  imageData, 
  isGeneratingImage, 
  onGenerateImage 
}) => {

  // Determine text alignment based on layout hint
  const getTextAlignment = (hint: string) => {
    if (hint.includes('center')) return 'text-center items-center';
    if (hint.includes('right')) return 'text-right items-end';
    return 'text-left items-start';
  };

  const alignmentClass = getTextAlignment(slide.layout_hint.toLowerCase());

  return (
    <div className="flex-shrink-0 w-[300px] h-[375px] relative rounded-xl overflow-hidden shadow-2xl bg-slate-800 border border-slate-700 group transition-all duration-300 hover:scale-[1.02]">
      {/* Background Image Layer */}
      <div className="absolute inset-0 z-0 bg-slate-900">
        {imageData ? (
          <img 
            src={imageData} 
            alt={`Slide ${slide.slide_number} visual`} 
            className="w-full h-full object-cover opacity-60"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center text-slate-700">
            <div className="text-center p-4">
              <Image className="w-12 h-12 mx-auto mb-2 opacity-50" />
              <p className="text-xs">Visual description provided</p>
            </div>
          </div>
        )}
        {/* Overlay gradient to ensure text readability */}
        <div className="absolute inset-0 bg-gradient-to-b from-transparent via-slate-900/40 to-slate-900/90 pointer-events-none"></div>
      </div>

      {/* Content Layer */}
      <div className={`relative z-10 h-full p-6 flex flex-col justify-between ${alignmentClass}`}>
        <div className="w-full">
            <div className="bg-blue-500/20 text-blue-300 text-[10px] font-bold px-2 py-1 rounded inline-block mb-4 backdrop-blur-sm">
                SLIDE {slide.slide_number}
            </div>
            <h2 className="text-2xl font-bold text-white mb-2 leading-tight drop-shadow-md">
                {slide.headline}
            </h2>
            <p className="text-sm text-slate-200 font-medium leading-relaxed drop-shadow-sm">
                {slide.sub_headline}
            </p>
        </div>

        {/* Controls - Only visible on hover or if empty */}
        <div className="w-full pt-4 mt-auto">
             <button
                onClick={() => onGenerateImage(slide.slide_number)}
                disabled={isGeneratingImage}
                className={`w-full text-xs font-semibold py-2 px-3 rounded-lg flex items-center justify-center gap-2 transition-all backdrop-blur-md
                    ${imageData 
                        ? 'bg-white/10 hover:bg-white/20 text-white border border-white/20 opacity-0 group-hover:opacity-100' 
                        : 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg shadow-blue-900/50'
                    }
                    disabled:opacity-50 disabled:cursor-not-allowed
                `}
             >
                {isGeneratingImage ? (
                    <>
                        <RefreshCw className="w-3 h-3 animate-spin" />
                        Generating...
                    </>
                ) : (
                    <>
                        <Image className="w-3 h-3" />
                        {imageData ? 'Regenerate Background' : 'Generate Visual'}
                    </>
                )}
             </button>

             {!imageData && (
                 <div className="mt-2 text-[10px] text-slate-400 leading-tight line-clamp-2">
                    Prompt: {slide.visual_description}
                 </div>
             )}
        </div>
      </div>
    </div>
  );
};

export default SlideCard;

import React, { useState } from 'react';
import { Sparkles, Wand2, Layers, Download, Palette, Users, Type } from 'lucide-react';
import { generateCarouselScript, generateSlideImage } from './services/geminiService';
import { CarouselResponse, GenerationStatus } from './types';
import SlideCard from './components/SlideCard';

const VISUAL_STYLES = [
  "Minimalist & Clean",
  "Cyberpunk Neon",
  "Corporate Memphis",
  "Dark Mode Gradient",
  "Abstract Geometric",
  "Vintage Paper Texture",
  "3D Claymorphism",
  "Futuristic Tech"
];

function App() {
  // Input State
  const [topic, setTopic] = useState('');
  const [visualStyle, setVisualStyle] = useState(VISUAL_STYLES[0]);
  const [targetAudience, setTargetAudience] = useState('');

  // Result State
  const [carouselData, setCarouselData] = useState<CarouselResponse | null>(null);
  const [generatedImages, setGeneratedImages] = useState<Record<number, string>>({});
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [imageLoadingState, setImageLoadingState] = useState<Record<number, boolean>>({});

  const handleGenerateScript = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic || !targetAudience) return;

    setStatus(GenerationStatus.GENERATING_SCRIPT);
    setCarouselData(null);
    setGeneratedImages({});

    try {
      const data = await generateCarouselScript(topic, visualStyle, targetAudience);
      setCarouselData(data);
      setStatus(GenerationStatus.COMPLETE);
    } catch (error) {
      console.error(error);
      setStatus(GenerationStatus.ERROR);
    }
  };

  const handleGenerateImage = async (slideNumber: number) => {
    if (!carouselData) return;

    const slide = carouselData.slides.find(s => s.slide_number === slideNumber);
    if (!slide) return;

    setImageLoadingState(prev => ({ ...prev, [slideNumber]: true }));

    try {
      const base64Image = await generateSlideImage(slide.visual_description, carouselData.carousel_metadata.visual_style);
      setGeneratedImages(prev => ({ ...prev, [slideNumber]: base64Image }));
    } catch (error) {
      console.error("Failed to generate image for slide " + slideNumber, error);
    } finally {
      setImageLoadingState(prev => ({ ...prev, [slideNumber]: false }));
    }
  };

  const handleGenerateAllImages = async () => {
      if (!carouselData) return;

      const promises = carouselData.slides.map(slide => handleGenerateImage(slide.slide_number));
      await Promise.all(promises);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 selection:bg-blue-500/30">
      {/* Header */}
      <header className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-xl sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-blue-600 flex items-center justify-center">
              <Layers className="w-5 h-5 text-white" />
            </div>
            <h1 className="font-bold text-lg tracking-tight text-white">Carousel<span className="text-blue-500">AI</span></h1>
          </div>
          <div className="text-xs font-medium px-3 py-1 rounded-full bg-slate-800 border border-slate-700 text-slate-400">
            Powered by Gemini
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-12">
        <div className="grid lg:grid-cols-12 gap-12">

          {/* Left Column: Input Form */}
          <div className="lg:col-span-4 space-y-8">
            <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-xl">
              <h2 className="text-xl font-semibold text-white mb-6 flex items-center gap-2">
                <Wand2 className="w-5 h-5 text-blue-500" />
                Create New Carousel
              </h2>

              <form onSubmit={handleGenerateScript} className="space-y-5">
                <div className="space-y-2">
                  <label className="text-sm font-medium text-slate-400 flex items-center gap-2">
                    <Type className="w-4 h-4" /> Topic
                  </label>
                  <input
                    type="text"
                    value={topic}
                    onChange={(e) => setTopic(e.target.value)}
                    placeholder="e.g. 5 Ways to Scale your SaaS..."
                    className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"
                    required
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-medium text-slate-400 flex items-center gap-2">
                    <Users className="w-4 h-4" /> Target Audience
                  </label>
                  <input
                    type="text"
                    value={targetAudience}
                    onChange={(e) => setTargetAudience(e.target.value)}
                    placeholder="e.g. Startup Founders, Marketers..."
                    className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"
                    required
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-medium text-slate-400 flex items-center gap-2">
                    <Palette className="w-4 h-4" /> Visual Style
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    {VISUAL_STYLES.map(style => (
                      <button
                        key={style}
                        type="button"
                        onClick={() => setVisualStyle(style)}
                        className={`text-xs px-3 py-2 rounded-lg text-left transition-all border ${
                          visualStyle === style 
                          ? 'bg-blue-600/20 border-blue-500 text-blue-300' 
                          : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-600'
                        }`}
                      >
                        {style}
                      </button>
                    ))}
                  </div>
                </div>

                <button
                  type="submit"
                  disabled={status === GenerationStatus.GENERATING_SCRIPT}
                  className="w-full bg-blue-600 hover:bg-blue-500 text-white font-semibold py-4 rounded-xl shadow-lg shadow-blue-900/20 flex items-center justify-center gap-2 transition-all hover:scale-[1.02] disabled:opacity-50 disabled:scale-100 disabled:cursor-not-allowed mt-4"
                >
                  {status === GenerationStatus.GENERATING_SCRIPT ? (
                    <>
                      <Sparkles className="w-5 h-5 animate-spin" />
                      Crafting Strategy...
                    </>
                  ) : (
                    <>
                      <Sparkles className="w-5 h-5" />
                      Generate Carousel
                    </>
                  )}
                </button>
              </form>
            </div>

            {/* Tips / Instructions */}
            <div className="bg-slate-900/50 border border-slate-800/50 rounded-2xl p-6 text-sm text-slate-500">
               <h3 className="text-slate-300 font-semibold mb-2">Pro Tips</h3>
               <ul className="space-y-2 list-disc list-inside">
                  <li>Be specific with your audience for better hooks.</li>
                  <li>Try "Cyberpunk" style for tech topics.</li>
                  <li>The AI generates image prompts for each slide automatically.</li>
               </ul>
            </div>
          </div>

          {/* Right Column: Output */}
          <div className="lg:col-span-8 space-y-8">
            {status === GenerationStatus.IDLE && (
              <div className="h-full flex flex-col items-center justify-center text-slate-600 border-2 border-dashed border-slate-800 rounded-3xl min-h-[500px]">
                <Layers className="w-16 h-16 mb-4 opacity-20" />
                <p className="text-lg">Enter a topic to generate your first carousel.</p>
              </div>
            )}

            {status === GenerationStatus.GENERATING_SCRIPT && (
              <div className="h-full flex flex-col items-center justify-center min-h-[500px] animate-pulse">
                 <div className="w-16 h-16 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mb-6"></div>
                 <p className="text-blue-400 font-medium">Analyzing viral trends...</p>
                 <p className="text-slate-500 text-sm mt-2">Writing hooks and content</p>
              </div>
            )}

            {(status === GenerationStatus.COMPLETE || status === GenerationStatus.GENERATING_IMAGES) && carouselData && (
              <div className="space-y-8 animate-in fade-in slide-in-from-bottom-8 duration-700">

                {/* Header for Results */}
                <div className="flex items-end justify-between">
                    <div>
                        <h2 className="text-2xl font-bold text-white mb-1">{carouselData.carousel_metadata.topic}</h2>
                        <p className="text-slate-400 text-sm">Targeting: {carouselData.carousel_metadata.target_audience}</p>
                    </div>
                    <button 
                        onClick={handleGenerateAllImages}
                        className="bg-white/5 hover:bg-white/10 text-white border border-white/10 px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2"
                    >
                        <Sparkles className="w-4 h-4 text-yellow-400" />
                        Generate All Visuals
                    </button>
                </div>

                {/* Carousel Preview Area */}
                <div className="w-full overflow-x-auto pb-8 pt-2 no-scrollbar">
                  <div className="flex gap-6 w-max px-2">
                    {carouselData.slides.map((slide) => (
                      <SlideCard
                        key={slide.slide_number}
                        slide={slide}
                        imageData={generatedImages[slide.slide_number]}
                        isGeneratingImage={!!imageLoadingState[slide.slide_number]}
                        onGenerateImage={handleGenerateImage}
                      />
                    ))}
                  </div>
                </div>

                {/* Script View (For copying) */}
                <div className="bg-slate-900 border border-slate-800 rounded-2xl overflow-hidden">
                    <div className="px-6 py-4 border-b border-slate-800 flex justify-between items-center bg-slate-900/50">
                        <h3 className="font-semibold text-slate-300">Raw Script</h3>
                        <div className="flex gap-2">
                            <button className="text-xs text-blue-400 hover:text-blue-300" onClick={() => navigator.clipboard.writeText(JSON.stringify(carouselData, null, 2))}>
                                Copy JSON
                            </button>
                        </div>
                    </div>
                    <div className="p-0">
                        {carouselData.slides.map((slide, idx) => (
                            <div key={idx} className={`p-6 border-b border-slate-800 last:border-0 hover:bg-slate-800/30 transition-colors flex gap-4`}>
                                <div className="text-slate-500 font-mono text-sm min-w-[24px] pt-1">
                                    {String(slide.slide_number).padStart(2, '0')}
                                </div>
                                <div className="space-y-1">
                                    <p className="text-white font-medium">{slide.headline}</p>
                                    <p className="text-slate-400 text-sm">{slide.sub_headline}</p>
                                    <p className="text-slate-600 text-xs mt-2 font-mono">Visual: {slide.visual_description}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  );
}

export default App;

