        parts: [{ text: imagePrompt }]
      },
    });

    // Extract image from response
    const parts = response.candidates?.[0]?.content?.parts;

    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
           return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("No image data found in response");

  } catch (error) {
    console.error("Error generating image:", error);
    throw error;
  }
};

import React from 'react';
import { Slide } from '../types';
import { Image, RefreshCw, Type, AlignLeft, AlignCenter, AlignRight } from 'lucide-react';

interface SlideCardProps {
  slide: Slide;
  imageData?: string;
  isGeneratingImage: boolean;
  onGenerateImage: (slideNumber: number) => void;
  onUpdateSlide: (slideNumber: number, field: keyof Slide, value: string) => void;
  readOnly?: boolean;
}

const SlideCard: React.FC<SlideCardProps> = ({ 
  slide, 
  imageData, 
  isGeneratingImage, 
  onGenerateImage,
  onUpdateSlide,
  readOnly = false
}) => {

  // Determine text alignment based on layout hint
  const getTextAlignment = (hint: string) => {
    if (hint.includes('center')) return 'text-center items-center';
    if (hint.includes('right')) return 'text-right items-end';
    return 'text-left items-start';
  };

  const alignmentClass = getTextAlignment(slide.layout_hint.toLowerCase());

  return (
    <div className="flex-shrink-0 w-[340px] h-[425px] relative rounded-xl overflow-hidden shadow-2xl bg-slate-800 border border-slate-700 group transition-all duration-300">
      {/* Background Image Layer */}
      <div className="absolute inset-0 z-0 bg-slate-900">
        {imageData ? (
          <img 
            src={imageData} 
            alt={`Slide ${slide.slide_number} visual`} 
            className="w-full h-full object-cover opacity-60"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center text-slate-700">
            <div className="text-center p-4">
              <Image className="w-12 h-12 mx-auto mb-2 opacity-50" />
              <p className="text-xs">Visual description provided</p>
            </div>
          </div>
        )}
        {/* Overlay gradient to ensure text readability */}
        <div className="absolute inset-0 bg-gradient-to-b from-transparent via-slate-900/40 to-slate-900/90 pointer-events-none"></div>
      </div>

      {/* Content Layer */}
      <div className={`relative z-10 h-full p-6 flex flex-col justify-between ${alignmentClass}`}>
        <div className="w-full space-y-3">
            <div className="flex justify-between items-center w-full">
                <div className="bg-blue-500/20 text-blue-300 text-[10px] font-bold px-2 py-1 rounded inline-block backdrop-blur-sm">
                    SLIDE {slide.slide_number}
                </div>
                {!readOnly && (
                    <div className="flex gap-1">
                        <button onClick={() => onUpdateSlide(slide.slide_number, 'layout_hint', 'left')} className={`p-1 rounded hover:bg-white/10 ${slide.layout_hint.includes('left') ? 'text-blue-400' : 'text-slate-500'}`}><AlignLeft size={12}/></button>
                        <button onClick={() => onUpdateSlide(slide.slide_number, 'layout_hint', 'center')} className={`p-1 rounded hover:bg-white/10 ${slide.layout_hint.includes('center') ? 'text-blue-400' : 'text-slate-500'}`}><AlignCenter size={12}/></button>
                        <button onClick={() => onUpdateSlide(slide.slide_number, 'layout_hint', 'right')} className={`p-1 rounded hover:bg-white/10 ${slide.layout_hint.includes('right') ? 'text-blue-400' : 'text-slate-500'}`}><AlignRight size={12}/></button>
                    </div>
                )}
            </div>

            {readOnly ? (
                <>
                    <h2 className="text-xl font-bold text-white leading-tight drop-shadow-md">{slide.headline}</h2>
                    <p className="text-sm text-slate-200 font-medium leading-relaxed drop-shadow-sm">{slide.sub_headline}</p>
                </>
            ) : (
                <>
                    <textarea 
                        value={slide.headline}
                        onChange={(e) => onUpdateSlide(slide.slide_number, 'headline', e.target.value)}
                        className={`bg-transparent border border-transparent hover:border-white/10 focus:border-blue-500/50 rounded w-full text-xl font-bold text-white leading-tight drop-shadow-md resize-none focus:outline-none focus:bg-slate-900/40 p-1 transition-all ${alignmentClass.includes('center') ? 'text-center' : alignmentClass.includes('right') ? 'text-right' : 'text-left'}`}
                        rows={2}
                        placeholder="Enter Headline"
                    />
                    <textarea 
                        value={slide.sub_headline}
                        onChange={(e) => onUpdateSlide(slide.slide_number, 'sub_headline', e.target.value)}
                        className={`bg-transparent border border-transparent hover:border-white/10 focus:border-blue-500/50 rounded w-full text-sm text-slate-200 font-medium leading-relaxed drop-shadow-sm resize-none focus:outline-none focus:bg-slate-900/40 p-1 transition-all ${alignmentClass.includes('center') ? 'text-center' : alignmentClass.includes('right') ? 'text-right' : 'text-left'}`}
                        rows={4}
                        placeholder="Enter Sub-headline"
                    />
                </>
            )}
        </div>

        {/* Controls */}
        <div className="w-full pt-4 mt-auto space-y-2">
             {!readOnly && (
                 <div className="relative group/prompt">
                    <label className="text-[10px] uppercase font-bold text-slate-500 mb-1 block">Visual Prompt</label>
                    <textarea
                        value={slide.visual_description}
                        onChange={(e) => onUpdateSlide(slide.slide_number, 'visual_description', e.target.value)}
                        className="w-full bg-slate-900/80 text-xs text-slate-300 border border-slate-700 rounded p-2 focus:border-blue-500 focus:outline-none resize-none h-16"
                    />
                 </div>
             )}

             <button
                onClick={() => onGenerateImage(slide.slide_number)}
                disabled={isGeneratingImage}
                className={`w-full text-xs font-semibold py-2 px-3 rounded-lg flex items-center justify-center gap-2 transition-all backdrop-blur-md
                    ${imageData 
                        ? 'bg-white/10 hover:bg-white/20 text-white border border-white/20' 
                        : 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg shadow-blue-900/50'
                    }
                    disabled:opacity-50 disabled:cursor-not-allowed
                `}
             >
                {isGeneratingImage ? (
                    <>
                        <RefreshCw className="w-3 h-3 animate-spin" />
                        Generating...
                    </>
                ) : (
                    <>
                        <Image className="w-3 h-3" />
                        {imageData ? 'Regenerate Visual' : 'Generate Visual'}
                    </>
                )}
             </button>
        </div>
      </div>
    </div>
  );
};

export default SlideCard;

import React, { useState, useEffect } from 'react';
import { Sparkles, Wand2, Layers, Download, Palette, Users, Type, Save, Archive, Play, Trash2, Edit3, Grid, Plus, Minus } from 'lucide-react';
import { generateCarouselScript, generateSlideImage } from './services/geminiService';
import { CarouselResponse, GenerationStatus, ViewMode, Slide } from './types';
import SlideCard from './components/SlideCard';

const VISUAL_STYLES = [
  "Minimalist & Clean",
  "Cyberpunk Neon",
  "Corporate Memphis",
  "Dark Mode Gradient",
  "Abstract Geometric",
  "Vintage Paper Texture",
  "3D Claymorphism",
  "Futuristic Tech",
  "Glassmorphism",
  "Brutalism",
  "Retro Pop Art",
  "Swiss International",
  "Doodle & Sketch",
  "Nature & Organic"
];

function App() {
  // --- View State ---
  const [activeView, setActiveView] = useState<ViewMode>('create');

  // --- Input State ---
  const [topic, setTopic] = useState('');
  const [visualStyle, setVisualStyle] = useState(VISUAL_STYLES[0]);
  const [targetAudience, setTargetAudience] = useState('');
  const [slideCount, setSlideCount] = useState<number>(5);

  // --- Data State ---
  const [currentCarousel, setCurrentCarousel] = useState<CarouselResponse | null>(null);
  const [generatedImages, setGeneratedImages] = useState<Record<string, Record<number, string>>>({}); // { carouselId: { slideNum: base64 } }
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [imageLoadingState, setImageLoadingState] = useState<Record<number, boolean>>({});

  // --- History State ---
  const [library, setLibrary] = useState<CarouselResponse[]>([]);

  // Load library from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('carousel_library');
    const savedImages = localStorage.getItem('carousel_images');
    if (saved) {
      try {
        setLibrary(JSON.parse(saved));
      } catch (e) { console.error("Failed to load library", e); }
    }
    if (savedImages) {
        try {
            setGeneratedImages(JSON.parse(savedImages));
        } catch (e) { console.error("Failed to load images", e); }
    }
  }, []);

  // Save library when it changes
  useEffect(() => {
    localStorage.setItem('carousel_library', JSON.stringify(library));
  }, [library]);

  // Save images when they change
  useEffect(() => {
    localStorage.setItem('carousel_images', JSON.stringify(generatedImages));
  }, [generatedImages]);


  // --- Actions ---

  const handleGenerateScript = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic || !targetAudience) return;

    setStatus(GenerationStatus.GENERATING_SCRIPT);

    try {
      const data = await generateCarouselScript(topic, visualStyle, targetAudience, slideCount);
      setCurrentCarousel(data);
      setStatus(GenerationStatus.COMPLETE);
      setActiveView('editor');
    } catch (error) {
      console.error(error);
      setStatus(GenerationStatus.ERROR);
    }
  };

  const handleGenerateImage = async (slideNumber: number) => {
    if (!currentCarousel) return;

    const slide = currentCarousel.slides.find(s => s.slide_number === slideNumber);
    if (!slide) return;

    setImageLoadingState(prev => ({ ...prev, [slideNumber]: true }));

    try {
      const base64Image = await generateSlideImage(slide.visual_description, currentCarousel.carousel_metadata.visual_style);
      setGeneratedImages(prev => ({
        ...prev,
        [currentCarousel.id]: {
            ...(prev[currentCarousel.id] || {}),
            [slideNumber]: base64Image
        }
      }));
    } catch (error) {
      console.error("Failed to generate image for slide " + slideNumber, error);
    } finally {
      setImageLoadingState(prev => ({ ...prev, [slideNumber]: false }));
    }
  };

  const handleGenerateAllImages = async () => {
      if (!currentCarousel) return;
      const promises = currentCarousel.slides.map(slide => handleGenerateImage(slide.slide_number));
      await Promise.all(promises);
  };

  const handleUpdateSlide = (slideNumber: number, field: keyof Slide, value: string) => {
      if (!currentCarousel) return;

      const updatedSlides = currentCarousel.slides.map(slide => {
          if (slide.slide_number === slideNumber) {
              return { ...slide, [field]: value };
          }
          return slide;
      });

      setCurrentCarousel({ ...currentCarousel, slides: updatedSlides });
  };

  const saveToLibrary = () => {
      if (!currentCarousel) return;

      // Check if already exists
      const exists = library.find(c => c.id === currentCarousel.id);
      let newLibrary;
      if (exists) {
          newLibrary = library.map(c => c.id === currentCarousel.id ? currentCarousel : c);
      } else {
          newLibrary = [currentCarousel, ...library];
      }
      setLibrary(newLibrary);
      alert('Saved to Library!');
  };

  const loadFromLibrary = (carousel: CarouselResponse) => {
      setCurrentCarousel(carousel);
      setActiveView('editor');
  };

  const deleteFromLibrary = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (confirm('Are you sure you want to delete this carousel?')) {
          setLibrary(prev => prev.filter(c => c.id !== id));
          // Clean up images
          const newImages = { ...generatedImages };
          delete newImages[id];
          setGeneratedImages(newImages);

          if (currentCarousel?.id === id) {
              setCurrentCarousel(null);
              setActiveView('create');
          }
      }
  };

  const exportJSON = () => {
      if (!currentCarousel) return;
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(currentCarousel, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", `carousel-${currentCarousel.carousel_metadata.topic.replace(/\s+/g, '-').toLowerCase()}.json`);
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
  };

  // --- Render Helpers ---

  const renderNav = () => (
      <nav className="flex flex-col space-y-2 w-full">
          <button 
            onClick={() => setActiveView('create')}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${activeView === 'create' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
          >
              <Wand2 className="w-5 h-5" /> Create
          </button>
          <button 
            onClick={() => setActiveView('editor')}
            disabled={!currentCarousel}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${activeView === 'editor' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50' : 'text-slate-400 hover:bg-slate-800 hover:text-white'} ${!currentCarousel ? 'opacity-50 cursor-not-allowed' : ''}`}
          >
              <Edit3 className="w-5 h-5" /> Editor
          </button>
          <button 
            onClick={() => setActiveView('library')}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${activeView === 'library' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
          >
              <Archive className="w-5 h-5" /> Library
          </button>
      </nav>
  );

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-blue-500/30 flex">

      {/* Sidebar */}
      <aside className="w-64 border-r border-slate-800 bg-slate-900/50 backdrop-blur-xl h-screen sticky top-0 flex flex-col p-6 shrink-0">
         <div className="flex items-center gap-2 mb-8">
            <div className="w-8 h-8 rounded-lg bg-blue-600 flex items-center justify-center">
              <Layers className="w-5 h-5 text-white" />
            </div>
            <h1 className="font-bold text-lg tracking-tight text-white">Carousel<span className="text-blue-500">AI</span></h1>
         </div>

         {renderNav()}

         <div className="mt-auto pt-6 border-t border-slate-800">
            <div className="text-xs text-slate-500 mb-2">Recent Projects</div>
            <div className="space-y-1">
                {library.slice(0, 3).map(item => (
                    <button key={item.id} onClick={() => loadFromLibrary(item)} className="block w-full text-left truncate text-sm text-slate-400 hover:text-white py-1">
                        {item.carousel_metadata.topic}
                    </button>
                ))}
            </div>
         </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto h-screen p-8 bg-slate-950 relative">

        {/* VIEW: CREATE */}
        {activeView === 'create' && (
            <div className="max-w-3xl mx-auto space-y-8 animate-in fade-in zoom-in-95 duration-500">
                <div className="text-center space-y-2 mb-12">
                    <h2 className="text-3xl font-bold text-white">What are we creating today?</h2>
                    <p className="text-slate-400">Generate viral LinkedIn & Instagram carousels in seconds.</p>
                </div>

                <div className="bg-slate-900 border border-slate-800 rounded-2xl p-8 shadow-xl">
                    <form onSubmit={handleGenerateScript} className="space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                             <div className="space-y-2">
                                <label className="text-sm font-medium text-slate-400 flex items-center gap-2">
                                    <Type className="w-4 h-4" /> Topic
                                </label>
                                <input
                                    type="text"
                                    value={topic}
                                    onChange={(e) => setTopic(e.target.value)}
                                    placeholder="e.g. 5 Ways to Scale your SaaS..."
                                    className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"
                                    required
                                />
                            </div>

                            <div className="space-y-2">
                                <label className="text-sm font-medium text-slate-400 flex items-center gap-2">
                                    <Users className="w-4 h-4" /> Target Audience
                                </label>
                                <input
                                    type="text"
                                    value={targetAudience}
                                    onChange={(e) => setTargetAudience(e.target.value)}
                                    placeholder="e.g. Startup Founders..."
                                    className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"
                                    required
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                             <label className="text-sm font-medium text-slate-400 flex items-center gap-2">
                                 <Grid className="w-4 h-4" /> Number of Slides: <span className="text-white font-bold">{slideCount}</span>
                             </label>
                             <div className="flex items-center gap-4">
                                <span className="text-xs text-slate-500">3</span>
                                <input 
                                    type="range" 
                                    min="3" 
                                    max="10" 
                                    value={slideCount} 
                                    onChange={(e) => setSlideCount(parseInt(e.target.value))}
                                    className="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-600"
                                />
                                <span className="text-xs text-slate-500">10</span>
                             </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-sm font-medium text-slate-400 flex items-center gap-2">
                                <Palette className="w-4 h-4" /> Visual Style
                            </label>
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                                {VISUAL_STYLES.map(style => (
                                <button
                                    key={style}
                                    type="button"
                                    onClick={() => setVisualStyle(style)}
                                    className={`text-xs px-3 py-2 rounded-lg text-left transition-all border truncate ${
                                    visualStyle === style 
                                    ? 'bg-blue-600/20 border-blue-500 text-blue-300 shadow-[0_0_10px_rgba(59,130,246,0.2)]' 
                                    : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-600'
                                    }`}
                                >
                                    {style}
                                </button>
                                ))}
                            </div>
                        </div>

                        <button
                            type="submit"
                            disabled={status === GenerationStatus.GENERATING_SCRIPT}
                            className="w-full bg-blue-600 hover:bg-blue-500 text-white font-semibold py-4 rounded-xl shadow-lg shadow-blue-900/20 flex items-center justify-center gap-2 transition-all hover:scale-[1.01] active:scale-[0.99] disabled:opacity-50 disabled:scale-100 disabled:cursor-not-allowed mt-4"
                        >
                            {status === GenerationStatus.GENERATING_SCRIPT ? (
                                <>
                                <Sparkles className="w-5 h-5 animate-spin" />
                                Crafting Strategy...
                                </>
                            ) : (
                                <>
                                <Sparkles className="w-5 h-5" />
                                Generate Carousel
                                </>
                            )}
                        </button>
                    </form>
                </div>
            </div>
        )}

        {/* VIEW: EDITOR */}
        {activeView === 'editor' && currentCarousel && (
            <div className="space-y-6 h-full flex flex-col animate-in fade-in slide-in-from-bottom-4 duration-500">
                <header className="flex items-center justify-between bg-slate-900/80 backdrop-blur border border-slate-800 p-4 rounded-xl sticky top-0 z-20">
                    <div>
                        <h2 className="text-xl font-bold text-white">{currentCarousel.carousel_metadata.topic}</h2>
                        <div className="flex gap-2 text-xs text-slate-400 mt-1">
                            <span className="bg-slate-800 px-2 py-0.5 rounded border border-slate-700">{currentCarousel.carousel_metadata.visual_style}</span>
                            <span className="bg-slate-800 px-2 py-0.5 rounded border border-slate-700">{currentCarousel.carousel_metadata.target_audience}</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-2">
                        <button onClick={saveToLibrary} className="bg-slate-800 hover:bg-slate-700 text-white border border-slate-700 px-3 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2">
                            <Save className="w-4 h-4" /> Save
                        </button>
                        <button onClick={exportJSON} className="bg-slate-800 hover:bg-slate-700 text-white border border-slate-700 px-3 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2">
                            <Download className="w-4 h-4" /> Export
                        </button>
                        <button onClick={handleGenerateAllImages} className="bg-blue-600 hover:bg-blue-500 text-white px-3 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 shadow-lg shadow-blue-900/20">
                            <Sparkles className="w-4 h-4 text-yellow-300" /> Generate All Images
                        </button>
                    </div>
                </header>

                <div className="flex-1 overflow-x-auto pb-4 no-scrollbar">
                    <div className="flex gap-6 w-max px-2 min-h-[450px] items-center">
                        {currentCarousel.slides.map((slide) => (
                            <SlideCard
                                key={slide.slide_number}
                                slide={slide}
                                imageData={generatedImages[currentCarousel.id]?.[slide.slide_number]}
                                isGeneratingImage={!!imageLoadingState[slide.slide_number]}
                                onGenerateImage={handleGenerateImage}
                                onUpdateSlide={handleUpdateSlide}
                            />
                        ))}
                    </div>
                </div>
            </div>
        )}

        {/* VIEW: LIBRARY */}
        {activeView === 'library' && (
            <div className="max-w-5xl mx-auto space-y-6 animate-in fade-in zoom-in-95 duration-500">
                <h2 className="text-2xl font-bold text-white flex items-center gap-2">
                    <Archive className="w-6 h-6 text-blue-500" /> Your Library
                </h2>

                {library.length === 0 ? (
                    <div className="text-center py-20 bg-slate-900/50 border border-slate-800 border-dashed rounded-2xl">
                        <Archive className="w-12 h-12 text-slate-700 mx-auto mb-4" />
                        <p className="text-slate-500">No saved carousels yet.</p>
                        <button onClick={() => setActiveView('create')} className="text-blue-500 hover:underline mt-2 text-sm">Create your first one</button>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {library.map((item) => (
                            <div key={item.id} onClick={() => loadFromLibrary(item)} className="bg-slate-900 border border-slate-800 hover:border-blue-500/50 rounded-xl p-5 cursor-pointer group transition-all hover:shadow-xl hover:shadow-blue-900/10 hover:-translate-y-1 relative">
                                <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button onClick={(e) => deleteFromLibrary(item.id, e)} className="p-2 text-slate-500 hover:text-red-400 hover:bg-slate-800 rounded-lg">
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                                <h3 className="font-bold text-white mb-2 line-clamp-1 pr-8">{item.carousel_metadata.topic}</h3>
                                <div className="flex flex-wrap gap-2 mb-4">
                                    <span className="text-[10px] bg-slate-800 text-slate-400 px-2 py-1 rounded border border-slate-700">
                                        {item.slides.length} Slides
                                    </span>
                                    <span className="text-[10px] bg-slate-800 text-slate-400 px-2 py-1 rounded border border-slate-700 truncate max-w-[120px]">
                                        {item.carousel_metadata.visual_style}
                                    </span>
                                </div>
                                <p className="text-xs text-slate-500">Created: {new Date(item.createdAt).toLocaleDateString()}</p>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        )}

      </main>
    </div>
  );
}

export default App;

export interface CarouselMetadata {
  topic: string;
  visual_style: string;
  target_audience: string;
}

export interface SlideDesign {
  textColor: string;
  overlayOpacity: number;
  fontSize: 'small' | 'medium' | 'large' | 'xl';
  textAlign: 'left' | 'center' | 'right';
  verticalAlign: 'top' | 'center' | 'bottom';
  textEffect: 'none' | 'shadow' | 'neon' | 'outline' | 'bg-highlight';
  decoration: 'none' | 'circle' | 'square' | 'accent-line' | 'corner-shape';
}

export interface Slide {
  slide_number: number;
  headline: string;
  sub_headline: string;
  visual_description: string;
  layout_hint: string;
  design: SlideDesign;
}

export interface CarouselResponse {
  id: string;
  createdAt: number;
  carousel_metadata: CarouselMetadata;
  slides: Slide[];
}

export enum GenerationStatus {
  IDLE = 'IDLE',
  GENERATING_SCRIPT = 'GENERATING_SCRIPT',
  GENERATING_IMAGES = 'GENERATING_IMAGES',
  COMPLETE = 'COMPLETE',
  ERROR = 'ERROR'
}

export type ViewMode = 'create' | 'editor' | 'library';

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { CarouselResponse, Slide } from "../types";

// Initialize Gemini Client
// @ts-ignore - Env variable is injected by the sandbox environment
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

const CAROUSEL_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    carousel_metadata: {
      type: Type.OBJECT,
      properties: {
        topic: { type: Type.STRING },
        visual_style: { type: Type.STRING },
        target_audience: { type: Type.STRING },
      },
      required: ["topic", "visual_style", "target_audience"],
    },
    slides: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          slide_number: { type: Type.INTEGER },
          headline: { type: Type.STRING },
          sub_headline: { type: Type.STRING },
          visual_description: { type: Type.STRING },
          layout_hint: { type: Type.STRING },
        },
        required: ["slide_number", "headline", "sub_headline", "visual_description", "layout_hint"],
      },
    },
  },
  required: ["carousel_metadata", "slides"],
};

export const generateCarouselScript = async (
  topic: string,
  visualStyle: string,
  targetAudience: string,
  slideCount: number
): Promise<CarouselResponse> => {
  const model = "gemini-3-flash-preview";

  const systemInstruction = `
    Role: You are a Senior Social Media Strategist and Visual Designer specializing in viral LinkedIn and Instagram carousels.
    Objective: Generate a cohesive, high-value ${slideCount}-slide carousel script based on the user's input.

    Structure:
    - Slide 1: High-impact hook (The "Headline").
    - Middle Slides (2-${slideCount - 1}): Actionable value (The "Meat").
    - Final Slide (${slideCount}): Strong Call to Action (The "Close").

    Visual Consistency:
    - Every visual description must include the user's chosen "Style Tag" (${visualStyle}) to ensure consistency.
    - Visual descriptions should be optimized for AI image generation (e.g., describing the subject, lighting, composition, background).

    Style Tag: ${visualStyle}
    Target Audience: ${targetAudience}
    Slide Count: ${slideCount}
  `;

  const prompt = `Topic: ${topic}. Create exactly ${slideCount} slides.`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: CAROUSEL_SCHEMA,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response text from Gemini");

    const data = JSON.parse(text);

    // Enrich with ID, Timestamp, and Default Design Properties
    const enrichedSlides = data.slides.map((slide: any) => ({
      ...slide,
      design: {
        textColor: '#ffffff',
        overlayOpacity: 40,
        fontSize: 'medium',
        textAlign: slide.layout_hint?.includes('center') ? 'center' : slide.layout_hint?.includes('right') ? 'right' : 'left',
        verticalAlign: 'top',
        textEffect: 'shadow',
        decoration: 'none'
      }
    }));

    return {
        ...data,
        slides: enrichedSlides,
        id: crypto.randomUUID(),
        createdAt: Date.now()
    } as CarouselResponse;

  } catch (error) {
    console.error("Error generating script:", error);
    throw error;
  }
};

export const generateSlideImage = async (
  visualDescription: string,
  visualStyle: string
): Promise<string> => {
  const model = "gemini-2.5-flash-image";

  // Construct a prompt optimized for image generation
  const imagePrompt = `
    Create a high-quality social media background image.
    Style: ${visualStyle}.
    Description: ${visualDescription}.
    Constraint: NO TEXT in the image. The image should be suitable for overlaying text later.
    Aspect Ratio: 4:5 (vertical).
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: [{ text: imagePrompt }]
      },
    });

    // Extract image from response
    const parts = response.candidates?.[0]?.content?.parts;

    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
           return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("No image data found in response");

  } catch (error) {
    console.error("Error generating image:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { Slide, SlideDesign } from '../types';
import { 
  Image, RefreshCw, Settings2, X, Type, 
  AlignLeft, AlignCenter, AlignRight, 
  ArrowUpToLine, ArrowDownToLine, MoveVertical,
  Palette, BoxSelect, Sparkles, Layers
} from 'lucide-react';

interface SlideCardProps {
  slide: Slide;
  imageData?: string;
  isGeneratingImage: boolean;
  onGenerateImage: (slideNumber: number) => void;
  onUpdateSlide: (slideNumber: number, field: keyof Slide, value: any) => void;
  onUpdateDesign: (slideNumber: number, field: keyof SlideDesign, value: any) => void;
  readOnly?: boolean;
}

const SlideCard: React.FC<SlideCardProps> = ({ 
  slide, 
  imageData, 
  isGeneratingImage, 
  onGenerateImage,
  onUpdateSlide,
  onUpdateDesign,
  readOnly = false
}) => {
  const [showSettings, setShowSettings] = useState(false);
  const design = slide.design;

  // Style Generators
  const getContainerStyle = () => {
    let justifyContent = 'justify-start';
    if (design.verticalAlign === 'center') justifyContent = 'justify-center';
    if (design.verticalAlign === 'bottom') justifyContent = 'justify-end';

    let alignItems = 'items-start';
    if (design.textAlign === 'center') alignItems = 'items-center';
    if (design.textAlign === 'right') alignItems = 'items-end';

    return `${justifyContent} ${alignItems}`;
  };

  const getTextStyle = (isHeadline: boolean) => {
    const baseSize = isHeadline ? 'font-bold' : 'font-medium';

    // Font Size
    let sizeClass = isHeadline ? 'text-2xl' : 'text-sm';
    if (design.fontSize === 'small') sizeClass = isHeadline ? 'text-xl' : 'text-xs';
    if (design.fontSize === 'large') sizeClass = isHeadline ? 'text-3xl' : 'text-base';
    if (design.fontSize === 'xl') sizeClass = isHeadline ? 'text-4xl' : 'text-lg';

    // Effects
    let effectClass = '';
    if (design.textEffect === 'shadow') effectClass = 'drop-shadow-lg shadow-black';
    if (design.textEffect === 'neon') effectClass = 'drop-shadow-[0_0_5px_rgba(255,255,255,0.8)]';
    if (design.textEffect === 'outline') effectClass = 'outline-text'; // Requires custom CSS or text-shadow hack
    if (design.textEffect === 'bg-highlight') effectClass = 'bg-black/50 px-2 rounded';

    return `${baseSize} ${sizeClass} ${effectClass} ${design.textAlign === 'center' ? 'text-center' : design.textAlign === 'right' ? 'text-right' : 'text-left'}`;
  };

  return (
    <div className="flex-shrink-0 w-[340px] h-[450px] relative rounded-xl overflow-hidden shadow-2xl bg-slate-800 border border-slate-700 group transition-all duration-300">

      {/* Background Image Layer */}
      <div className="absolute inset-0 z-0 bg-slate-900">
        {imageData ? (
          <img 
            src={imageData} 
            alt={`Slide ${slide.slide_number} visual`} 
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center text-slate-700">
            <div className="text-center p-4">
              <Image className="w-12 h-12 mx-auto mb-2 opacity-50" />
              <p className="text-xs">Visual description provided</p>
            </div>
          </div>
        )}

        {/* Customizable Overlay */}
        <div 
          className="absolute inset-0 pointer-events-none transition-all duration-300"
          style={{ backgroundColor: `rgba(15, 23, 42, ${design.overlayOpacity / 100})` }}
        ></div>

        {/* Decorations */}
        {design.decoration === 'circle' && (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-48 h-48 border-4 border-white/20 rounded-full pointer-events-none"></div>
        )}
        {design.decoration === 'square' && (
          <div className="absolute top-4 right-4 bottom-4 left-4 border-2 border-white/20 pointer-events-none"></div>
        )}
        {design.decoration === 'accent-line' && (
           <div className={`absolute w-24 h-2 bg-blue-500 rounded-full ${design.verticalAlign === 'bottom' ? 'top-8' : 'bottom-8'} ${design.textAlign === 'center' ? 'left-1/2 -translate-x-1/2' : design.textAlign === 'right' ? 'right-8' : 'left-8'}`}></div>
        )}
        {design.decoration === 'corner-shape' && (
           <div className="absolute top-0 right-0 w-24 h-24 bg-gradient-to-bl from-blue-500/50 to-transparent rounded-bl-full pointer-events-none"></div>
        )}
      </div>

      {/* Main Content Layer */}
      <div className={`relative z-10 h-full p-6 flex flex-col transition-all ${getContainerStyle()}`}>

        {/* Slide Number Badge */}
        <div className="absolute top-4 left-4 z-20">
             <div className="bg-blue-500/20 text-blue-300 text-[10px] font-bold px-2 py-1 rounded backdrop-blur-sm border border-blue-500/10">
                SLIDE {slide.slide_number}
             </div>
        </div>

        {/* Edit Button (Top Right) */}
        {!readOnly && (
            <button 
                onClick={() => setShowSettings(!showSettings)}
                className={`absolute top-4 right-4 z-20 p-2 rounded-lg backdrop-blur-md transition-all ${showSettings ? 'bg-blue-600 text-white' : 'bg-white/10 text-white hover:bg-white/20'}`}
            >
                {showSettings ? <X size={16} /> : <Settings2 size={16} />}
            </button>
        )}

        {/* Text Area */}
        <div className="w-full relative z-10">
            {readOnly ? (
                <>
                    <h2 
                        className={`mb-3 leading-tight transition-all ${getTextStyle(true)}`}
                        style={{ color: design.textColor }}
                    >
                        {slide.headline}
                    </h2>
                    <p 
                        className={`leading-relaxed opacity-90 transition-all ${getTextStyle(false)}`}
                        style={{ color: design.textColor }}
                    >
                        {slide.sub_headline}
                    </p>
                </>
            ) : (
                <>
                    <textarea 
                        value={slide.headline}
                        onChange={(e) => onUpdateSlide(slide.slide_number, 'headline', e.target.value)}
                        className={`bg-transparent border border-transparent hover:border-white/10 focus:border-blue-500/50 rounded w-full resize-none focus:outline-none focus:bg-slate-900/40 p-1 mb-2 transition-all ${getTextStyle(true)}`}
                        style={{ color: design.textColor }}
                        rows={2}
                        placeholder="Headline"
                    />
                    <textarea 
                        value={slide.sub_headline}
                        onChange={(e) => onUpdateSlide(slide.slide_number, 'sub_headline', e.target.value)}
                        className={`bg-transparent border border-transparent hover:border-white/10 focus:border-blue-500/50 rounded w-full resize-none focus:outline-none focus:bg-slate-900/40 p-1 transition-all ${getTextStyle(false)}`}
                        style={{ color: design.textColor }}
                        rows={4}
                        placeholder="Sub-headline"
                    />
                </>
            )}
        </div>
      </div>

      {/* Settings Overlay Panel */}
      {showSettings && !readOnly && (
        <div className="absolute bottom-0 left-0 right-0 bg-slate-900/95 backdrop-blur-xl border-t border-slate-700 p-4 z-30 animate-in slide-in-from-bottom-10 duration-200 shadow-2xl">
            <div className="grid grid-cols-5 gap-4">

                {/* 1. Alignment */}
                <div className="space-y-2 col-span-1">
                    <label className="text-[10px] text-slate-500 font-bold uppercase block text-center">Layout</label>
                    <div className="grid grid-cols-3 gap-1">
                        {[
                            { icon: ArrowUpToLine, v: 'top' },
                            { icon: MoveVertical, v: 'center' },
                            { icon: ArrowDownToLine, v: 'bottom' }
                        ].map((btn) => (
                             <button 
                                key={btn.v}
                                onClick={() => onUpdateDesign(slide.slide_number, 'verticalAlign', btn.v)}
                                className={`p-1.5 rounded flex justify-center ${design.verticalAlign === btn.v ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400 hover:bg-slate-700'}`}
                             >
                                <btn.icon size={12} />
                             </button>
                        ))}
                         {[
                            { icon: AlignLeft, v: 'left' },
                            { icon: AlignCenter, v: 'center' },
                            { icon: AlignRight, v: 'right' }
                        ].map((btn) => (
                             <button 
                                key={btn.v}
                                onClick={() => onUpdateDesign(slide.slide_number, 'textAlign', btn.v)}
                                className={`p-1.5 rounded flex justify-center ${design.textAlign === btn.v ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400 hover:bg-slate-700'}`}
                             >
                                <btn.icon size={12} />
                             </button>
                        ))}
                    </div>
                </div>

                {/* 2. Color & Overlay */}
                <div className="space-y-2 col-span-1">
                     <label className="text-[10px] text-slate-500 font-bold uppercase block text-center">Color</label>
                     <div className="flex flex-col gap-2 items-center">
                        <div className="relative group w-full">
                            <input 
                                type="color" 
                                value={design.textColor}
                                onChange={(e) => onUpdateDesign(slide.slide_number, 'textColor', e.target.value)}
                                className="opacity-0 absolute inset-0 w-full h-full cursor-pointer"
                            />
                            <div className="w-full h-6 rounded border border-slate-600 flex items-center justify-center text-[10px]" style={{ backgroundColor: design.textColor, color: design.textColor === '#ffffff' ? '#000' : '#fff' }}>
                                Text
                            </div>
                        </div>
                        <input 
                            type="range" 
                            min="0" 
                            max="90" 
                            value={design.overlayOpacity} 
                            onChange={(e) => onUpdateDesign(slide.slide_number, 'overlayOpacity', parseInt(e.target.value))}
                            className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                            title="Overlay Opacity"
                        />
                     </div>
                </div>

                {/* 3. Typography Size */}
                <div className="space-y-2 col-span-1">
                    <label className="text-[10px] text-slate-500 font-bold uppercase block text-center">Size</label>
                    <div className="flex flex-col gap-1">
                        {['small', 'medium', 'large', 'xl'].map(s => (
                            <button
                                key={s}
                                onClick={() => onUpdateDesign(slide.slide_number, 'fontSize', s)}
                                className={`text-[10px] py-1 rounded border ${design.fontSize === s ? 'bg-blue-600 border-blue-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-500'}`}
                            >
                                {s.toUpperCase()}
                            </button>
                        ))}
                    </div>
                </div>

                {/* 4. Effects */}
                <div className="space-y-2 col-span-1">
                    <label className="text-[10px] text-slate-500 font-bold uppercase block text-center">Effect</label>
                    <div className="flex flex-col gap-1">
                         {[
                            { id: 'none', label: 'None' },
                            { id: 'shadow', label: 'Shadow' },
                            { id: 'neon', label: 'Neon' },
                            { id: 'bg-highlight', label: 'Box' }
                        ].map(eff => (
                            <button
                                key={eff.id}
                                onClick={() => onUpdateDesign(slide.slide_number, 'textEffect', eff.id)}
                                className={`text-[10px] py-1 rounded border ${design.textEffect === eff.id ? 'bg-blue-600 border-blue-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-500'}`}
                            >
                                {eff.label}
                            </button>
                        ))}
                    </div>
                </div>

                 {/* 5. Decoration */}
                 <div className="space-y-2 col-span-1">
                    <label className="text-[10px] text-slate-500 font-bold uppercase block text-center">Decor</label>
                     <div className="grid grid-cols-2 gap-1">
                         {[
                            { id: 'none', icon: X },
                            { id: 'circle', icon: Sparkles },
                            { id: 'square', icon: BoxSelect },
                            { id: 'corner-shape', icon: Layers }
                        ].map(d => (
                            <button
                                key={d.id}
                                onClick={() => onUpdateDesign(slide.slide_number, 'decoration', d.id)}
                                className={`p-1.5 rounded flex justify-center items-center ${design.decoration === d.id ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400 hover:bg-slate-700'}`}
                                title={d.id}
                            >
                                <d.icon size={12} />
                            </button>
                        ))}
                     </div>
                </div>
            </div>

            {/* Prompt Edit Area */}
             <div className="mt-3 pt-3 border-t border-slate-800">
                <div className="flex gap-2">
                    <div className="flex-1">
                        <input
                            value={slide.visual_description}
                            onChange={(e) => onUpdateSlide(slide.slide_number, 'visual_description', e.target.value)}
                            className="w-full bg-slate-950 text-xs text-slate-400 border border-slate-800 rounded px-2 py-1 focus:border-blue-500 focus:outline-none"
                            placeholder="Prompt..."
                        />
                    </div>
                    <button
                        onClick={() => onGenerateImage(slide.slide_number)}
                        disabled={isGeneratingImage}
                        className="bg-blue-600 hover:bg-blue-500 text-white p-1.5 rounded disabled:opacity-50"
                        title="Regenerate Image"
                    >
                        {isGeneratingImage ? <RefreshCw size={14} className="animate-spin" /> : <Image size={14} />}
                    </button>
                </div>
             </div>
        </div>
      )}
    </div>
  );
};

export default SlideCard;

import React, { useState, useEffect } from 'react';
import { Sparkles, Wand2, Layers, Download, Palette, Users, Type, Save, Archive, Play, Trash2, Edit3, Grid, Plus, Minus } from 'lucide-react';
import { generateCarouselScript, generateSlideImage } from './services/geminiService';
import { CarouselResponse, GenerationStatus, ViewMode, Slide, SlideDesign } from './types';
import SlideCard from './components/SlideCard';

const VISUAL_STYLES = [
  "Minimalist & Clean",
  "Cyberpunk Neon",
  "Corporate Memphis",
  "Dark Mode Gradient",
  "Abstract Geometric",
  "Vintage Paper Texture",
  "3D Claymorphism",
  "Futuristic Tech",
  "Glassmorphism",
  "Brutalism",
  "Retro Pop Art",
  "Swiss International",
  "Doodle & Sketch",
  "Nature & Organic"
];

function App() {
  // --- View State ---
  const [activeView, setActiveView] = useState<ViewMode>('create');

  // --- Input State ---
  const [topic, setTopic] = useState('');
  const [visualStyle, setVisualStyle] = useState(VISUAL_STYLES[0]);
  const [targetAudience, setTargetAudience] = useState('');
  const [slideCount, setSlideCount] = useState<number>(5);

  // --- Data State ---
  const [currentCarousel, setCurrentCarousel] = useState<CarouselResponse | null>(null);
  const [generatedImages, setGeneratedImages] = useState<Record<string, Record<number, string>>>({}); // { carouselId: { slideNum: base64 } }
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [imageLoadingState, setImageLoadingState] = useState<Record<number, boolean>>({});

  // --- History State ---
  const [library, setLibrary] = useState<CarouselResponse[]>([]);

  // Load library from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('carousel_library');
    // NOTE: We don't load images from local storage to prevent quotas crashes. 
    // In a real app, these would be URLs from a CDN.
    if (saved) {
      try {
        setLibrary(JSON.parse(saved));
      } catch (e) { console.error("Failed to load library", e); }
    }
  }, []);

  // Save library when it changes
  useEffect(() => {
    try {
        localStorage.setItem('carousel_library', JSON.stringify(library));
    } catch (e) {
        console.error("Failed to save library to local storage (likely quota exceeded)", e);
    }
  }, [library]);

  // --- Actions ---

  const handleGenerateScript = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic || !targetAudience) return;

    setStatus(GenerationStatus.GENERATING_SCRIPT);

    try {
      const data = await generateCarouselScript(topic, visualStyle, targetAudience, slideCount);
      setCurrentCarousel(data);
      setStatus(GenerationStatus.COMPLETE);
      setActiveView('editor');
    } catch (error) {
      console.error(error);
      setStatus(GenerationStatus.ERROR);
    }
  };

  const handleGenerateImage = async (slideNumber: number) => {
    if (!currentCarousel) return;

    const slide = currentCarousel.slides.find(s => s.slide_number === slideNumber);
    if (!slide) return;

    setImageLoadingState(prev => ({ ...prev, [slideNumber]: true }));

    try {
      const base64Image = await generateSlideImage(slide.visual_description, currentCarousel.carousel_metadata.visual_style);
      setGeneratedImages(prev => ({
        ...prev,
        [currentCarousel.id]: {
            ...(prev[currentCarousel.id] || {}),
            [slideNumber]: base64Image
        }
      }));
    } catch (error) {
      console.error("Failed to generate image for slide " + slideNumber, error);
      alert("Failed to generate image. Please try again.");
    } finally {
      setImageLoadingState(prev => ({ ...prev, [slideNumber]: false }));
    }
  };

  const handleGenerateAllImages = async () => {
      if (!currentCarousel) return;
      const promises = currentCarousel.slides.map(slide => handleGenerateImage(slide.slide_number));
      await Promise.all(promises);
  };

  const handleUpdateSlide = (slideNumber: number, field: keyof Slide, value: any) => {
      if (!currentCarousel) return;

      const updatedSlides = currentCarousel.slides.map(slide => {
          if (slide.slide_number === slideNumber) {
              return { ...slide, [field]: value };
          }
          return slide;
      });

      setCurrentCarousel({ ...currentCarousel, slides: updatedSlides });
  };

  const handleUpdateDesign = (slideNumber: number, field: keyof SlideDesign, value: any) => {
    if (!currentCarousel) return;

    const updatedSlides = currentCarousel.slides.map(slide => {
        if (slide.slide_number === slideNumber) {
            return { 
                ...slide, 
                design: {
                    ...slide.design,
                    [field]: value
                }
            };
        }
        return slide;
    });

    setCurrentCarousel({ ...currentCarousel, slides: updatedSlides });
  };

  const saveToLibrary = () => {
      if (!currentCarousel) return;

      // Check if already exists
      const exists = library.find(c => c.id === currentCarousel.id);
      let newLibrary;
      if (exists) {
          newLibrary = library.map(c => c.id === currentCarousel.id ? currentCarousel : c);
      } else {
          newLibrary = [currentCarousel, ...library];
      }
      setLibrary(newLibrary);
      alert('Saved to Library!');
  };

  const loadFromLibrary = (carousel: CarouselResponse) => {
      setCurrentCarousel(carousel);
      setActiveView('editor');
  };

  const deleteFromLibrary = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (confirm('Are you sure you want to delete this carousel?')) {
          setLibrary(prev => prev.filter(c => c.id !== id));
          // Clean up images from state
          const newImages = { ...generatedImages };
          delete newImages[id];
          setGeneratedImages(newImages);

          if (currentCarousel?.id === id) {
              setCurrentCarousel(null);
              setActiveView('create');
          }
      }
  };

  const exportJSON = () => {
      if (!currentCarousel) return;
      // We also want to export images if they exist, to make it a true backup
      const exportData = {
          ...currentCarousel,
          _images: generatedImages[currentCarousel.id] || {}
      };

      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", `carousel-${currentCarousel.carousel_metadata.topic.replace(/\s+/g, '-').toLowerCase()}.json`);
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
  };

  // --- Render Helpers ---

  const renderNav = () => (
      <nav className="flex flex-col space-y-2 w-full">
          <button 
            onClick={() => setActiveView('create')}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${activeView === 'create' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
          >
              <Wand2 className="w-5 h-5" /> Create
          </button>
          <button 
            onClick={() => setActiveView('editor')}
            disabled={!currentCarousel}
