  User
} from 'lucide-react';

interface SlideCardProps {
  slide: Slide;
  imageData?: string;
  isGeneratingImage: boolean;
  onGenerateImage: (slideNumber: number) => void;
  onUpdateSlide: (slideNumber: number, field: keyof Slide, value: any) => void;
  onUpdateDesign: (slideNumber: number, field: keyof SlideDesign, value: any) => void;
  readOnly?: boolean;
  language?: 'en' | 'ar';
}

const SlideCard: React.FC<SlideCardProps> = ({ 
  slide, 
  imageData, 
  isGeneratingImage, 
  onGenerateImage,
  onUpdateSlide,
  onUpdateDesign,
  readOnly = false,
  language = 'en'
}) => {
  const [showSettings, setShowSettings] = useState(false);
  const design = slide.design;
  const isRTL = language === 'ar';

  const headlineRef = useRef<HTMLTextAreaElement>(null);
  const subheadRef = useRef<HTMLTextAreaElement>(null);

  // Auto-resize textareas
  const autoResize = (elem: HTMLTextAreaElement | null) => {
    if (elem) {
        elem.style.height = 'auto';
        elem.style.height = elem.scrollHeight + 'px';
    }
  };

  useEffect(() => {
    if (!readOnly) {
        autoResize(headlineRef.current);
        autoResize(subheadRef.current);
    }
  }, [slide.headline, slide.sub_headline, readOnly]);


  const getTextStyle = (isHeadline: boolean) => {
    const baseSize = isHeadline ? 'font-bold' : 'font-medium';

    let sizeClass = isHeadline ? 'text-2xl' : 'text-sm';
    if (design.fontSize === 'small') sizeClass = isHeadline ? 'text-xl' : 'text-xs';
    if (design.fontSize === 'large') sizeClass = isHeadline ? 'text-3xl' : 'text-base';
    if (design.fontSize === 'xl') sizeClass = isHeadline ? 'text-4xl' : 'text-lg';

    let effectClass = '';
    if (design.textEffect === 'shadow') effectClass = 'drop-shadow-lg shadow-black';
    if (design.textEffect === 'neon') effectClass = 'drop-shadow-[0_0_5px_rgba(255,255,255,0.8)]';
    if (design.textEffect === 'outline') effectClass = 'outline-text'; 
    if (design.textEffect === 'bg-highlight') effectClass = 'bg-black/50 px-2 rounded box-decoration-clone';

    return `${baseSize} ${sizeClass} ${effectClass} ${isRTL ? 'text-right' : 'text-left'}`;
  };

  // Character Counts
  const MAX_HEADLINE = 60;
  const MAX_SUBHEAD = 120;

  const renderCounter = (current: number, max: number) => {
      const isNearLimit = current > max * 0.9;
      return (
          <span className={`text-[9px] absolute right-0 -bottom-4 ${isNearLimit ? 'text-red-400' : 'text-slate-500'}`}>
              {current}/{max}
          </span>
      );
  };

  return (
    <div className="flex-shrink-0 w-[340px] h-[450px] relative rounded-xl overflow-hidden shadow-2xl bg-slate-800 border border-slate-700 group transition-all duration-300">

      {/* Background Image Layer */}
      <div className="absolute inset-0 z-0 bg-slate-900">
        {imageData ? (
          <img 
            src={imageData} 
            alt={`Slide ${slide.slide_number} visual`} 
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center text-slate-700">
            <div className="text-center p-4">
              <Image className="w-12 h-12 mx-auto mb-2 opacity-50" />
              <p className="text-xs">Visual description provided</p>
            </div>
          </div>
        )}

        <div 
          className="absolute inset-0 pointer-events-none transition-all duration-300"
          style={{ backgroundColor: `rgba(15, 23, 42, ${design.overlayOpacity / 100})` }}
        ></div>

        {/* Decorations */}
        {design.decoration === 'circle' && (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-48 h-48 border-4 border-white/20 rounded-full pointer-events-none"></div>
        )}
        {design.decoration === 'square' && (
          <div className="absolute top-4 right-4 bottom-4 left-4 border-2 border-white/20 pointer-events-none"></div>
        )}
        {design.decoration === 'accent-line' && (
           <div className="absolute top-10 left-10 w-20 h-1 bg-blue-500 pointer-events-none"></div>
        )}
        {design.decoration === 'corner-shape' && (
           <div className="absolute top-0 right-0 w-24 h-24 bg-gradient-to-bl from-blue-500/50 to-transparent rounded-bl-full pointer-events-none"></div>
        )}
      </div>

      {/* Main Content Layer - Absolute Positioning */}
      <div 
        className="absolute z-10 w-[85%] transition-all duration-100 ease-out flex flex-col gap-2"
        style={{ 
            top: `${design.yPosition}%`, 
            left: `${design.xPosition}%`,
            transform: 'translate(-50%, 0)', // Center horizontally relative to left point
            direction: isRTL ? 'rtl' : 'ltr'
        }}
      >
            {readOnly ? (
                <>
                    <h2 
                        className={`leading-tight whitespace-pre-wrap ${getTextStyle(true)}`}
                        style={{ color: design.textColor }}
