                            value={slide.headline}
                            onChange={(e) => onUpdateSlide(slide.slide_number, 'headline', e.target.value)}
                            className={`bg-transparent border border-dashed border-white/20 hover:border-blue-500/50 rounded w-full resize-none focus:outline-none focus:bg-slate-900/40 p-1 overflow-hidden ${getTextStyle(true)}`}
                            style={{ color: design.textColor }}
                            rows={1}
                            placeholder={isRTL ? "العنوان الرئيسي" : "Headline"}
                        />
                        {renderCounter(slide.headline.length, MAX_HEADLINE)}
                    </div>

                    <div className="relative w-full">
                        <textarea 
                            ref={subheadRef}
                            value={slide.sub_headline}
                            onChange={(e) => onUpdateSlide(slide.slide_number, 'sub_headline', e.target.value)}
                            className={`bg-transparent border border-dashed border-white/20 hover:border-blue-500/50 rounded w-full resize-none focus:outline-none focus:bg-slate-900/40 p-1 overflow-hidden ${getTextStyle(false)}`}
                            style={{ color: design.textColor }}
                            rows={1}
                            placeholder={isRTL ? "العنوان الفرعي" : "Sub-headline"}
                        />
                        {renderCounter(slide.sub_headline.length, MAX_SUBHEAD)}
                    </div>
                </>
            )}
      </div>

      {/* Slide Number Badge */}
      <div className={`absolute top-4 ${isRTL ? 'right-4' : 'left-4'} z-20`}>
             <div className="bg-blue-500/20 text-blue-300 text-[10px] font-bold px-2 py-1 rounded backdrop-blur-sm border border-blue-500/10">
                {slide.slide_number}
             </div>
      </div>

      {/* Edit Button */}
      {!readOnly && (
            <button 
                onClick={() => setShowSettings(!showSettings)}
                className={`absolute top-4 ${isRTL ? 'left-4' : 'right-4'} z-20 p-2 rounded-lg backdrop-blur-md transition-all ${showSettings ? 'bg-blue-600 text-white' : 'bg-white/10 text-white hover:bg-white/20'}`}
            >
                {showSettings ? <X size={16} /> : <Settings2 size={16} />}
            </button>
      )}

      {/* Settings Overlay Panel */}
      {showSettings && !readOnly && (
        <div className="absolute bottom-0 left-0 right-0 bg-slate-900/95 backdrop-blur-xl border-t border-slate-700 p-4 z-30 animate-in slide-in-from-bottom-10 duration-200 shadow-2xl">
            <div className="grid grid-cols-5 gap-4 mb-4">

                {/* 1. Position Sliders */}
                <div className="space-y-2 col-span-2">
                    <label className="text-[10px] text-slate-500 font-bold uppercase block text-center flex items-center justify-center gap-1">
                        <Move size={10}/> Position
                    </label>
                    <div className="flex flex-col gap-3 px-2">
                        <div className="flex items-center gap-2">
                             <span className="text-[10px] text-slate-400 w-3">X</span>
                             <input 
                                type="range" min="0" max="100" 
                                value={design.xPosition} 
                                onChange={(e) => onUpdateDesign(slide.slide_number, 'xPosition', parseInt(e.target.value))}
                                className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                            />
                        </div>
                        <div className="flex items-center gap-2">
                             <span className="text-[10px] text-slate-400 w-3">Y</span>
                             <input 
                                type="range" min="0" max="100" 
                                value={design.yPosition} 
                                onChange={(e) => onUpdateDesign(slide.slide_number, 'yPosition', parseInt(e.target.value))}
                                className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                            />
                        </div>
                    </div>
                </div>

                {/* 2. Color & Overlay */}
                <div className="space-y-2 col-span-1">
                     <label className="text-[10px] text-slate-500 font-bold uppercase block text-center">Style</label>
                     <div className="flex flex-col gap-2 items-center">
                        <div className="relative group w-full">
                            <input 
                                type="color" 
                                value={design.textColor}
                                onChange={(e) => onUpdateDesign(slide.slide_number, 'textColor', e.target.value)}
                                className="opacity-0 absolute inset-0 w-full h-full cursor-pointer"
                            />
                            <div className="w-full h-6 rounded border border-slate-600 flex items-center justify-center text-[10px]" style={{ backgroundColor: design.textColor, color: design.textColor === '#ffffff' ? '#000' : '#fff' }}>
                                A
                            </div>
                        </div>
                        <input 
                            type="range" min="0" max="90" 
                            value={design.overlayOpacity} 
                            onChange={(e) => onUpdateDesign(slide.slide_number, 'overlayOpacity', parseInt(e.target.value))}
                            className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                            title="Opacity"
                        />
                     </div>
                </div>

                {/* 3. Character Toggle */}
                <div className="space-y-2 col-span-1">
                     <label className="text-[10px] text-slate-500 font-bold uppercase block text-center">Char</label>
                     <button
                        onClick={() => onUpdateSlide(slide.slide_number, 'include_character', !slide.include_character)}
                        className={`w-full h-12 rounded flex items-center justify-center border ${slide.include_character ? 'bg-blue-600 border-blue-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-500'}`}
                        title="Include Character in Visual"
                     >
                         <User size={16} />
                     </button>
                </div>

                 {/* 4. Decoration */}
                 <div className="space-y-2 col-span-1">
                    <label className="text-[10px] text-slate-500 font-bold uppercase block text-center">Decor</label>
                     <div className="grid grid-cols-1 gap-1">
                         <button onClick={() => onUpdateDesign(slide.slide_number, 'decoration', design.decoration === 'none' ? 'circle' : 'none')} className="text-[10px] p-1 bg-slate-800 rounded border border-slate-700 text-slate-300">
                             {design.decoration === 'none' ? 'Add' : 'Rm'}
                         </button>
                         <button onClick={() => onUpdateDesign(slide.slide_number, 'textEffect', design.textEffect === 'none' ? 'shadow' : 'none')} className="text-[10px] p-1 bg-slate-800 rounded border border-slate-700 text-slate-300">
                             FX
                         </button>
                     </div>
                </div>
            </div>

            {/* Prompt Edit Area */}
             <div className="mt-3 pt-3 border-t border-slate-800">
                <div className="flex gap-2">
                    <div className="flex-1">
                        <input
                            value={slide.visual_description}
                            onChange={(e) => onUpdateSlide(slide.slide_number, 'visual_description', e.target.value)}
                            className="w-full bg-slate-950 text-xs text-slate-400 border border-slate-800 rounded px-2 py-1 focus:border-blue-500 focus:outline-none"
                            placeholder="Prompt..."
                        />
                    </div>
                    <button
                        onClick={() => onGenerateImage(slide.slide_number)}
                        disabled={isGeneratingImage}
                        className="bg-blue-600 hover:bg-blue-500 text-white p-1.5 rounded disabled:opacity-50"
                        title="Regenerate Image"
                    >
                        {isGeneratingImage ? <RefreshCw size={14} className="animate-spin" /> : <Image size={14} />}
                    </button>
                </div>
             </div>
        </div>
      )}
    </div>
  );
};

export default SlideCard;

import React, { useState, useEffect } from 'react';
import { Sparkles, Wand2, Layers, Download, Palette, Users, Type, Save, Archive, Play, Trash2, Edit3, Grid, Globe, UserPlus, Zap } from 'lucide-react';
import { generateCarouselScript, generateSlideImage, generateIdeas } from './services/geminiService';
import { CarouselResponse, GenerationStatus, ViewMode, Slide, SlideDesign } from './types';
import SlideCard from './components/SlideCard';

const VISUAL_STYLES = [
  "Minimalist & Clean",
  "Cyberpunk Neon",
  "Corporate Memphis",
  "Dark Mode Gradient",
  "Abstract Geometric",
  "Vintage Paper Texture",
  "3D Claymorphism",
  "Futuristic Tech",
  "Glassmorphism",
  "Brutalism",
  "Retro Pop Art",
  "Swiss International",
  "Doodle & Sketch",
  "Nature & Organic"
];

function App() {
  // --- View State ---
  const [activeView, setActiveView] = useState<ViewMode>('create');

  // --- Input State ---
  const [topic, setTopic] = useState('');
  const [visualStyle, setVisualStyle] = useState(VISUAL_STYLES[0]);
  const [targetAudience, setTargetAudience] = useState('');
  const [slideCount, setSlideCount] = useState<number>(5);

  // New Input States
  const [language, setLanguage] = useState<'en' | 'ar'>('en');
  const [tone, setTone] = useState('');
  const [dialect, setDialect] = useState(''); // Only for Arabic
  const [mainTheme, setMainTheme] = useState('');
  const [useCharacter, setUseCharacter] = useState(false);
  const [characterDesc, setCharacterDesc] = useState(''); // Editable global prompt

  // --- Data State ---
  const [currentCarousel, setCurrentCarousel] = useState<CarouselResponse | null>(null);
  const [generatedImages, setGeneratedImages] = useState<Record<string, Record<number, string>>>({});
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [imageLoadingState, setImageLoadingState] = useState<Record<number, boolean>>({});

  // --- History State ---
  const [library, setLibrary] = useState<CarouselResponse[]>([]);

  // Load library from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('carousel_library');
    if (saved) {
      try {
        setLibrary(JSON.parse(saved));
      } catch (e) { console.error("Failed to load library", e); }
    }
  }, []);

  // Save library when it changes
  useEffect(() => {
    try {
        localStorage.setItem('carousel_library', JSON.stringify(library));
    } catch (e) {
        console.error("Failed to save library (quota exceeded)", e);
    }
  }, [library]);

  // --- Actions ---

  const handleAutoGenerateIdeas = async () => {
     if (!mainTheme) {
         alert("Please enter a Main Theme first.");
         return;
     }
     setStatus(GenerationStatus.GENERATING_IDEAS);
     try {
         const idea = await generateIdeas(mainTheme, language);
         setTopic(idea.topic);
         setTargetAudience(idea.audience);
     } catch (e) {
         console.error(e);
     } finally {
         setStatus(GenerationStatus.IDLE);
     }
  };

  const handleGenerateScript = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic || !targetAudience) return;

    setStatus(GenerationStatus.GENERATING_SCRIPT);

    try {
      const data = await generateCarouselScript(
          topic, visualStyle, targetAudience, slideCount, 
          language, tone, dialect, useCharacter
      );

      // If user wants a character, populate the state with what the AI came up with
      if (useCharacter && data.carousel_metadata.character_description) {
          setCharacterDesc(data.carousel_metadata.character_description);
      }

      setCurrentCarousel(data);
      setStatus(GenerationStatus.COMPLETE);
      setActiveView('editor');
    } catch (error) {
      console.error(error);
      setStatus(GenerationStatus.ERROR);
    }
  };

  const handleGenerateImage = async (slideNumber: number) => {
    if (!currentCarousel) return;

    const slide = currentCarousel.slides.find(s => s.slide_number === slideNumber);
    if (!slide) return;

    setImageLoadingState(prev => ({ ...prev, [slideNumber]: true }));

    try {
      // Pass the potentially edited global character description if applicable
      const metadata = { 
          ...currentCarousel.carousel_metadata, 
          character_description: characterDesc || currentCarousel.carousel_metadata.character_description 
      };

      const base64Image = await generateSlideImage(slide, metadata);
      setGeneratedImages(prev => ({
        ...prev,
        [currentCarousel.id]: {
            ...(prev[currentCarousel.id] || {}),
            [slideNumber]: base64Image
        }
      }));
    } catch (error) {
      console.error("Failed to generate image", error);
      alert("Failed to generate image. Please try again.");
    } finally {
      setImageLoadingState(prev => ({ ...prev, [slideNumber]: false }));
    }
  };

  const handleGenerateAllImages = async () => {
      if (!currentCarousel) return;
      const promises = currentCarousel.slides.map(slide => handleGenerateImage(slide.slide_number));
      await Promise.all(promises);
  };

  const handleUpdateSlide = (slideNumber: number, field: keyof Slide, value: any) => {
      if (!currentCarousel) return;
      const updatedSlides = currentCarousel.slides.map(slide => {
          if (slide.slide_number === slideNumber) {
              return { ...slide, [field]: value };
          }
          return slide;
      });
      setCurrentCarousel({ ...currentCarousel, slides: updatedSlides });
  };

  const handleUpdateDesign = (slideNumber: number, field: keyof SlideDesign, value: any) => {
    if (!currentCarousel) return;
    const updatedSlides = currentCarousel.slides.map(slide => {
        if (slide.slide_number === slideNumber) {
            return { 
                ...slide, 
                design: { ...slide.design, [field]: value }
            };
        }
        return slide;
    });
    setCurrentCarousel({ ...currentCarousel, slides: updatedSlides });
  };

  const saveToLibrary = () => {
      if (!currentCarousel) return;
      // Save the potentially edited character description back to metadata
      const carouselToSave = {
          ...currentCarousel,
          carousel_metadata: {
              ...currentCarousel.carousel_metadata,
              character_description: characterDesc
          }
      };

      const exists = library.find(c => c.id === carouselToSave.id);
      let newLibrary;
      if (exists) {
          newLibrary = library.map(c => c.id === carouselToSave.id ? carouselToSave : c);
      } else {
          newLibrary = [carouselToSave, ...library];
      }
      setLibrary(newLibrary);
      alert('Saved to Library!');
  };

  const loadFromLibrary = (carousel: CarouselResponse) => {
      setCurrentCarousel(carousel);
      setLanguage(carousel.carousel_metadata.language as 'en' | 'ar');
      setCharacterDesc(carousel.carousel_metadata.character_description || '');
      setActiveView('editor');
  };

  const deleteFromLibrary = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (confirm('Are you sure you want to delete this carousel?')) {
          setLibrary(prev => prev.filter(c => c.id !== id));
          const newImages = { ...generatedImages };
          delete newImages[id];
          setGeneratedImages(newImages);
          if (currentCarousel?.id === id) {
              setCurrentCarousel(null);
              setActiveView('create');
          }
      }
  };

  const exportJSON = () => {
      if (!currentCarousel) return;
      const exportData = {
          ...currentCarousel,
          _images: generatedImages[currentCarousel.id] || {}
      };
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", `carousel-${currentCarousel.carousel_metadata.topic.replace(/\s+/g, '-').toLowerCase()}.json`);
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
  };

  // --- Render Helpers ---

  const renderNav = () => (
      <nav className="flex flex-col space-y-2 w-full">
          <button onClick={() => setActiveView('create')} className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${activeView === 'create' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}>
              <Wand2 className="w-5 h-5" /> Create
          </button>
          <button onClick={() => setActiveView('editor')} disabled={!currentCarousel} className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${activeView === 'editor' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50' : 'text-slate-400 hover:bg-slate-800 hover:text-white'} ${!currentCarousel ? 'opacity-50 cursor-not-allowed' : ''}`}>
              <Edit3 className="w-5 h-5" /> Editor
          </button>
          <button onClick={() => setActiveView('library')} className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${activeView === 'library' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}>
              <Archive className="w-5 h-5" /> Library
          </button>
      </nav>
  );

  return (
    <div className={`min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-blue-500/30 flex ${language === 'ar' ? 'font-[sans-serif]' : ''}`}>

      {/* Sidebar */}
      <aside className="w-64 border-r border-slate-800 bg-slate-900/50 backdrop-blur-xl h-screen sticky top-0 flex flex-col p-6 shrink-0 z-30">
         <div className="flex items-center gap-2 mb-8">
            <div className="w-8 h-8 rounded-lg bg-blue-600 flex items-center justify-center">
              <Layers className="w-5 h-5 text-white" />
            </div>
            <h1 className="font-bold text-lg tracking-tight text-white">Carousel<span className="text-blue-500">AI</span></h1>
         </div>

         {renderNav()}

         <div className="mt-auto pt-6 border-t border-slate-800">
            <div className="text-xs text-slate-500 mb-2">Recent Projects</div>
            <div className="space-y-1">
                {library.slice(0, 3).map(item => (
                    <button key={item.id} onClick={() => loadFromLibrary(item)} className="block w-full text-left truncate text-sm text-slate-400 hover:text-white py-1">
                        {item.carousel_metadata.topic}
                    </button>
                ))}
            </div>
         </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto h-screen p-8 bg-slate-950 relative" dir={language === 'ar' ? 'rtl' : 'ltr'}>

        {/* Language Switcher (Top Right) */}
        <div className="absolute top-8 right-8 z-40 flex gap-2">
            <button 
                onClick={() => setLanguage('en')}
                className={`px-3 py-1 rounded-full text-xs font-bold transition-all ${language === 'en' ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400'}`}
            >
                ENG
            </button>
            <button 
                onClick={() => setLanguage('ar')}
                className={`px-3 py-1 rounded-full text-xs font-bold transition-all ${language === 'ar' ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400'}`}
            >
                عربي
            </button>
        </div>

        {/* VIEW: CREATE */}
        {activeView === 'create' && (
            <div className="max-w-3xl mx-auto space-y-8 animate-in fade-in zoom-in-95 duration-500 pb-20">
                <div className="text-center space-y-2 mb-10 mt-10">
                    <h2 className="text-3xl font-bold text-white">{language === 'ar' ? 'لنصنع محتوى فيروسي اليوم' : 'What are we creating today?'}</h2>
                    <p className="text-slate-400">{language === 'ar' ? 'أنشئ كاروسيل احترافي لـ LinkedIn و Instagram في ثوانٍ.' : 'Generate viral LinkedIn & Instagram carousels in seconds.'}</p>
                </div>

                <div className="bg-slate-900 border border-slate-800 rounded-2xl p-8 shadow-xl">
                    <form onSubmit={handleGenerateScript} className="space-y-6">

                        {/* 1. Main Theme & Auto-Gen */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium text-slate-400 flex items-center gap-2">
                                <Globe className="w-4 h-4" /> {language === 'ar' ? 'الموضوع العام' : 'Main Theme'}
                            </label>
                            <div className="flex gap-2">
                                <input
                                    type="text"
                                    value={mainTheme}
                                    onChange={(e) => setMainTheme(e.target.value)}
                                    placeholder={language === 'ar' ? 'مثل: ريادة الأعمال، الذكاء الاصطناعي...' : 'e.g. Entrepreneurship, AI, Fitness...'}
                                    className="flex-1 bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all"
                                />
                                <button
                                    type="button"
                                    onClick={handleAutoGenerateIdeas}
                                    disabled={status === GenerationStatus.GENERATING_IDEAS}
                                    className="bg-blue-600/20 text-blue-400 hover:bg-blue-600/30 px-4 rounded-xl text-sm font-medium transition-colors flex items-center gap-2 whitespace-nowrap"
                                >
                                    {status === GenerationStatus.GENERATING_IDEAS ? <Sparkles className="animate-spin w-4 h-4"/> : <Zap className="w-4 h-4" />}
                                    {language === 'ar' ? 'توليد أفكار' : 'Auto Fill'}
                                </button>
                            </div>
                        </div>

                        {/* 2. Topic & Audience */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                             <div className="space-y-2">
                                <label className="text-sm font-medium text-slate-400 flex items-center gap-2">
                                    <Type className="w-4 h-4" /> {language === 'ar' ? 'عنوان الكاروسيل' : 'Specific Topic'}
                                </label>
                                <input
                                    type="text"
                                    value={topic}
                                    onChange={(e) => setTopic(e.target.value)}
                                    placeholder={language === 'ar' ? '5 طرق لزيادة المبيعات...' : 'e.g. 5 Ways to Scale your SaaS...'}
                                    className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all"
                                    required
                                />
                            </div>

                            <div className="space-y-2">
                                <label className="text-sm font-medium text-slate-400 flex items-center gap-2">
                                    <Users className="w-4 h-4" /> {language === 'ar' ? 'الجمهور المستهدف' : 'Target Audience'}
                                </label>
                                <input
                                    type="text"
                                    value={targetAudience}
                                    onChange={(e) => setTargetAudience(e.target.value)}
                                    placeholder={language === 'ar' ? 'مؤسسي الشركات الناشئة...' : 'e.g. Startup Founders...'}
                                    className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all"
                                    required
                                />
                            </div>
                        </div>

                        {/* 3. Tone & Dialect */}
                        <div className="bg-slate-800/50 p-4 rounded-xl border border-slate-800 space-y-4">
                            <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider">{language === 'ar' ? 'نبرة الصوت واللغة' : 'Tone & Voice'}</h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className="space-y-1">
                                    <label className="text-xs text-slate-400">{language === 'ar' ? 'النبرة (مثل: رسمي، مرح)' : 'Tone (e.g., Professional, Witty)'}</label>
                                    <input
                                        type="text"
                                        value={tone}
                                        onChange={(e) => setTone(e.target.value)}
                                        className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-blue-500"
                                        placeholder={language === 'ar' ? 'تحفيزي، ساخر، جدي...' : 'Motivational, Sarcastic, Educational...'}
                                    />
                                </div>
                                {language === 'ar' && (
                                    <div className="space-y-1">
                                        <label className="text-xs text-slate-400">اللهجة (مثل: فصحى، مصري، خليجي)</label>
                                        <input
                                            type="text"
                                            value={dialect}
                                            onChange={(e) => setDialect(e.target.value)}
                                            className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-blue-500"
                                            placeholder="العربية الفصحى"
                                        />
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* 4. Character Settings */}
                        <div className="bg-slate-800/50 p-4 rounded-xl border border-slate-800 flex items-center justify-between">
                            <div>
                                <h3 className="text-sm font-medium text-white flex items-center gap-2">
                                    <UserPlus className="w-4 h-4 text-blue-400" /> 
                                    {language === 'ar' ? 'توليد شخصية خاصة' : 'Generate Character'}
                                </h3>
                                <p className="text-xs text-slate-500 mt-1">
                                    {language === 'ar' ? 'سيتم إنشاء شخصية متسقة تظهر في الشرائح.' : 'Create a consistent character to appear in your slides.'}
                                </p>
