import { GoogleGenAI, Type, Schema } from "@google/genai";
import { CarouselResponse, Slide } from "../types";

// Initialize Gemini Client
// @ts-ignore - Env variable is injected by the sandbox environment
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

const CAROUSEL_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    carousel_metadata: {
      type: Type.OBJECT,
      properties: {
        topic: { type: Type.STRING },
        visual_style: { type: Type.STRING },
        target_audience: { type: Type.STRING },
        language: { type: Type.STRING, enum: ['en', 'ar'] },
        tone: { type: Type.STRING },
        dialect: { type: Type.STRING },
        character_description: { type: Type.STRING },
      },
      required: ["topic", "visual_style", "target_audience", "character_description"],
    },
    slides: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          slide_number: { type: Type.INTEGER },
          headline: { type: Type.STRING },
          sub_headline: { type: Type.STRING },
          visual_description: { type: Type.STRING },
          layout_hint: { type: Type.STRING },
          include_character: { type: Type.BOOLEAN },
        },
        required: ["slide_number", "headline", "sub_headline", "visual_description", "layout_hint", "include_character"],
      },
    },
  },
  required: ["carousel_metadata", "slides"],
};

export const generateIdeas = async (
    theme: string, 
    language: 'en' | 'ar'
): Promise<{ topic: string, audience: string }> => {
    const model = "gemini-3-flash-preview";
    const langPrompt = language === 'ar' ? 'in Arabic' : 'in English';
    const prompt = `Generate a viral, trending social media topic and a specific target audience based on the theme: "${theme}". Return strictly JSON: { "topic": "...", "audience": "..." } ${langPrompt}.`;

    try {
        const response = await ai.models.generateContent({
            model,
            contents: prompt,
            config: { responseMimeType: "application/json" }
        });
        const text = response.text || "{}";
        return JSON.parse(text);
    } catch (e) {
        console.error("Error generating ideas", e);
        return { topic: "Growth Hacking Strategies", audience: "Startup Founders" };
    }
};

export const generateCarouselScript = async (
  topic: string,
  visualStyle: string,
  targetAudience: string,
  slideCount: number,
  language: 'en' | 'ar',
  tone: string,
  dialect: string,
  useCharacter: boolean
): Promise<CarouselResponse> => {
  const model = "gemini-3-flash-preview";

  const langInstruction = language === 'ar' 
    ? `Language: Arabic (Dialect/Style: ${dialect || 'Modern Standard Arabic'}). Ensure headlines are catchy in Arabic.`
    : `Language: English. Tone: ${tone}.`;

  const characterInstruction = useCharacter
    ? `Create a consistent character description (e.g., "A friendly 3D robot with a blue tie" or "A minimalist line-art business woman"). Populate 'character_description' with this. Set 'include_character' to true for slides where the character interacts with elements.`
    : `Leave 'character_description' empty. Set 'include_character' to false.`;

  const systemInstruction = `
    Role: You are a Senior Social Media Strategist.
    Objective: Generate a viral ${slideCount}-slide carousel.

    ${langInstruction}
    Target Audience: ${targetAudience}
    Tone: ${tone}
    Visual Style: ${visualStyle}

    ${characterInstruction}

    Structure:
    - Slide 1: Hook.
    - Middle: Value.
    - End: CTA.

    Visual Prompting:
    - In 'visual_description', describe the scene. If a character is used, just say "The Character [doing action]".
  `;

  const prompt = `Topic: ${topic}. Slides: ${slideCount}.`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: CAROUSEL_SCHEMA,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response text from Gemini");

    const data = JSON.parse(text);

    // Enrich with Default Design Properties
    const enrichedSlides = data.slides.map((slide: any) => ({
      ...slide,
      character_custom_prompt: "", // Initialize
      design: {
        textColor: '#ffffff',
        overlayOpacity: 40,
        fontSize: 'medium',
        textAlign: language === 'ar' ? 'right' : 'left', // Initialize based on language
        xPosition: 50, // Center
        yPosition: 10, // Top area
        textEffect: 'shadow',
        decoration: 'none'
      }
    }));

    // Ensure metadata has all fields
    data.carousel_metadata.language = language;
    data.carousel_metadata.tone = tone;
    data.carousel_metadata.dialect = dialect;

    return {
        ...data,
        slides: enrichedSlides,
        id: crypto.randomUUID(),
        createdAt: Date.now()
    } as CarouselResponse;

  } catch (error) {
    console.error("Error generating script:", error);
    throw error;
  }
};

export const generateSlideImage = async (
  slide: Slide,
  metadata: any
): Promise<string> => {
  const model = "gemini-2.5-flash-image";

  let characterPromptPart = "";
  // Logic: Use per-slide custom prompt if available, otherwise use global description
  if (slide.include_character) {
      const charDesc = slide.character_custom_prompt || metadata.character_description;
      if (charDesc) {
         characterPromptPart = `Character Reference: ${charDesc}. The character is visible in this image.`;
      }
  }

  // Construct a prompt optimized for image generation
  const imagePrompt = `
    Create a social media background image (Aspect Ratio 4:5 Vertical).
    Style: ${metadata.visual_style}.
    Scene: ${slide.visual_description}.
    ${characterPromptPart}
    Constraint: NO TEXT in the image. High quality, aesthetic, clean background.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: { parts: [{ text: imagePrompt }] },
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
           return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
    }
    throw new Error("No image data found");
  } catch (error) {
    console.error("Error generating image:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Slide, SlideDesign } from '../types';
import { 
  Image, RefreshCw, Settings2, X, Move,
  Palette, BoxSelect, Sparkles, Layers,
  User, AlignLeft, AlignCenter, AlignRight
} from 'lucide-react';

interface SlideCardProps {
  slide: Slide;
  imageData?: string;
  isGeneratingImage: boolean;
  onGenerateImage: (slideNumber: number) => void;
  onUpdateSlide: (slideNumber: number, field: keyof Slide, value: any) => void;
  onUpdateDesign: (slideNumber: number, field: keyof SlideDesign, value: any) => void;
  readOnly?: boolean;
  language?: 'en' | 'ar';
}

const SlideCard: React.FC<SlideCardProps> = ({ 
  slide, 
  imageData, 
  isGeneratingImage, 
  onGenerateImage,
  onUpdateSlide,
  onUpdateDesign,
  readOnly = false,
  language = 'en'
}) => {
  const [showSettings, setShowSettings] = useState(false);
  const design = slide.design;
  const isRTL = language === 'ar';

  const headlineRef = useRef<HTMLTextAreaElement>(null);
  const subheadRef = useRef<HTMLTextAreaElement>(null);

  // Auto-resize textareas
  const autoResize = (elem: HTMLTextAreaElement | null) => {
    if (elem) {
        elem.style.height = 'auto';
        elem.style.height = elem.scrollHeight + 'px';
    }
  };

  useEffect(() => {
    if (!readOnly) {
        autoResize(headlineRef.current);
        autoResize(subheadRef.current);
    }
  }, [slide.headline, slide.sub_headline, readOnly]);


  const getTextStyle = (isHeadline: boolean) => {
    const baseSize = isHeadline ? 'font-bold' : 'font-medium';

    let sizeClass = isHeadline ? 'text-2xl' : 'text-sm';
    if (design.fontSize === 'small') sizeClass = isHeadline ? 'text-xl' : 'text-xs';
    if (design.fontSize === 'large') sizeClass = isHeadline ? 'text-3xl' : 'text-base';
    if (design.fontSize === 'xl') sizeClass = isHeadline ? 'text-4xl' : 'text-lg';

    let effectClass = '';
    if (design.textEffect === 'shadow') effectClass = 'drop-shadow-lg shadow-black';
    if (design.textEffect === 'neon') effectClass = 'drop-shadow-[0_0_5px_rgba(255,255,255,0.8)]';
    if (design.textEffect === 'outline') effectClass = 'outline-text'; 
    if (design.textEffect === 'bg-highlight') effectClass = 'bg-black/50 px-2 rounded box-decoration-clone';

    // Alignment
    let alignClass = 'text-left';
    if (design.textAlign === 'center') alignClass = 'text-center';
    if (design.textAlign === 'right') alignClass = 'text-right';

    return `${baseSize} ${sizeClass} ${effectClass} ${alignClass}`;
  };

  // Character Counts
  const MAX_HEADLINE = 60;
  const MAX_SUBHEAD = 120;

  const renderCounter = (current: number, max: number) => {
      const isNearLimit = current > max * 0.9;
      return (
          <span className={`text-[9px] absolute right-0 -bottom-4 ${isNearLimit ? 'text-red-400' : 'text-slate-500'}`}>
              {current}/{max}
          </span>
      );
  };

  return (
    <div className="flex-shrink-0 w-[340px] h-[450px] relative rounded-xl overflow-hidden shadow-2xl bg-slate-800 border border-slate-700 group transition-all duration-300">

      {/* Background Image Layer */}
      <div className="absolute inset-0 z-0 bg-slate-900">
        {imageData ? (
          <img 
            src={imageData} 
            alt={`Slide ${slide.slide_number} visual`} 
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center text-slate-700">
            <div className="text-center p-4">
              <Image className="w-12 h-12 mx-auto mb-2 opacity-50" />
              <p className="text-xs">Visual description provided</p>
            </div>
          </div>
        )}

        <div 
          className="absolute inset-0 pointer-events-none transition-all duration-300"
          style={{ backgroundColor: `rgba(15, 23, 42, ${design.overlayOpacity / 100})` }}
        ></div>

        {/* Decorations */}
        {design.decoration === 'circle' && (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-48 h-48 border-4 border-white/20 rounded-full pointer-events-none"></div>
        )}
        {design.decoration === 'square' && (
          <div className="absolute top-4 right-4 bottom-4 left-4 border-2 border-white/20 pointer-events-none"></div>
        )}
        {design.decoration === 'accent-line' && (
           <div className="absolute top-10 left-10 w-20 h-1 bg-blue-500 pointer-events-none"></div>
        )}
        {design.decoration === 'corner-shape' && (
           <div className="absolute top-0 right-0 w-24 h-24 bg-gradient-to-bl from-blue-500/50 to-transparent rounded-bl-full pointer-events-none"></div>
        )}
      </div>

      {/* Main Content Layer - Absolute Positioning */}
      <div 
        className="absolute z-10 w-[85%] transition-all duration-100 ease-out flex flex-col gap-2"
        style={{ 
            top: `${design.yPosition}%`, 
            left: `${design.xPosition}%`,
            transform: 'translate(-50%, 0)', // Center horizontally relative to left point
            direction: isRTL ? 'rtl' : 'ltr'
        }}
      >
            {readOnly ? (
                <>
                    <h2 
                        className={`leading-tight whitespace-pre-wrap ${getTextStyle(true)}`}
                        style={{ color: design.textColor }}
                    >
                        {slide.headline}
                    </h2>
                    <p 
                        className={`leading-relaxed opacity-90 whitespace-pre-wrap ${getTextStyle(false)}`}
                        style={{ color: design.textColor }}
                    >
                        {slide.sub_headline}
                    </p>
                </>
            ) : (
                <>
                    <div className="relative w-full">
                        <textarea 
                            ref={headlineRef}
                            value={slide.headline}
                            onChange={(e) => onUpdateSlide(slide.slide_number, 'headline', e.target.value)}
                            className={`bg-transparent border border-dashed border-white/20 hover:border-blue-500/50 rounded w-full resize-none focus:outline-none focus:bg-slate-900/40 p-1 overflow-hidden ${getTextStyle(true)}`}
                            style={{ color: design.textColor }}
                            rows={1}
                            placeholder={isRTL ? "العنوان الرئيسي" : "Headline"}
                        />
                        {renderCounter(slide.headline.length, MAX_HEADLINE)}
                    </div>

                    <div className="relative w-full">
                        <textarea 
                            ref={subheadRef}
                            value={slide.sub_headline}
                            onChange={(e) => onUpdateSlide(slide.slide_number, 'sub_headline', e.target.value)}
                            className={`bg-transparent border border-dashed border-white/20 hover:border-blue-500/50 rounded w-full resize-none focus:outline-none focus:bg-slate-900/40 p-1 overflow-hidden ${getTextStyle(false)}`}
                            style={{ color: design.textColor }}
                            rows={1}
                            placeholder={isRTL ? "العنوان الفرعي" : "Sub-headline"}
                        />
                        {renderCounter(slide.sub_headline.length, MAX_SUBHEAD)}
                    </div>
                </>
            )}
      </div>

      {/* Slide Number Badge */}
      <div className={`absolute top-4 ${isRTL ? 'right-4' : 'left-4'} z-20`}>
             <div className="bg-blue-500/20 text-blue-300 text-[10px] font-bold px-2 py-1 rounded backdrop-blur-sm border border-blue-500/10">
                {slide.slide_number}
             </div>
      </div>

      {/* Edit Button */}
      {!readOnly && (
            <button 
                onClick={() => setShowSettings(!showSettings)}
                className={`absolute top-4 ${isRTL ? 'left-4' : 'right-4'} z-20 p-2 rounded-lg backdrop-blur-md transition-all ${showSettings ? 'bg-blue-600 text-white' : 'bg-white/10 text-white hover:bg-white/20'}`}
            >
