            <button 
                onClick={() => setShowSettings(!showSettings)}
                className={`absolute top-4 ${isRTL ? 'left-4' : 'right-4'} z-20 p-2 rounded-lg backdrop-blur-md transition-all ${showSettings ? 'bg-blue-600 text-white' : 'bg-white/10 text-white hover:bg-white/20'}`}
                data-html2canvas-ignore="true"
            >
                {showSettings ? <X size={16} /> : <Settings2 size={16} />}
            </button>
      )}

      {/* Settings Overlay Panel */}
      {showSettings && !readOnly && (
        <div 
            className="absolute bottom-0 left-0 right-0 bg-slate-900/95 backdrop-blur-xl border-t border-slate-700 z-30 animate-in slide-in-from-bottom-10 duration-200 shadow-2xl h-[280px] overflow-y-auto"
            data-html2canvas-ignore="true"
        >
            {/* Tabs */}
            <div className="flex border-b border-slate-800 sticky top-0 bg-slate-900/95 z-10">
                <button onClick={() => setActiveTab('layout')} className={`flex-1 py-2 text-[10px] font-bold uppercase flex flex-col items-center gap-1 ${activeTab === 'layout' ? 'text-blue-400 border-b-2 border-blue-500' : 'text-slate-500 hover:text-slate-300'}`}>
                    <Layout size={14} /> Layout
                </button>
                <button onClick={() => setActiveTab('text')} className={`flex-1 py-2 text-[10px] font-bold uppercase flex flex-col items-center gap-1 ${activeTab === 'text' ? 'text-blue-400 border-b-2 border-blue-500' : 'text-slate-500 hover:text-slate-300'}`}>
                    <Type size={14} /> Text
                </button>
                <button onClick={() => setActiveTab('style')} className={`flex-1 py-2 text-[10px] font-bold uppercase flex flex-col items-center gap-1 ${activeTab === 'style' ? 'text-blue-400 border-b-2 border-blue-500' : 'text-slate-500 hover:text-slate-300'}`}>
                    <Palette size={14} /> Style
                </button>
                <button onClick={() => setActiveTab('char')} className={`flex-1 py-2 text-[10px] font-bold uppercase flex flex-col items-center gap-1 ${activeTab === 'char' ? 'text-blue-400 border-b-2 border-blue-500' : 'text-slate-500 hover:text-slate-300'}`}>
                    <User size={14} /> Char
                </button>
            </div>

            <div className="p-4">
                {/* --- LAYOUT TAB --- */}
                {activeTab === 'layout' && (
                    <div className="space-y-4">
                        <div className="space-y-2">
                             <label className="text-[10px] text-slate-500 font-bold uppercase block">Presets</label>
                             <div className="grid grid-cols-2 gap-2">
                                 <button onClick={() => applyLayoutPreset('default')} className="text-[10px] p-2 bg-slate-800 border border-slate-700 rounded hover:bg-slate-700">Standard</button>
                                 <button onClick={() => applyLayoutPreset('title-focus')} className="text-[10px] p-2 bg-slate-800 border border-slate-700 rounded hover:bg-slate-700">Headline Focus</button>
                                 <button onClick={() => applyLayoutPreset('quote')} className="text-[10px] p-2 bg-slate-800 border border-slate-700 rounded hover:bg-slate-700">Quote Style</button>
                                 <button onClick={() => applyLayoutPreset('bottom-caption')} className="text-[10px] p-2 bg-slate-800 border border-slate-700 rounded hover:bg-slate-700">Bottom Caption</button>
                             </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-[10px] text-slate-500 font-bold uppercase block flex items-center gap-1"><Move size={10}/> Manual Position</label>
                            <div className="space-y-2 bg-slate-800/50 p-2 rounded border border-slate-700/50">
                                <div className="flex items-center gap-2">
                                     <span className="text-[9px] text-slate-400 w-2">X</span>
                                     <input 
                                        type="range" min="0" max="100" 
                                        value={design.xPosition} 
                                        onChange={(e) => onUpdateDesign(slide.slide_number, 'xPosition', parseInt(e.target.value))}
                                        className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                                    />
                                </div>
                                <div className="flex items-center gap-2">
                                     <span className="text-[9px] text-slate-400 w-2">Y</span>
                                     <input 
                                        type="range" min="0" max="100" 
                                        value={design.yPosition} 
                                        onChange={(e) => onUpdateDesign(slide.slide_number, 'yPosition', parseInt(e.target.value))}
                                        className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                                    />
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* --- TEXT TAB --- */}
                {activeTab === 'text' && (
                    <div className="space-y-4">
                        <div className="space-y-2">
                            <label className="text-[10px] text-slate-500 font-bold uppercase block">Alignment</label>
                            <div className="flex gap-1 justify-between bg-slate-800/50 p-1 rounded">
                                <button onClick={() => onUpdateDesign(slide.slide_number, 'textAlign', 'left')} className={`flex-1 p-1 rounded flex justify-center ${design.textAlign === 'left' ? 'bg-blue-600 text-white' : 'hover:bg-slate-700 text-slate-400'}`}><AlignLeft size={14}/></button>
                                <button onClick={() => onUpdateDesign(slide.slide_number, 'textAlign', 'center')} className={`flex-1 p-1 rounded flex justify-center ${design.textAlign === 'center' ? 'bg-blue-600 text-white' : 'hover:bg-slate-700 text-slate-400'}`}><AlignCenter size={14}/></button>
                                <button onClick={() => onUpdateDesign(slide.slide_number, 'textAlign', 'right')} className={`flex-1 p-1 rounded flex justify-center ${design.textAlign === 'right' ? 'bg-blue-600 text-white' : 'hover:bg-slate-700 text-slate-400'}`}><AlignRight size={14}/></button>
                                <button onClick={() => onUpdateDesign(slide.slide_number, 'textAlign', 'justify')} className={`flex-1 p-1 rounded flex justify-center ${design.textAlign === 'justify' ? 'bg-blue-600 text-white' : 'hover:bg-slate-700 text-slate-400'}`}><AlignJustify size={14}/></button>
                            </div>
                        </div>

                        <div className="space-y-2">
                             <label className="text-[10px] text-slate-500 font-bold uppercase block">Styling</label>
                             <div className="flex gap-2 items-center">
                                <input 
                                    type="color" 
                                    value={design.textColor}
                                    onChange={(e) => onUpdateDesign(slide.slide_number, 'textColor', e.target.value)}
                                    className="w-8 h-8 rounded bg-transparent cursor-pointer border border-slate-600"
                                />
                                <select 
                                    value={design.fontSize}
                                    onChange={(e) => onUpdateDesign(slide.slide_number, 'fontSize', e.target.value)}
                                    className="bg-slate-800 text-white text-xs p-1.5 rounded border border-slate-700 outline-none flex-1"
                                >
                                    <option value="small">Small</option>
                                    <option value="medium">Medium</option>
                                    <option value="large">Large</option>
                                    <option value="xl">Extra Large</option>
                                </select>
                             </div>
                        </div>

                         <div className="space-y-2">
                             <label className="text-[10px] text-slate-500 font-bold uppercase block">Effects</label>
                             <div className="grid grid-cols-3 gap-1">
                                 {['none', 'shadow', 'neon', 'outline', 'bg-highlight', 'glitch', 'retro'].map(eff => (
                                     <button 
                                        key={eff}
                                        onClick={() => onUpdateDesign(slide.slide_number, 'textEffect', eff)}
                                        className={`text-[10px] py-1 rounded border ${design.textEffect === eff ? 'bg-blue-600 border-blue-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400'}`}
                                     >
                                        {eff}
                                     </button>
                                 ))}
                             </div>
                         </div>
                    </div>
                )}

                {/* --- STYLE TAB --- */}
                {activeTab === 'style' && (
                     <div className="space-y-4">
                        <div className="space-y-2">
                             <label className="text-[10px] text-slate-500 font-bold uppercase block">Visual Patterns</label>
                             <div className="grid grid-cols-4 gap-2">
                                 {[
                                     { id: 'none', label: 'None', icon: X },
                                     { id: 'grid', label: 'Grid', icon: Grid },
                                     { id: 'frame', label: 'Frame', icon: Frame },
                                     { id: 'blob', label: 'Blob', icon: Sparkles },
                                     { id: 'circle', label: 'Circle', icon: BoxSelect },
                                     { id: 'square', label: 'Square', icon: BoxSelect },
                                     { id: 'accent-line', label: 'Line', icon: BoxSelect },
                                     { id: 'corner-shape', label: 'Corner', icon: Layers },
                                 ].map((d) => (
                                     <button
                                        key={d.id}
                                        onClick={() => onUpdateDesign(slide.slide_number, 'decoration', d.id)}
                                        className={`flex flex-col items-center justify-center p-2 rounded border gap-1 h-16 ${design.decoration === d.id ? 'bg-blue-600 border-blue-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400'}`}
                                     >
                                         <d.icon size={12} />
                                         <span className="text-[9px]">{d.label}</span>
                                     </button>
                                 ))}
                             </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-[10px] text-slate-500 font-bold uppercase block">Overlay Darkness</label>
                            <input 
                                type="range" min="0" max="90" 
                                value={design.overlayOpacity} 
                                onChange={(e) => onUpdateDesign(slide.slide_number, 'overlayOpacity', parseInt(e.target.value))}
                                className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                            />
                        </div>

                        <div className="pt-2 border-t border-slate-800">
                             <div className="flex gap-2">
                                <input
                                    value={slide.visual_description}
                                    onChange={(e) => onUpdateSlide(slide.slide_number, 'visual_description', e.target.value)}
                                    className="flex-1 bg-slate-950 text-xs text-slate-400 border border-slate-800 rounded px-2 py-1 focus:border-blue-500 focus:outline-none"
                                    placeholder="Edit visual prompt..."
                                />
                                <button
                                    onClick={() => onGenerateImage(slide.slide_number)}
                                    disabled={isGeneratingImage}
                                    className="bg-blue-600 hover:bg-blue-500 text-white p-1.5 rounded disabled:opacity-50"
                                >
                                    {isGeneratingImage ? <RefreshCw size={14} className="animate-spin" /> : <Image size={14} />}
                                </button>
                            </div>
                        </div>
                     </div>
                )}

                {/* --- CHARACTER TAB --- */}
                {activeTab === 'char' && (
                    <div className="space-y-4">
                         <div className="space-y-2">
                            <button
                                onClick={() => onUpdateSlide(slide.slide_number, 'include_character', !slide.include_character)}
                                className={`w-full py-2 rounded flex items-center justify-center border text-xs font-bold ${slide.include_character ? 'bg-blue-600 border-blue-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-500'}`}
                            >
                                <User size={14} className="mr-2"/> {slide.include_character ? 'Character Enabled' : 'Character Disabled'}
                            </button>
                        </div>

                        {slide.include_character && (
                            <div className="space-y-4 animate-in slide-in-from-right-5 duration-200">
                                <div className="grid grid-cols-2 gap-4">
                                     <div className="space-y-1">
                                        <label className="text-[9px] text-slate-500 font-bold uppercase block">Scale</label>
                                        <select 
                                            value={slide.character_settings?.scale || 'medium'}
                                            onChange={(e) => updateCharacterSetting('scale', e.target.value)}
                                            className="w-full bg-slate-800 text-white text-xs p-1.5 rounded border border-slate-700"
                                        >
                                            <option value="small">Small</option>
                                            <option value="medium">Medium</option>
                                            <option value="large">Large</option>
                                        </select>
                                     </div>
                                     <div className="space-y-1">
                                        <label className="text-[9px] text-slate-500 font-bold uppercase block">Position</label>
                                        <select 
                                            value={slide.character_settings?.position || 'center'}
                                            onChange={(e) => updateCharacterSetting('position', e.target.value)}
                                            className="w-full bg-slate-800 text-white text-xs p-1.5 rounded border border-slate-700"
                                        >
                                            <option value="left">Left</option>
                                            <option value="center">Center</option>
                                            <option value="right">Right</option>
                                        </select>
                                     </div>
                                </div>

                                <div className="space-y-1">
                                    <label className="text-[9px] text-blue-400 font-bold uppercase block">Action Prompt</label>
                                    <textarea 
                                        value={slide.character_custom_prompt || ''}
                                        onChange={(e) => onUpdateSlide(slide.slide_number, 'character_custom_prompt', e.target.value)}
                                        placeholder="e.g. The character is holding a sign..."
                                        className="w-full bg-slate-950/50 border border-blue-500/30 rounded px-2 py-2 text-xs text-slate-300 focus:outline-none focus:border-blue-500 h-20 resize-none"
                                    />
                                    <p className="text-[9px] text-slate-500">Updates visual on regeneration.</p>
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
      )}
    </div>
  );
};

export default SlideCard;

import React, { useState, useEffect } from 'react';
import { Sparkles, Wand2, Layers, Download, Palette, Users, Type, Save, Archive, Play, Trash2, Edit3, Grid, Globe, UserPlus, Zap, FileDown } from 'lucide-react';
import { generateCarouselScript, generateSlideImage, generateIdeas } from './services/geminiService';
import { CarouselResponse, GenerationStatus, ViewMode, Slide, SlideDesign } from './types';
import SlideCard from './components/SlideCard';
// @ts-ignore
import { jsPDF } from "jspdf";
// @ts-ignore
import html2canvas from "html2canvas";

const VISUAL_STYLES = [
  "Minimalist & Clean",
  "Cyberpunk Neon",
  "Corporate Memphis",
  "Dark Mode Gradient",
  "Abstract Geometric",
  "Vintage Paper Texture",
  "3D Claymorphism",
  "Futuristic Tech",
  "Glassmorphism",
  "Brutalism",
  "Retro Pop Art",
  "Swiss International",
  "Doodle & Sketch",
  "Nature & Organic"
];

function App() {
  // --- View State ---
  const [activeView, setActiveView] = useState<ViewMode>('create');

  // --- Input State ---
  const [topic, setTopic] = useState('');
  const [visualStyle, setVisualStyle] = useState(VISUAL_STYLES[0]);
  const [targetAudience, setTargetAudience] = useState('');
  const [slideCount, setSlideCount] = useState<number>(5);

  // New Input States
  const [language, setLanguage] = useState<'en' | 'ar'>('en');
  const [tone, setTone] = useState('');
  const [dialect, setDialect] = useState(''); // Only for Arabic
  const [mainTheme, setMainTheme] = useState('');
  const [useCharacter, setUseCharacter] = useState(false);
  const [characterDesc, setCharacterDesc] = useState(''); // Editable global prompt

  // --- Data State ---
  const [currentCarousel, setCurrentCarousel] = useState<CarouselResponse | null>(null);
  const [generatedImages, setGeneratedImages] = useState<Record<string, Record<number, string>>>({});
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [imageLoadingState, setImageLoadingState] = useState<Record<number, boolean>>({});

  // --- History State ---
  const [library, setLibrary] = useState<CarouselResponse[]>([]);

  // Load library from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('carousel_library');
    if (saved) {
      try {
        setLibrary(JSON.parse(saved));
      } catch (e) { console.error("Failed to load library", e); }
    }
  }, []);

  // Save library when it changes
  useEffect(() => {
    try {
        localStorage.setItem('carousel_library', JSON.stringify(library));
    } catch (e) {
        console.error("Failed to save library (quota exceeded)", e);
    }
  }, [library]);

  // --- Actions ---

  const handleAutoGenerateIdeas = async () => {
     if (!mainTheme) {
         alert("Please enter a Main Theme first.");
         return;
     }
     setStatus(GenerationStatus.GENERATING_IDEAS);
     try {
         const idea = await generateIdeas(mainTheme, language);
         setTopic(idea.topic);
         setTargetAudience(idea.audience);
     } catch (e) {
         console.error(e);
     } finally {
         setStatus(GenerationStatus.IDLE);
     }
  };

  const handleGenerateScript = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic || !targetAudience) return;

    setStatus(GenerationStatus.GENERATING_SCRIPT);

    try {
      const data = await generateCarouselScript(
          topic, visualStyle, targetAudience, slideCount, 
          language, tone, dialect, useCharacter
      );

      // If user wants a character, populate the state with what the AI came up with
      if (useCharacter && data.carousel_metadata.character_description) {
          setCharacterDesc(data.carousel_metadata.character_description);
      }

      setCurrentCarousel(data);
      setStatus(GenerationStatus.COMPLETE);
      setActiveView('editor');
    } catch (error) {
      console.error(error);
      setStatus(GenerationStatus.ERROR);
    }
  };

  const handleGenerateImage = async (slideNumber: number) => {
    if (!currentCarousel) return;

    const slide = currentCarousel.slides.find(s => s.slide_number === slideNumber);
    if (!slide) return;

    setImageLoadingState(prev => ({ ...prev, [slideNumber]: true }));

    try {
      // Pass the potentially edited global character description if applicable
      const metadata = { 
          ...currentCarousel.carousel_metadata, 
          character_description: characterDesc || currentCarousel.carousel_metadata.character_description 
      };

      const base64Image = await generateSlideImage(slide, metadata);
      setGeneratedImages(prev => ({
        ...prev,
        [currentCarousel.id]: {
            ...(prev[currentCarousel.id] || {}),
            [slideNumber]: base64Image
        }
      }));
    } catch (error) {
      console.error("Failed to generate image", error);
      alert("Failed to generate image. Please try again.");
    } finally {
      setImageLoadingState(prev => ({ ...prev, [slideNumber]: false }));
    }
  };

  const handleGenerateAllImages = async () => {
      if (!currentCarousel) return;
      const promises = currentCarousel.slides.map(slide => handleGenerateImage(slide.slide_number));
      await Promise.all(promises);
  };

  const handleUpdateSlide = (slideNumber: number, field: keyof Slide, value: any) => {
      if (!currentCarousel) return;
      const updatedSlides = currentCarousel.slides.map(slide => {
          if (slide.slide_number === slideNumber) {
              return { ...slide, [field]: value };
          }
          return slide;
      });
      setCurrentCarousel({ ...currentCarousel, slides: updatedSlides });
  };

  const handleUpdateDesign = (slideNumber: number, field: keyof SlideDesign, value: any) => {
    if (!currentCarousel) return;
    const updatedSlides = currentCarousel.slides.map(slide => {
        if (slide.slide_number === slideNumber) {
            return { 
                ...slide, 
                design: { ...slide.design, [field]: value }
            };
        }
        return slide;
    });
    setCurrentCarousel({ ...currentCarousel, slides: updatedSlides });
  };

  const saveToLibrary = () => {
      if (!currentCarousel) return;
      // Save the potentially edited character description back to metadata
      const carouselToSave = {
          ...currentCarousel,
          carousel_metadata: {
              ...currentCarousel.carousel_metadata,
              character_description: characterDesc
          }
      };

      const exists = library.find(c => c.id === carouselToSave.id);
      let newLibrary;
      if (exists) {
          newLibrary = library.map(c => c.id === carouselToSave.id ? carouselToSave : c);
      } else {
          newLibrary = [carouselToSave, ...library];
      }
      setLibrary(newLibrary);
      alert('Saved to Library!');
  };

  const loadFromLibrary = (carousel: CarouselResponse) => {
      setCurrentCarousel(carousel);
      setLanguage(carousel.carousel_metadata.language as 'en' | 'ar');
      setCharacterDesc(carousel.carousel_metadata.character_description || '');
      setActiveView('editor');
  };

  const deleteFromLibrary = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (confirm('Are you sure you want to delete this carousel?')) {
          setLibrary(prev => prev.filter(c => c.id !== id));
          const newImages = { ...generatedImages };
          delete newImages[id];
          setGeneratedImages(newImages);
          if (currentCarousel?.id === id) {
              setCurrentCarousel(null);
              setActiveView('create');
          }
      }
  };

  const exportJSON = () => {
      if (!currentCarousel) return;
      const exportData = {
          ...currentCarousel,
          _images: generatedImages[currentCarousel.id] || {}
      };
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", `carousel-${currentCarousel.carousel_metadata.topic.replace(/\s+/g, '-').toLowerCase()}.json`);
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
  };

  const exportPDF = async () => {
    if (!currentCarousel) return;

    // Check if we have images generated for all slides? Not strictly necessary but better.
    // Create PDF
    const doc = new jsPDF({
        orientation: "portrait",
        unit: "px",
        format: [340, 450] // Match slide dimensions
    });

    const slideElements = document.querySelectorAll('[id^="slide-card-"]');

    for (let i = 0; i < slideElements.length; i++) {
        const el = slideElements[i] as HTMLElement;
        if (i > 0) doc.addPage();

        try {
            // Render to canvas
            // We use higher scale for better quality, but here 1.5 or 2 is usually enough
            const canvas = await html2canvas(el, { 
                scale: 2, 
                useCORS: true,
                backgroundColor: null 
            });
            const imgData = canvas.toDataURL('image/png');
            doc.addImage(imgData, 'PNG', 0, 0, 340, 450);
        } catch (e) {
            console.error("Error exporting slide " + i, e);
        }
    }
    doc.save(`carousel-${currentCarousel.carousel_metadata.topic.slice(0, 20)}.pdf`);
  };

  // --- Render Helpers ---

  const renderNav = () => (
      <nav className="flex flex-col space-y-2 w-full">
          <button onClick={() => setActiveView('create')} className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${activeView === 'create' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}>
              <Wand2 className="w-5 h-5" /> Create
          </button>
          <button onClick={() => setActiveView('editor')} disabled={!currentCarousel} className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${activeView === 'editor' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50' : 'text-slate-400 hover:bg-slate-800 hover:text-white'} ${!currentCarousel ? 'opacity-50 cursor-not-allowed' : ''}`}>
              <Edit3 className="w-5 h-5" /> Editor
          </button>
          <button onClick={() => setActiveView('library')} className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${activeView === 'library' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}>
              <Archive className="w-5 h-5" /> Library
          </button>
      </nav>
  );

  return (
    <div className={`min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-blue-500/30 flex ${language === 'ar' ? 'font-[sans-serif]' : ''}`}>

      {/* Sidebar */}
      <aside className="w-64 border-r border-slate-800 bg-slate-900/50 backdrop-blur-xl h-screen sticky top-0 flex flex-col p-6 shrink-0 z-30">
         <div className="flex items-center gap-2 mb-8">
            <div className="w-8 h-8 rounded-lg bg-blue-600 flex items-center justify-center">
              <Layers className="w-5 h-5 text-white" />
            </div>
            <h1 className="font-bold text-lg tracking-tight text-white">Carousel<span className="text-blue-500">AI</span></h1>
         </div>

         {renderNav()}

         <div className="mt-auto pt-6 border-t border-slate-800">
            <div className="text-xs text-slate-500 mb-2">Recent Projects</div>
            <div className="space-y-1">
                {library.slice(0, 3).map(item => (
                    <button key={item.id} onClick={() => loadFromLibrary(item)} className="block w-full text-left truncate text-sm text-slate-400 hover:text-white py-1">
                        {item.carousel_metadata.topic}
                    </button>
                ))}
            </div>
         </div>
      </aside>

      {/* Main Content */}
