  textEffect: 'none' | 'shadow' | 'neon' | 'outline' | 'bg-highlight' | 'glitch' | 'retro';
  decoration: 'none' | 'circle' | 'square' | 'accent-line' | 'corner-shape' | 'grid' | 'blob' | 'frame';
