                                <div className="grid grid-cols-2 gap-4">
                                    <div className="space-y-1">
                                        <label className="text-[9px] text-slate-500 font-bold uppercase block flex items-center gap-1"><Ghost size={8}/> Opacity</label>
                                        <input 
                                            type="range" min="10" max="100" 
                                            value={slide.character_settings?.opacity ?? 100} 
                                            onChange={(e) => updateCharacterSetting('opacity', parseInt(e.target.value))}
                                            className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                                            title="Lower values prompt for transparency"
                                        />
                                    </div>
                                    <div className="space-y-1">
                                        <label className="text-[9px] text-slate-500 font-bold uppercase block flex items-center gap-1"><RotateCw size={8}/> Rotation</label>
                                        <input 
                                            type="range" min="-180" max="180" 
                                            value={slide.character_settings?.rotation ?? 0} 
                                            onChange={(e) => updateCharacterSetting('rotation', parseInt(e.target.value))}
                                            className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                                        />
                                    </div>
                                </div>

                                <div className="space-y-1">
                                    <label className="text-[9px] text-blue-400 font-bold uppercase block">Action Prompt</label>
                                    <textarea 
                                        value={slide.character_custom_prompt || ''}
                                        onChange={(e) => onUpdateSlide(slide.slide_number, 'character_custom_prompt', e.target.value)}
                                        placeholder="e.g. The character is holding a sign..."
                                        className="w-full bg-slate-950/50 border border-blue-500/30 rounded px-2 py-2 text-xs text-slate-300 focus:outline-none focus:border-blue-500 h-16 resize-none"
                                    />
                                    <p className="text-[9px] text-slate-500">Updates visual on regeneration.</p>
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
      )}
    </div>
  );
};

export default SlideCard;

import React, { useState, useEffect } from 'react';
import { Sparkles, Wand2, Layers, Download, Palette, Users, Type, Save, Archive, Play, Trash2, Edit3, Grid, Globe, UserPlus, Zap, FileDown, Check } from 'lucide-react';
import { generateCarouselScript, generateSlideImage, generateIdeas } from './services/geminiService';
import { CarouselResponse, GenerationStatus, ViewMode, Slide, SlideDesign } from './types';
import SlideCard from './components/SlideCard';
// @ts-ignore
import { jsPDF } from "jspdf";
// @ts-ignore
import html2canvas from "html2canvas";

const VISUAL_STYLES = [
  "Minimalist & Clean",
  "Cyberpunk Neon",
  "Corporate Memphis",
  "Dark Mode Gradient",
  "Abstract Geometric",
  "Vintage Paper Texture",
  "3D Claymorphism",
  "Futuristic Tech",
  "Glassmorphism",
  "Brutalism",
  "Retro Pop Art",
  "Swiss International",
  "Doodle & Sketch",
  "Nature & Organic",
  "Hand Drawn", 
  "Collage", 
  "Pixar Style", 
  "Watercolor", 
  "Editorial", 
  "High Contrast", 
  "Isometric 3D"
];

const TONES_EN = [
    "Professional", "Casual", "Humorous", "Inspirational", "Educational", "Controversial", "Empathetic", "Urgent", "Witty"
];

const TONES_AR = [
    "Professional (رسمي)", "Friendly (ودود)", "Inspirational (ملهم)", "Sarcastic (ساخر)", "Educational (تعليمي)", "Urgent (عاجل)", "Serious (جدي)"
];

function App() {
  // --- View State ---
  const [activeView, setActiveView] = useState<ViewMode>('create');

  // --- Input State ---
  const [topic, setTopic] = useState('');
  const [visualStyle, setVisualStyle] = useState(VISUAL_STYLES[0]);
  const [targetAudience, setTargetAudience] = useState('');
  const [slideCount, setSlideCount] = useState<number>(5);

  // New Input States
  const [language, setLanguage] = useState<'en' | 'ar'>('en');
  const [tone, setTone] = useState(TONES_EN[0]);
  const [dialect, setDialect] = useState(''); // Only for Arabic
  const [mainTheme, setMainTheme] = useState('');
  const [useCharacter, setUseCharacter] = useState(false);
  const [characterDesc, setCharacterDesc] = useState(''); 

  // --- Data State ---
  const [currentCarousel, setCurrentCarousel] = useState<CarouselResponse | null>(null);
  const [generatedImages, setGeneratedImages] = useState<Record<string, Record<number, string>>>({});
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [imageLoadingState, setImageLoadingState] = useState<Record<number, boolean>>({});

  // --- History State ---
  const [library, setLibrary] = useState<CarouselResponse[]>([]);

  // Load library from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('carousel_library');
    if (saved) {
      try {
        setLibrary(JSON.parse(saved));
      } catch (e) { console.error("Failed to load library", e); }
    }
  }, []);

  // Save library when it changes
  useEffect(() => {
    try {
        localStorage.setItem('carousel_library', JSON.stringify(library));
    } catch (e) {
        console.error("Failed to save library (quota exceeded)", e);
    }
  }, [library]);

  const handleLanguageChange = (lang: 'en' | 'ar') => {
      setLanguage(lang);
      // Reset tone to first available for that language to ensure consistency
      setTone(lang === 'en' ? TONES_EN[0] : TONES_AR[0]);
  };

  const handleAutoGenerateIdeas = async () => {
     if (!mainTheme) {
         alert("Please enter a Main Theme first.");
         return;
     }
     setStatus(GenerationStatus.GENERATING_IDEAS);
     try {
         const idea = await generateIdeas(mainTheme, language);
         setTopic(idea.topic);
         setTargetAudience(idea.audience);
     } catch (e) {
         console.error(e);
     } finally {
         setStatus(GenerationStatus.IDLE);
     }
  };

  const handleGenerateScript = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic || !targetAudience) return;

    setStatus(GenerationStatus.GENERATING_SCRIPT);

    try {
      const data = await generateCarouselScript(
          topic, visualStyle, targetAudience, slideCount, 
          language, tone, dialect, useCharacter
      );

      // If user wants a character, populate the state with what the AI came up with
      if (useCharacter && data.carousel_metadata.character_description) {
          setCharacterDesc(data.carousel_metadata.character_description);
      }

      setCurrentCarousel(data);
      setStatus(GenerationStatus.COMPLETE);
      setActiveView('editor');
    } catch (error) {
      console.error(error);
      setStatus(GenerationStatus.ERROR);
    }
  };

  const handleGenerateImage = async (slideNumber: number) => {
    if (!currentCarousel) return;

    const slide = currentCarousel.slides.find(s => s.slide_number === slideNumber);
    if (!slide) return;

    setImageLoadingState(prev => ({ ...prev, [slideNumber]: true }));

    try {
      const metadata = { 
          ...currentCarousel.carousel_metadata, 
          character_description: characterDesc || currentCarousel.carousel_metadata.character_description 
      };

      const base64Image = await generateSlideImage(slide, metadata);
      setGeneratedImages(prev => ({
        ...prev,
        [currentCarousel.id]: {
            ...(prev[currentCarousel.id] || {}),
            [slideNumber]: base64Image
        }
      }));
    } catch (error) {
      console.error("Failed to generate image", error);
      alert("Failed to generate image. Please try again.");
    } finally {
      setImageLoadingState(prev => ({ ...prev, [slideNumber]: false }));
    }
  };

  const handleGenerateAllImages = async () => {
      if (!currentCarousel) return;
      const promises = currentCarousel.slides.map(slide => handleGenerateImage(slide.slide_number));
      await Promise.all(promises);
  };

  const handleUpdateSlide = (slideNumber: number, field: keyof Slide, value: any) => {
      if (!currentCarousel) return;
      const updatedSlides = currentCarousel.slides.map(slide => {
          if (slide.slide_number === slideNumber) {
              return { ...slide, [field]: value };
          }
          return slide;
      });
      setCurrentCarousel({ ...currentCarousel, slides: updatedSlides });
  };

  const handleUpdateDesign = (slideNumber: number, field: keyof SlideDesign, value: any) => {
    if (!currentCarousel) return;
    const updatedSlides = currentCarousel.slides.map(slide => {
        if (slide.slide_number === slideNumber) {
            return { 
                ...slide, 
                design: { ...slide.design, [field]: value }
            };
        }
        return slide;
    });
    setCurrentCarousel({ ...currentCarousel, slides: updatedSlides });
  };

  const saveToLibrary = () => {
      if (!currentCarousel) return;
      const carouselToSave = {
          ...currentCarousel,
          carousel_metadata: {
              ...currentCarousel.carousel_metadata,
              character_description: characterDesc
          }
      };

      const exists = library.find(c => c.id === carouselToSave.id);
      let newLibrary;
      if (exists) {
          newLibrary = library.map(c => c.id === carouselToSave.id ? carouselToSave : c);
      } else {
          newLibrary = [carouselToSave, ...library];
      }
      setLibrary(newLibrary);
      alert('Saved to Library!');
  };

  const loadFromLibrary = (carousel: CarouselResponse) => {
      setCurrentCarousel(carousel);
      setLanguage(carousel.carousel_metadata.language as 'en' | 'ar');
      setCharacterDesc(carousel.carousel_metadata.character_description || '');
      setActiveView('editor');
  };

  const deleteFromLibrary = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (confirm('Are you sure you want to delete this carousel?')) {
          setLibrary(prev => prev.filter(c => c.id !== id));
          const newImages = { ...generatedImages };
          delete newImages[id];
          setGeneratedImages(newImages);
          if (currentCarousel?.id === id) {
              setCurrentCarousel(null);
              setActiveView('create');
          }
      }
  };

  const exportJSON = () => {
      if (!currentCarousel) return;
      const exportData = {
          ...currentCarousel,
          _images: generatedImages[currentCarousel.id] || {}
      };
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", `carousel-${currentCarousel.carousel_metadata.topic.replace(/\s+/g, '-').toLowerCase()}.json`);
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
  };

  const exportPDF = async () => {
    if (!currentCarousel) return;
    const doc = new jsPDF({
        orientation: "portrait",
        unit: "px",
        format: [340, 450] // Match slide dimensions
    });

    const slideElements = document.querySelectorAll('[id^="slide-card-"]');

    for (let i = 0; i < slideElements.length; i++) {
        const el = slideElements[i] as HTMLElement;
        if (i > 0) doc.addPage();
        try {
            const canvas = await html2canvas(el, { 
                scale: 2, 
                useCORS: true,
                backgroundColor: null 
            });
            const imgData = canvas.toDataURL('image/png');
            doc.addImage(imgData, 'PNG', 0, 0, 340, 450);
        } catch (e) {
            console.error("Error exporting slide " + i, e);
        }
    }
    doc.save(`carousel-${currentCarousel.carousel_metadata.topic.slice(0, 20)}.pdf`);
  };

  return (
    <div className={`min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-blue-500/30 flex flex-col ${language === 'ar' ? 'font-[sans-serif]' : ''}`}>

      {/* Top Navigation Header */}
      <header className="sticky top-0 z-50 bg-slate-900/80 backdrop-blur-md border-b border-slate-800 px-6 py-3 flex items-center justify-between">
         <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-blue-600 flex items-center justify-center shadow-[0_0_15px_rgba(37,99,235,0.4)]">
              <Layers className="w-5 h-5 text-white" />
            </div>
            <h1 className="font-bold text-lg tracking-tight text-white hidden md:block">Carousel<span className="text-blue-500">AI</span></h1>
         </div>

         <div className="flex bg-slate-800 rounded-lg p-1 border border-slate-700">
             <button onClick={() => setActiveView('create')} className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${activeView === 'create' ? 'bg-blue-600 text-white shadow-sm' : 'text-slate-400 hover:text-white'}`}>
                 {language === 'ar' ? 'إنشاء' : 'Create'}
             </button>
             <button onClick={() => setActiveView('editor')} disabled={!currentCarousel} className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${activeView === 'editor' ? 'bg-blue-600 text-white shadow-sm' : 'text-slate-400 hover:text-white'} disabled:opacity-50`}>
                 {language === 'ar' ? 'تعديل' : 'Editor'}
             </button>
             <button onClick={() => setActiveView('library')} className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${activeView === 'library' ? 'bg-blue-600 text-white shadow-sm' : 'text-slate-400 hover:text-white'}`}>
                 {language === 'ar' ? 'المكتبة' : 'Library'}
             </button>
         </div>

         <div className="flex gap-2">
            <button onClick={() => handleLanguageChange('en')} className={`px-3 py-1 rounded text-xs font-bold transition-all border ${language === 'en' ? 'bg-slate-700 border-slate-600 text-white' : 'border-transparent text-slate-500 hover:text-white'}`}>ENG</button>
            <button onClick={() => handleLanguageChange('ar')} className={`px-3 py-1 rounded text-xs font-bold transition-all border ${language === 'ar' ? 'bg-slate-700 border-slate-600 text-white' : 'border-transparent text-slate-500 hover:text-white'}`}>عربي</button>
         </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto bg-slate-950 p-6 md:p-8" dir={language === 'ar' ? 'rtl' : 'ltr'}>

        {/* VIEW: CREATE */}
        {activeView === 'create' && (
            <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in zoom-in-95 duration-300 pb-20">
                <div className="text-center space-y-2 mb-8">
                    <h2 className="text-3xl font-bold text-white bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">
                        {language === 'ar' ? 'لنصنع محتوى فيروسي اليوم' : 'Create Viral Carousels'}
                    </h2>
                    <p className="text-slate-400">
                        {language === 'ar' ? 'أنشئ كاروسيل احترافي لـ LinkedIn و Instagram في ثوانٍ.' : 'Generate professional LinkedIn & Instagram carousels in seconds using AI.'}
                    </p>
                </div>

                <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 md:p-8 shadow-2xl">
                    <form onSubmit={handleGenerateScript} className="space-y-8">

                        {/* 1. Theme & Auto-Gen */}
                        <div className="space-y-3">
                            <label className="text-sm font-bold text-slate-300 flex items-center gap-2">
                                <Globe className="w-4 h-4 text-blue-500" /> {language === 'ar' ? 'الموضوع العام' : 'Main Theme'}
                            </label>
                            <div className="flex gap-3">
                                <div className="flex-1 relative">
                                    <input
                                        type="text"
                                        value={mainTheme}
                                        onChange={(e) => setMainTheme(e.target.value)}
                                        placeholder={language === 'ar' ? 'مثل: ريادة الأعمال، الذكاء الاصطناعي...' : 'e.g. Entrepreneurship, AI, Fitness...'}
                                        className="w-full bg-slate-800/50 border border-slate-700 rounded-xl px-4 py-3 text-white placeholder-slate-500 focus:outline-none focus:border-blue-500 transition-all pl-10"
                                    />
                                    <div className="absolute left-3 top-3.5 text-slate-500"><Sparkles size={16}/></div>
                                </div>
                                <button
                                    type="button"
                                    onClick={handleAutoGenerateIdeas}
                                    disabled={status === GenerationStatus.GENERATING_IDEAS}
                                    className="bg-blue-600/10 hover:bg-blue-600/20 text-blue-400 border border-blue-600/30 px-6 rounded-xl text-sm font-bold transition-colors flex items-center gap-2 whitespace-nowrap"
                                >
                                    {status === GenerationStatus.GENERATING_IDEAS ? <Sparkles className="animate-spin w-4 h-4"/> : <Zap className="w-4 h-4" />}
                                    {language === 'ar' ? 'توليد أفكار' : 'Auto-Fill'}
                                </button>
                            </div>
                        </div>

                        {/* 2. Topic & Audience Grid */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                             <div className="space-y-3">
                                <label className="text-sm font-bold text-slate-300 flex items-center gap-2">
                                    <Type className="w-4 h-4 text-blue-500" /> {language === 'ar' ? 'عنوان الكاروسيل' : 'Specific Topic'}
                                </label>
                                <input
                                    type="text"
                                    value={topic}
                                    onChange={(e) => setTopic(e.target.value)}
                                    placeholder={language === 'ar' ? '5 طرق لزيادة المبيعات...' : 'e.g. 5 Ways to Scale your SaaS...'}
                                    className="w-full bg-slate-800/50 border border-slate-700 rounded-xl px-4 py-3 text-white placeholder-slate-500 focus:outline-none focus:border-blue-500 transition-all"
                                    required
                                />
                            </div>

                            <div className="space-y-3">
                                <label className="text-sm font-bold text-slate-300 flex items-center gap-2">
                                    <Users className="w-4 h-4 text-blue-500" /> {language === 'ar' ? 'الجمهور المستهدف' : 'Target Audience'}
                                </label>
                                <input
                                    type="text"
                                    value={targetAudience}
                                    onChange={(e) => setTargetAudience(e.target.value)}
                                    placeholder={language === 'ar' ? 'مؤسسي الشركات الناشئة...' : 'e.g. Startup Founders...'}
                                    className="w-full bg-slate-800/50 border border-slate-700 rounded-xl px-4 py-3 text-white placeholder-slate-500 focus:outline-none focus:border-blue-500 transition-all"
                                    required
                                />
                            </div>
                        </div>

                        {/* 3. Tone Toggles & Dialect */}
                        <div className="space-y-3">
                            <label className="text-sm font-bold text-slate-300 flex items-center gap-2">
                                <Sparkles className="w-4 h-4 text-blue-500" /> {language === 'ar' ? 'النبرة' : 'Tone'}
                            </label>

                            <div className="flex flex-wrap gap-2">
                                {(language === 'en' ? TONES_EN : TONES_AR).map((t) => (
                                    <button
                                        key={t}
                                        type="button"
                                        onClick={() => setTone(t)}
                                        className={`px-3 py-1.5 rounded-lg text-xs font-medium border transition-all ${tone === t ? 'bg-blue-600 border-blue-500 text-white shadow-md shadow-blue-900/20' : 'bg-slate-800/50 border-slate-700 text-slate-400 hover:border-slate-600'}`}
                                    >
                                        {t}
                                    </button>
                                ))}
                            </div>

                            {language === 'ar' && (
                                <div className="mt-3">
                                    <input
                                        type="text"
                                        value={dialect}
                                        onChange={(e) => setDialect(e.target.value)}
                                        className="w-full bg-slate-800/50 border border-slate-700 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-blue-500 placeholder-slate-600"
                                        placeholder="تخصيص اللهجة (اختياري: مصرية، سعودية...)"
                                    />
                                </div>
                            )}
                        </div>

                        <div className="h-px bg-slate-800 w-full"></div>

                        {/* 4. Visual Styles Toggles */}
                        <div className="space-y-3">
                            <label className="text-sm font-bold text-slate-300 flex items-center gap-2">
                                <Palette className="w-4 h-4 text-blue-500" /> {language === 'ar' ? 'النمط البصري' : 'Visual Style'}
                            </label>
                            <div className="flex flex-wrap gap-2 max-h-32 overflow-y-auto custom-scrollbar p-1">
                                {VISUAL_STYLES.map(style => (
                                    <button
                                        key={style}
                                        type="button"
                                        onClick={() => setVisualStyle(style)}
                                        className={`px-3 py-1.5 rounded-lg text-xs font-medium border transition-all flex items-center gap-1 ${visualStyle === style ? 'bg-purple-600 border-purple-500 text-white shadow-md shadow-purple-900/20' : 'bg-slate-800/50 border-slate-700 text-slate-400 hover:border-slate-600'}`}
                                    >
                                        {visualStyle === style && <Check size={12}/>} {style}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* 5. Character & Slides */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-800/30 p-4 rounded-xl border border-slate-800">
                             <div className="space-y-2">
                                <label className="text-xs font-bold text-slate-500 uppercase tracking-wider block">
                                    {language === 'ar' ? 'عدد الشرائح' : 'Slide Count'} ({slideCount})
                                </label>
                                <input 
                                    type="range" min="3" max="10" value={slideCount} onChange={(e) => setSlideCount(parseInt(e.target.value))}
                                    className="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-500"
                                />
                                <div className="flex justify-between text-[10px] text-slate-500">
                                    <span>3 Slides</span>
                                    <span>10 Slides</span>
                                </div>
                             </div>

                             <div className="flex items-center justify-between">
                                <div>
                                    <h3 className="text-sm font-bold text-white flex items-center gap-2">
                                        <UserPlus className="w-4 h-4 text-blue-400" /> 
                                        {language === 'ar' ? 'توليد شخصية' : 'AI Character'}
                                    </h3>
                                    <p className="text-[10px] text-slate-500 mt-1">
                                        {language === 'ar' ? 'شخصية متسقة.' : 'Consistent character across slides.'}
                                    </p>
                                </div>
                                <button
                                    type="button" 
                                    onClick={() => setUseCharacter(!useCharacter)}
                                    className={`w-12 h-6 rounded-full p-1 transition-colors ${useCharacter ? 'bg-blue-600' : 'bg-slate-700'}`}
                                >
                                    <div className={`w-4 h-4 bg-white rounded-full shadow-sm transition-transform ${useCharacter ? 'translate-x-6' : 'translate-x-0'}`} />
                                </button>
                             </div>
                        </div>

                        <button
                            type="submit"
                            disabled={status === GenerationStatus.GENERATING_SCRIPT}
                            className="w-full bg-blue-600 hover:bg-blue-500 text-white font-bold py-4 rounded-xl shadow-xl shadow-blue-900/20 flex items-center justify-center gap-2 transition-all hover:scale-[1.01] active:scale-[0.99] disabled:opacity-50 disabled:scale-100 disabled:cursor-not-allowed text-lg"
                        >
                            {status === GenerationStatus.GENERATING_SCRIPT ? (
                                <>
                                <Sparkles className="w-5 h-5 animate-spin" />
                                {language === 'ar' ? 'جاري الكتابة...' : 'Crafting Strategy...'}
                                </>
                            ) : (
                                <>
                                <Sparkles className="w-5 h-5" />
                                {language === 'ar' ? 'إنشاء الكاروسيل' : 'Generate Carousel'}
                                </>
                            )}
                        </button>
                    </form>
                </div>
            </div>
        )}

        {/* VIEW: EDITOR */}
        {activeView === 'editor' && currentCarousel && (
            <div className="space-y-6 h-full flex flex-col animate-in fade-in slide-in-from-bottom-4 duration-500">
                <header className="flex flex-col md:flex-row md:items-center justify-between bg-slate-900 border border-slate-800 p-4 rounded-xl sticky top-0 z-20 gap-4 shadow-lg">
                    <div>
                        <h2 className="text-xl font-bold text-white max-w-md truncate">{currentCarousel.carousel_metadata.topic}</h2>
                        <div className="flex gap-2 text-xs text-slate-400 mt-1">
                            <span className="bg-slate-800 px-2 py-0.5 rounded border border-slate-700">{currentCarousel.carousel_metadata.visual_style}</span>
                            {currentCarousel.carousel_metadata.character_description && <span className="bg-blue-900/30 text-blue-300 px-2 py-0.5 rounded border border-blue-800">Has Character</span>}
                        </div>
