} from 'lucide-react';

interface SlideCardProps {
  slide: Slide;
  imageData?: string;
  isGeneratingImage: boolean;
  onGenerateImage: (slideNumber: number) => void;
  onUpdateSlide: (slideNumber: number, field: keyof Slide, value: any) => void;
  onUpdateDesign: (slideNumber: number, field: keyof SlideDesign, value: any) => void;
  readOnly?: boolean;
  language?: 'en' | 'ar';
}

const SlideCard: React.FC<SlideCardProps> = ({ 
  slide, 
  imageData, 
  isGeneratingImage, 
  onGenerateImage,
  onUpdateSlide,
  onUpdateDesign,
  readOnly = false,
  language = 'en'
}) => {
  const [showSettings, setShowSettings] = useState(false);
  const [activeTab, setActiveTab] = useState<'layout' | 'text' | 'style' | 'char'>('layout');
  const design = slide.design;
  const isRTL = language === 'ar';

  const headlineRef = useRef<HTMLTextAreaElement>(null);
  const subheadRef = useRef<HTMLTextAreaElement>(null);

  // Auto-resize textareas
  const autoResize = (elem: HTMLTextAreaElement | null) => {
    if (elem) {
        elem.style.height = 'auto';
        elem.style.height = elem.scrollHeight + 'px';
    }
  };

  useEffect(() => {
    if (!readOnly) {
        autoResize(headlineRef.current);
        autoResize(subheadRef.current);
    }
  }, [slide.headline, slide.sub_headline, readOnly]);


  const getTextStyle = (isHeadline: boolean) => {
    const baseSize = isHeadline ? 'font-bold' : 'font-medium';

    let sizeClass = isHeadline ? 'text-2xl' : 'text-sm';
    if (design.fontSize === 'small') sizeClass = isHeadline ? 'text-xl' : 'text-xs';
    if (design.fontSize === 'large') sizeClass = isHeadline ? 'text-3xl' : 'text-base';
    if (design.fontSize === 'xl') sizeClass = isHeadline ? 'text-4xl' : 'text-lg';

    let effectClass = '';
    if (design.textEffect === 'shadow') effectClass = 'drop-shadow-lg shadow-black';
    if (design.textEffect === 'neon') effectClass = 'drop-shadow-[0_0_5px_rgba(255,255,255,0.8)]';
    if (design.textEffect === 'outline') effectClass = 'outline-text'; 
    if (design.textEffect === 'bg-highlight') effectClass = 'bg-black/50 px-2 rounded box-decoration-clone';
    if (design.textEffect === 'glitch') effectClass = 'glitch-text'; // Would need CSS implementation
    if (design.textEffect === 'retro') effectClass = 'text-yellow-400 drop-shadow-[2px_2px_0_rgba(0,0,0,1)]';

    // Alignment
    let alignClass = 'text-left';
    if (design.textAlign === 'center') alignClass = 'text-center';
    if (design.textAlign === 'right') alignClass = 'text-right';
    if (design.textAlign === 'justify') alignClass = 'text-justify';

    return `${baseSize} ${sizeClass} ${effectClass} ${alignClass}`;
  };

  const applyLayoutPreset = (type: 'default' | 'title-focus' | 'quote' | 'bottom-caption') => {
      if (type === 'default') {
          onUpdateDesign(slide.slide_number, 'textAlign', isRTL ? 'right' : 'left');
          onUpdateDesign(slide.slide_number, 'xPosition', 50);
          onUpdateDesign(slide.slide_number, 'yPosition', 10);
          onUpdateDesign(slide.slide_number, 'fontSize', 'medium');
          onUpdateDesign(slide.slide_number, 'decoration', 'none');
      } else if (type === 'title-focus') {
          onUpdateDesign(slide.slide_number, 'textAlign', 'center');
          onUpdateDesign(slide.slide_number, 'xPosition', 50);
          onUpdateDesign(slide.slide_number, 'yPosition', 40);
          onUpdateDesign(slide.slide_number, 'fontSize', 'xl');
      } else if (type === 'quote') {
          onUpdateDesign(slide.slide_number, 'textAlign', 'center');
          onUpdateDesign(slide.slide_number, 'xPosition', 50);
          onUpdateDesign(slide.slide_number, 'yPosition', 50);
          onUpdateDesign(slide.slide_number, 'fontSize', 'large');
          onUpdateDesign(slide.slide_number, 'decoration', 'accent-line');
      } else if (type === 'bottom-caption') {
          onUpdateDesign(slide.slide_number, 'textAlign', 'center');
          onUpdateDesign(slide.slide_number, 'xPosition', 50);
          onUpdateDesign(slide.slide_number, 'yPosition', 80);
          onUpdateDesign(slide.slide_number, 'fontSize', 'small');
      }
  };

  const updateCharacterSetting = (field: keyof CharacterSettings, value: any) => {
      onUpdateSlide(slide.slide_number, 'character_settings', {
          ...slide.character_settings,
          [field]: value
      });
  };

  // Character Counts
  const MAX_HEADLINE = 60;
  const MAX_SUBHEAD = 120;

  const renderCounter = (current: number, max: number) => {
      const isNearLimit = current > max * 0.9;
      return (
          <span className={`text-[9px] absolute right-0 -bottom-4 ${isNearLimit ? 'text-red-400' : 'text-slate-500'}`}>
              {current}/{max}
          </span>
      );
  };

  return (
    <div 
        id={`slide-card-${slide.slide_number}`}
        className="flex-shrink-0 w-[340px] h-[450px] relative rounded-xl overflow-hidden shadow-2xl bg-slate-900 border border-slate-800 group transition-all duration-300 select-none"
    >

      {/* Background Image Layer */}
      <div className="absolute inset-0 z-0 bg-slate-950">
        {imageData ? (
          <img 
            src={imageData} 
            alt={`Slide ${slide.slide_number} visual`} 
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center text-slate-700 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-slate-900 to-slate-950">
            <div className="text-center p-4">
              <Image className="w-12 h-12 mx-auto mb-2 opacity-50 text-slate-600" />
