import React, { useState, useEffect } from 'react';
import { Sparkles, Wand2, Layers, Download, Palette, Users, Type, Save, Archive, Play, Trash2, Edit3, Grid, Globe, UserPlus, Zap, FileDown, Check, Lightbulb, MessageSquare } from 'lucide-react';
import { generateCarouselScript, generateSlideImage, generateIdeas } from './services/geminiService';
import { CarouselResponse, GenerationStatus, ViewMode, Slide, SlideDesign } from './types';
import SlideCard from './components/SlideCard';
// @ts-ignore
import { jsPDF } from "jspdf";
// @ts-ignore
import html2canvas from "html2canvas";

const VISUAL_STYLES = [
  "Minimalist & Clean",
  "Cyberpunk Neon",
  "Corporate Memphis",
  "Dark Mode Gradient",
  "Abstract Geometric",
  "Vintage Paper Texture",
  "3D Claymorphism",
  "Futuristic Tech",
  "Glassmorphism",
  "Brutalism",
  "Retro Pop Art",
  "Swiss International",
  "Doodle & Sketch",
  "Nature & Organic",
  "Hand Drawn", 
  "Collage", 
  "Pixar Style", 
  "Watercolor", 
  "Editorial", 
  "High Contrast", 
  "Isometric 3D"
];

const TONES_EN = [
    "Professional", "Casual", "Humorous", "Inspirational", "Educational", "Controversial", "Empathetic", "Urgent", "Witty"
];

const TONES_AR = [
    "Professional (رسمي)", "Friendly (ودود)", "Inspirational (ملهم)", "Sarcastic (ساخر)", "Educational (تعليمي)", "Urgent (عاجل)", "Serious (جدي)"
];

function App() {
  // --- View State ---
  const [activeView, setActiveView] = useState<ViewMode>('create');

  // --- Input State ---
  const [topic, setTopic] = useState('');
  const [visualStyle, setVisualStyle] = useState(VISUAL_STYLES[0]);
  const [targetAudience, setTargetAudience] = useState('');
  const [slideCount, setSlideCount] = useState<number>(5);

  // New Input States
  const [language, setLanguage] = useState<'en' | 'ar'>('en');
  const [tone, setTone] = useState(TONES_EN[0]);
  const [dialect, setDialect] = useState(''); // Only for Arabic
  const [mainTheme, setMainTheme] = useState('');
  const [useCharacter, setUseCharacter] = useState(false);
  const [characterDesc, setCharacterDesc] = useState(''); 

  // --- Data State ---
  const [currentCarousel, setCurrentCarousel] = useState<CarouselResponse | null>(null);
  const [generatedImages, setGeneratedImages] = useState<Record<string, Record<number, string>>>({});
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [imageLoadingState, setImageLoadingState] = useState<Record<number, boolean>>({});

  // --- History State ---
  const [library, setLibrary] = useState<CarouselResponse[]>([]);

  // Load library from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('carousel_library');
    if (saved) {
      try {
        setLibrary(JSON.parse(saved));
      } catch (e) { console.error("Failed to load library", e); }
    }
  }, []);

  // Save library when it changes
  useEffect(() => {
    try {
        localStorage.setItem('carousel_library', JSON.stringify(library));
    } catch (e) {
        console.error("Failed to save library (quota exceeded)", e);
    }
  }, [library]);

  const handleLanguageChange = (lang: 'en' | 'ar') => {
      setLanguage(lang);
      // Reset tone to first available for that language to ensure consistency
      setTone(lang === 'en' ? TONES_EN[0] : TONES_AR[0]);
  };

  const handleAutoGenerateIdeas = async () => {
     if (!mainTheme) {
         alert("Please enter a Main Theme first.");
         return;
     }
     setStatus(GenerationStatus.GENERATING_IDEAS);
     try {
         const idea = await generateIdeas(mainTheme, language);
         setTopic(idea.topic);
         setTargetAudience(idea.audience);
     } catch (e) {
         console.error(e);
     } finally {
         setStatus(GenerationStatus.IDLE);
     }
  };

  const handleGenerateScript = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic || !targetAudience) return;

    setStatus(GenerationStatus.GENERATING_SCRIPT);

    try {
      const data = await generateCarouselScript(
          topic, visualStyle, targetAudience, slideCount, 
          language, tone, dialect, useCharacter
      );

      // If user wants a character, populate the state with what the AI came up with
      if (useCharacter && data.carousel_metadata.character_description) {
          setCharacterDesc(data.carousel_metadata.character_description);
      }

      setCurrentCarousel(data);
      setStatus(GenerationStatus.COMPLETE);
      setActiveView('editor');
    } catch (error) {
      console.error(error);
      setStatus(GenerationStatus.ERROR);
    }
  };

  const handleGenerateImage = async (slideNumber: number) => {
    if (!currentCarousel) return;

    const slide = currentCarousel.slides.find(s => s.slide_number === slideNumber);
    if (!slide) return;

    setImageLoadingState(prev => ({ ...prev, [slideNumber]: true }));

    try {
      const metadata = { 
          ...currentCarousel.carousel_metadata, 
          character_description: characterDesc || currentCarousel.carousel_metadata.character_description 
      };

      const base64Image = await generateSlideImage(slide, metadata);
      setGeneratedImages(prev => ({
        ...prev,
        [currentCarousel.id]: {
            ...(prev[currentCarousel.id] || {}),
            [slideNumber]: base64Image
        }
      }));
    } catch (error) {
      console.error("Failed to generate image", error);
      alert("Failed to generate image. Please try again.");
    } finally {
      setImageLoadingState(prev => ({ ...prev, [slideNumber]: false }));
    }
  };

  const handleGenerateAllImages = async () => {
      if (!currentCarousel) return;
      const promises = currentCarousel.slides.map(slide => handleGenerateImage(slide.slide_number));
      await Promise.all(promises);
  };

  const handleUpdateSlide = (slideNumber: number, field: keyof Slide, value: any) => {
      if (!currentCarousel) return;
      const updatedSlides = currentCarousel.slides.map(slide => {
          if (slide.slide_number === slideNumber) {
              return { ...slide, [field]: value };
          }
          return slide;
      });
      setCurrentCarousel({ ...currentCarousel, slides: updatedSlides });
  };

  const handleUpdateDesign = (slideNumber: number, field: keyof SlideDesign, value: any) => {
    if (!currentCarousel) return;
    const updatedSlides = currentCarousel.slides.map(slide => {
        if (slide.slide_number === slideNumber) {
            return { 
                ...slide, 
                design: { ...slide.design, [field]: value }
            };
        }
        return slide;
    });
    setCurrentCarousel({ ...currentCarousel, slides: updatedSlides });
  };

  const saveToLibrary = () => {
      if (!currentCarousel) return;
      const carouselToSave = {
          ...currentCarousel,
          carousel_metadata: {
              ...currentCarousel.carousel_metadata,
              character_description: characterDesc
          }
      };

      const exists = library.find(c => c.id === carouselToSave.id);
      let newLibrary;
      if (exists) {
          newLibrary = library.map(c => c.id === carouselToSave.id ? carouselToSave : c);
      } else {
          newLibrary = [carouselToSave, ...library];
      }
      setLibrary(newLibrary);
      alert('Saved to Library!');
  };

  const loadFromLibrary = (carousel: CarouselResponse) => {
      setCurrentCarousel(carousel);
      setLanguage(carousel.carousel_metadata.language as 'en' | 'ar');
      setCharacterDesc(carousel.carousel_metadata.character_description || '');
      setActiveView('editor');
  };

  const deleteFromLibrary = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (confirm('Are you sure you want to delete this carousel?')) {
          setLibrary(prev => prev.filter(c => c.id !== id));
          const newImages = { ...generatedImages };
          delete newImages[id];
          setGeneratedImages(newImages);
          if (currentCarousel?.id === id) {
              setCurrentCarousel(null);
              setActiveView('create');
          }
      }
  };

  const exportJSON = () => {
      if (!currentCarousel) return;
      const exportData = {
          ...currentCarousel,
          _images: generatedImages[currentCarousel.id] || {}
      };
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", `carousel-${currentCarousel.carousel_metadata.topic.replace(/\s+/g, '-').toLowerCase()}.json`);
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
  };

  const exportPDF = async () => {
    if (!currentCarousel) return;
    const doc = new jsPDF({
        orientation: "portrait",
        unit: "px",
        format: [340, 450] // Match slide dimensions
    });

    const slideElements = document.querySelectorAll('[id^="slide-card-"]');

    for (let i = 0; i < slideElements.length; i++) {
        const el = slideElements[i] as HTMLElement;
        if (i > 0) doc.addPage();
        try {
            const canvas = await html2canvas(el, { 
                scale: 2, 
                useCORS: true,
                backgroundColor: null 
            });
            const imgData = canvas.toDataURL('image/png');
            doc.addImage(imgData, 'PNG', 0, 0, 340, 450);
        } catch (e) {
            console.error("Error exporting slide " + i, e);
        }
    }
    doc.save(`carousel-${currentCarousel.carousel_metadata.topic.slice(0, 20)}.pdf`);
  };

  return (
    <div className={`min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-blue-500/30 flex flex-col ${language === 'ar' ? 'font-[sans-serif]' : ''}`}>

      {/* Top Navigation Header */}
      <header className="sticky top-0 z-50 bg-slate-900/80 backdrop-blur-xl border-b border-slate-800 px-6 py-4 flex items-center justify-between shadow-sm">
         <div className="flex items-center gap-2">
            <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-blue-600 to-indigo-700 flex items-center justify-center shadow-[0_0_20px_rgba(37,99,235,0.3)]">
              <Layers className="w-5 h-5 text-white" />
            </div>
            <h1 className="font-bold text-xl tracking-tight text-white hidden md:block">Carousel<span className="text-blue-500">AI</span></h1>
         </div>

         <div className="flex bg-slate-800/80 rounded-xl p-1 border border-slate-700/50">
             {['create', 'editor', 'library'].map((mode) => (
                 <button 
                    key={mode}
                    onClick={() => setActiveView(mode as ViewMode)} 
                    disabled={mode === 'editor' && !currentCarousel}
                    className={`px-5 py-2 rounded-lg text-sm font-semibold transition-all capitalize ${activeView === mode ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50' : 'text-slate-400 hover:text-white disabled:opacity-40 disabled:hover:text-slate-400'}`}
                 >
                     {mode}
                 </button>
             ))}
         </div>

         <div className="flex gap-2">
            <button onClick={() => handleLanguageChange('en')} className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all border ${language === 'en' ? 'bg-slate-800 border-slate-600 text-white shadow-sm' : 'border-transparent text-slate-500 hover:text-white'}`}>ENG</button>
            <button onClick={() => handleLanguageChange('ar')} className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all border ${language === 'ar' ? 'bg-slate-800 border-slate-600 text-white shadow-sm' : 'border-transparent text-slate-500 hover:text-white'}`}>عربي</button>
         </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto bg-slate-950 p-6 md:p-8 custom-scrollbar" dir={language === 'ar' ? 'rtl' : 'ltr'}>

        {/* VIEW: CREATE */}
        {activeView === 'create' && (
            <div className="max-w-6xl mx-auto space-y-10 animate-in fade-in zoom-in-95 duration-500 pb-20">
                <div className="text-center space-y-3 mb-12 pt-10">
                    <h2 className="text-4xl md:text-5xl font-extrabold text-white tracking-tight">
                        {language === 'ar' ? 'أنشئ كاروسيل فيروسي' : 'Create Viral Carousels'}
                        <span className="text-blue-500">.</span>
                    </h2>
                    <p className="text-slate-400 text-lg max-w-2xl mx-auto">
                        {language === 'ar' ? 'ذكاء اصطناعي متطور لبناء محتوى LinkedIn و Instagram في ثوانٍ.' : 'Advanced AI to generate professional LinkedIn & Instagram strategies in seconds.'}
                    </p>
                </div>

                <form onSubmit={handleGenerateScript} className="space-y-6">

                    {/* Strategy Grid */}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

                        {/* Card 1: Content Strategy */}
                        <div className="bg-slate-900/50 border border-slate-800 rounded-2xl p-6 shadow-xl backdrop-blur-sm relative overflow-hidden group hover:border-slate-700 transition-colors">
                            <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/5 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>

                            <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
                                <Lightbulb className="w-5 h-5 text-blue-500" />
                                {language === 'ar' ? 'استراتيجية المحتوى' : 'Content Strategy'}
                            </h3>

                            <div className="space-y-5">
                                <div className="space-y-2">
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">{language === 'ar' ? 'الموضوع العام' : 'Main Theme'}</label>
                                    <div className="flex gap-2">
                                        <input
                                            type="text"
                                            value={mainTheme}
                                            onChange={(e) => setMainTheme(e.target.value)}
                                            placeholder={language === 'ar' ? 'مثل: ريادة الأعمال، الذكاء الاصطناعي...' : 'e.g. Entrepreneurship, AI, Fitness...'}
                                            className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-white placeholder-slate-600 focus:outline-none focus:border-blue-500 transition-all"
                                        />
                                        <button
                                            type="button"
                                            onClick={handleAutoGenerateIdeas}
                                            disabled={status === GenerationStatus.GENERATING_IDEAS}
                                            className="bg-blue-600/10 hover:bg-blue-600/20 text-blue-400 border border-blue-600/30 px-4 rounded-xl text-xs font-bold transition-colors flex items-center justify-center whitespace-nowrap min-w-[100px]"
                                        >
                                            {status === GenerationStatus.GENERATING_IDEAS ? <Sparkles className="animate-spin w-4 h-4"/> : (language === 'ar' ? 'اقتراح' : 'Auto-Fill')}
                                        </button>
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">{language === 'ar' ? 'العنوان المحدد' : 'Specific Topic'}</label>
                                    <input
                                        type="text"
                                        value={topic}
                                        onChange={(e) => setTopic(e.target.value)}
                                        placeholder={language === 'ar' ? '5 طرق لزيادة المبيعات...' : 'e.g. 5 Ways to Scale your SaaS...'}
                                        className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-white placeholder-slate-600 focus:outline-none focus:border-blue-500 transition-all"
                                        required
                                    />
                                </div>

                                <div className="space-y-2">
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">{language === 'ar' ? 'الجمهور' : 'Audience'}</label>
                                    <input
                                        type="text"
                                        value={targetAudience}
                                        onChange={(e) => setTargetAudience(e.target.value)}
                                        placeholder={language === 'ar' ? 'مؤسسي الشركات الناشئة...' : 'e.g. Startup Founders...'}
                                        className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-white placeholder-slate-600 focus:outline-none focus:border-blue-500 transition-all"
                                        required
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Card 2: Identity & Tone */}
                        <div className="bg-slate-900/50 border border-slate-800 rounded-2xl p-6 shadow-xl backdrop-blur-sm relative overflow-hidden group hover:border-slate-700 transition-colors">
                            <div className="absolute top-0 right-0 w-32 h-32 bg-purple-500/5 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>

                            <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
                                <MessageSquare className="w-5 h-5 text-purple-500" />
                                {language === 'ar' ? 'الهوية والنبرة' : 'Identity & Tone'}
                            </h3>

                            <div className="space-y-5">
                                <div className="space-y-2">
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">{language === 'ar' ? 'النبرة' : 'Voice Tone'}</label>
                                    <div className="flex flex-wrap gap-2">
                                        {(language === 'en' ? TONES_EN : TONES_AR).map((t) => (
                                            <button
                                                key={t}
                                                type="button"
                                                onClick={() => setTone(t)}
                                                className={`px-3 py-1.5 rounded-lg text-xs font-medium border transition-all ${tone === t ? 'bg-purple-600 border-purple-500 text-white shadow-md shadow-purple-900/20' : 'bg-slate-950 border-slate-800 text-slate-400 hover:border-slate-600'}`}
                                            >
                                                {t}
                                            </button>
                                        ))}
                                    </div>
                                </div>

                                {language === 'ar' && (
                                    <div className="space-y-2">
                                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">اللهجة</label>
                                        <input
                                            type="text"
                                            value={dialect}
                                            onChange={(e) => setDialect(e.target.value)}
                                            className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-white placeholder-slate-600 focus:outline-none focus:border-purple-500 transition-all"
                                            placeholder="تخصيص اللهجة (اختياري: مصرية، سعودية...)"
                                        />
                                    </div>
                                )}

                                <div className="space-y-2 pt-2">
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block">
                                        {language === 'ar' ? 'عدد الشرائح' : 'Slide Count'} ({slideCount})
                                    </label>
                                    <input 
                                        type="range" min="3" max="10" value={slideCount} onChange={(e) => setSlideCount(parseInt(e.target.value))}
                                        className="w-full h-2 bg-slate-950 rounded-lg appearance-none cursor-pointer accent-purple-500"
                                    />
                                    <div className="flex justify-between text-[10px] text-slate-500 font-mono">
                                        <span>3</span>
                                        <span>10</span>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Card 3: Visuals (Full Width) */}
                        <div className="lg:col-span-2 bg-slate-900/50 border border-slate-800 rounded-2xl p-6 shadow-xl backdrop-blur-sm relative overflow-hidden group hover:border-slate-700 transition-colors">
                            <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
                                <Palette className="w-5 h-5 text-indigo-500" />
                                {language === 'ar' ? 'الهوية البصرية' : 'Visual Identity'}
                            </h3>

                            <div className="space-y-6">
                                <div className="space-y-3">
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">{language === 'ar' ? 'النمط الفني' : 'Art Style'}</label>
                                    <div className="flex flex-wrap gap-2">
                                        {VISUAL_STYLES.map(style => (
                                            <button
                                                key={style}
                                                type="button"
                                                onClick={() => setVisualStyle(style)}
                                                className={`px-3 py-2 rounded-lg text-xs font-medium border transition-all flex items-center gap-1.5 ${visualStyle === style ? 'bg-indigo-600 border-indigo-500 text-white shadow-md shadow-indigo-900/20' : 'bg-slate-950 border-slate-800 text-slate-400 hover:border-slate-600'}`}
                                            >
                                                {visualStyle === style && <Check size={12}/>} {style}
                                            </button>
                                        ))}
                                    </div>
                                </div>

                                <div className="border-t border-slate-800 pt-6">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-start gap-4">
                                            <div className={`p-2 rounded-xl transition-colors ${useCharacter ? 'bg-blue-500/20 text-blue-400' : 'bg-slate-800 text-slate-500'}`}>
                                                <UserPlus size={24} />
                                            </div>
                                            <div>
                                                <h4 className="text-sm font-bold text-white">{language === 'ar' ? 'شخصية العلامة التجارية (AI)' : 'AI Brand Avatar'}</h4>
                                                <p className="text-xs text-slate-500 mt-1 max-w-md">
                                                    {language === 'ar' ? 'إضافة شخصية مخصصة تظهر في جميع الشرائح لزيادة الارتباط.' : 'Generate a consistent character that appears across all slides to boost engagement.'}
                                                </p>
                                            </div>
                                        </div>
                                        <button
                                            type="button" 
                                            onClick={() => setUseCharacter(!useCharacter)}
                                            className={`w-14 h-7 rounded-full p-1 transition-all duration-300 ${useCharacter ? 'bg-blue-600 shadow-[0_0_10px_rgba(37,99,235,0.4)]' : 'bg-slate-800'}`}
                                        >
                                            <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform duration-300 ${useCharacter ? 'translate-x-7' : 'translate-x-0'}`} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>

                    </div>

                    <div className="pt-4">
                        <button
                            type="submit"
                            disabled={status === GenerationStatus.GENERATING_SCRIPT}
                            className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-bold py-5 rounded-2xl shadow-xl shadow-blue-900/20 flex items-center justify-center gap-3 transition-all hover:scale-[1.01] active:scale-[0.99] disabled:opacity-50 disabled:scale-100 disabled:cursor-not-allowed text-lg border border-blue-500/20"
                        >
                            {status === GenerationStatus.GENERATING_SCRIPT ? (
                                <>
                                <Sparkles className="w-6 h-6 animate-spin" />
                                {language === 'ar' ? 'جاري تحليل التريندات...' : 'Analyzing Trends & Generating...'}
                                </>
                            ) : (
                                <>
                                <Zap className="w-6 h-6 fill-current" />
                                {language === 'ar' ? 'إنشاء الكاروسيل الآن' : 'Generate Carousel Now'}
                                </>
                            )}
                        </button>
                    </div>
                </form>
            </div>
        )}

        {/* VIEW: EDITOR */}
        {activeView === 'editor' && currentCarousel && (
            <div className="space-y-6 h-full flex flex-col animate-in fade-in slide-in-from-bottom-4 duration-500">
                <header className="flex flex-col md:flex-row md:items-center justify-between bg-slate-900 border border-slate-800 p-4 rounded-xl sticky top-0 z-20 gap-4 shadow-lg">
                    <div>
                        <h2 className="text-xl font-bold text-white max-w-md truncate">{currentCarousel.carousel_metadata.topic}</h2>
                        <div className="flex gap-2 text-xs text-slate-400 mt-1">
                            <span className="bg-slate-800 px-2 py-0.5 rounded border border-slate-700">{currentCarousel.carousel_metadata.visual_style}</span>
                            {currentCarousel.carousel_metadata.character_description && <span className="bg-blue-900/30 text-blue-300 px-2 py-0.5 rounded border border-blue-800">Has Character</span>}
                        </div>
                    </div>
                    <div className="flex flex-wrap items-center gap-2">
                        <button onClick={saveToLibrary} className="bg-slate-800 hover:bg-slate-700 text-white border border-slate-700 px-3 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2">
                            <Save className="w-4 h-4" /> Save
                        </button>
                        <button onClick={exportJSON} className="bg-slate-800 hover:bg-slate-700 text-white border border-slate-700 px-3 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2">
                            <Download className="w-4 h-4" /> JSON
                        </button>
                         <button onClick={exportPDF} className="bg-slate-800 hover:bg-slate-700 text-white border border-slate-700 px-3 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2">
                            <FileDown className="w-4 h-4" /> PDF
                        </button>
                        <button onClick={handleGenerateAllImages} className="bg-blue-600 hover:bg-blue-500 text-white px-3 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 shadow-lg shadow-blue-900/20">
                            <Sparkles className="w-4 h-4 text-yellow-300" /> Generate All
                        </button>
                    </div>
                </header>

                {/* Global Character Prompt Editor (If active) */}
                {useCharacter && (
                    <div className="bg-slate-900 border border-slate-800 p-4 rounded-xl flex gap-4 items-center animate-in slide-in-from-top-2">
                        <div className="bg-blue-600/20 p-2 rounded-lg">
                            <UserPlus className="w-5 h-5 text-blue-400" />
                        </div>
                        <div className="flex-1">
                            <label className="text-xs text-slate-500 font-bold uppercase block mb-1">Global Character Identity</label>
                            <input 
                                value={characterDesc}
                                onChange={(e) => setCharacterDesc(e.target.value)}
                                className="w-full bg-slate-950 border border-slate-800 rounded px-3 py-2 text-sm text-white focus:border-blue-500 outline-none transition-colors"
                                placeholder="Describe the character here to maintain consistency (e.g., A minimalist robot with glowing eyes)..."
                            />
                        </div>
                    </div>
                )}

                <div className="flex-1 overflow-x-auto pb-8 custom-scrollbar pt-2">
                    <div className="flex gap-8 w-max px-4 min-h-[500px] items-center">
                        {currentCarousel.slides.map((slide) => (
                            <SlideCard
                                key={slide.slide_number}
                                slide={slide}
                                imageData={generatedImages[currentCarousel.id]?.[slide.slide_number]}
                                isGeneratingImage={!!imageLoadingState[slide.slide_number]}
                                onGenerateImage={handleGenerateImage}
                                onUpdateSlide={handleUpdateSlide}
                                onUpdateDesign={handleUpdateDesign}
                                language={currentCarousel.carousel_metadata.language as 'en' | 'ar'}
                            />
                        ))}
                    </div>
                </div>
            </div>
        )}

        {/* VIEW: LIBRARY */}
        {activeView === 'library' && (
            <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in zoom-in-95 duration-500">
                <div className="flex items-center justify-between">
                    <h2 className="text-3xl font-bold text-white flex items-center gap-3">
                        <Archive className="w-8 h-8 text-blue-500" /> 
                        {language === 'ar' ? 'المكتبة' : 'Your Library'}
                    </h2>
                </div>

                {library.length === 0 ? (
                    <div className="text-center py-24 bg-slate-900/50 border border-slate-800 border-dashed rounded-3xl">
                        <div className="w-16 h-16 bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-6">
                            <Archive className="w-8 h-8 text-slate-500" />
                        </div>
                        <h3 className="text-xl font-bold text-white mb-2">No carousels yet</h3>
                        <p className="text-slate-500 mb-6">Start creating viral content today.</p>
                        <button onClick={() => setActiveView('create')} className="text-blue-500 font-semibold hover:text-blue-400 transition-colors">Create your first one &rarr;</button>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {library.map((item) => (
                            <div key={item.id} onClick={() => loadFromLibrary(item)} className="bg-slate-900 border border-slate-800 hover:border-blue-500/50 rounded-2xl p-6 cursor-pointer group transition-all hover:shadow-2xl hover:shadow-blue-900/10 hover:-translate-y-1 relative">
                                <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                                    <button onClick={(e) => deleteFromLibrary(item.id, e)} className="p-2 text-slate-500 hover:text-red-400 hover:bg-slate-800/80 rounded-lg backdrop-blur-sm transition-colors">
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                                <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-slate-800 to-slate-900 flex items-center justify-center mb-4 shadow-inner">
                                    <Layers className="w-5 h-5 text-blue-500" />
                                </div>
                                <h3 className="font-bold text-white text-lg mb-2 line-clamp-2 pr-8 leading-tight">{item.carousel_metadata.topic}</h3>
                                <div className="flex flex-wrap gap-2 mb-4 mt-4">
                                    <span className="text-[10px] uppercase font-bold tracking-wider bg-slate-800 text-slate-400 px-2 py-1 rounded border border-slate-700">
                                        {item.slides.length} Slides
                                    </span>
                                    <span className="text-[10px] uppercase font-bold tracking-wider bg-slate-800 text-slate-400 px-2 py-1 rounded border border-slate-700 truncate max-w-[120px]">
                                        {item.carousel_metadata.language === 'ar' ? 'Arabic' : 'English'}
                                    </span>
                                </div>
                                <div className="pt-4 border-t border-slate-800 flex justify-between items-center">
                                    <p className="text-xs text-slate-600">{new Date(item.createdAt).toLocaleDateString()}</p>
                                    <span className="text-xs text-blue-500 font-medium opacity-0 group-hover:opacity-100 transition-opacity">Open Editor &rarr;</span>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        )}

      </main>
    </div>
  );
}

export default App;

export interface CarouselMetadata {
  topic: string;
  visual_style: string;
  target_audience: string;
  language: 'en' | 'ar';
  tone: string;
  dialect?: string;
  main_theme?: string;
  character_description?: string; // Global character prompt
}

export interface SlideDesign {
  textColor: string;
  overlayOpacity: number;
  fontSize: 'small' | 'medium' | 'large' | 'xl';
  textAlign: 'left' | 'center' | 'right' | 'justify';
  xPosition: number; // 0 to 100 percentage
  yPosition: number; // 0 to 100 percentage
  textEffect: 'none' | 'shadow' | 'neon' | 'outline' | 'bg-highlight' | 'glitch' | 'retro';
  decoration: 'none' | 'circle' | 'square' | 'accent-line' | 'corner-shape' | 'grid' | 'blob' | 'frame';
}

export type CharacterPosition = 
  'top-left' | 'top-center' | 'top-right' | 
  'center-left' | 'center' | 'center-right' | 
  'bottom-left' | 'bottom-center' | 'bottom-right';

export interface CharacterSettings {
    scale: 'small' | 'medium' | 'large';
    position: CharacterPosition;
    opacity: number; // 0-100
    rotation: number; // -180 to 180
    expression: 'neutral' | 'happy' | 'serious' | 'surprised' | 'focused' | 'excited' | 'confused';
}

export interface Slide {
  slide_number: number;
  headline: string;
  sub_headline: string;
  visual_description: string;
  layout_hint: string;
  include_character: boolean; 
  character_custom_prompt?: string;
  character_settings: CharacterSettings;
  design: SlideDesign;
}

export interface CarouselResponse {
  id: string;
  createdAt: number;
  carousel_metadata: CarouselMetadata;
  slides: Slide[];
}

export enum GenerationStatus {
  IDLE = 'IDLE',
  GENERATING_IDEAS = 'GENERATING_IDEAS',
  GENERATING_SCRIPT = 'GENERATING_SCRIPT',
  GENERATING_IMAGES = 'GENERATING_IMAGES',
  COMPLETE = 'COMPLETE',
  ERROR = 'ERROR'
}

export type ViewMode = 'create' | 'editor' | 'library';

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { CarouselResponse, Slide } from "../types";

// Initialize Gemini Client
// @ts-ignore - Env variable is injected by the sandbox environment
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

const CAROUSEL_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    carousel_metadata: {
      type: Type.OBJECT,
      properties: {
        topic: { type: Type.STRING },
        visual_style: { type: Type.STRING },
        target_audience: { type: Type.STRING },
        language: { type: Type.STRING, enum: ['en', 'ar'] },
        tone: { type: Type.STRING },
        dialect: { type: Type.STRING },
        character_description: { type: Type.STRING },
      },
      required: ["topic", "visual_style", "target_audience", "character_description"],
    },
    slides: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          slide_number: { type: Type.INTEGER },
          headline: { type: Type.STRING },
          sub_headline: { type: Type.STRING },
          visual_description: { type: Type.STRING },
          layout_hint: { type: Type.STRING },
          include_character: { type: Type.BOOLEAN },
        },
        required: ["slide_number", "headline", "sub_headline", "visual_description", "layout_hint", "include_character"],
      },
    },
  },
  required: ["carousel_metadata", "slides"],
};

export const generateIdeas = async (
    theme: string, 
    language: 'en' | 'ar'
): Promise<{ topic: string, audience: string }> => {
    const model = "gemini-3-flash-preview";
    const langPrompt = language === 'ar' ? 'in Arabic' : 'in English';
    const prompt = `Generate a viral, trending social media topic and a specific target audience based on the theme: "${theme}". Return strictly JSON: { "topic": "...", "audience": "..." } ${langPrompt}.`;

    try {
        const response = await ai.models.generateContent({
            model,
            contents: prompt,
            config: { responseMimeType: "application/json" }
        });
        const text = response.text || "{}";
        return JSON.parse(text);
    } catch (e) {
        console.error("Error generating ideas", e);
        return { topic: "Growth Hacking Strategies", audience: "Startup Founders" };
    }
};

export const generateCarouselScript = async (
  topic: string,
  visualStyle: string,
  targetAudience: string,
  slideCount: number,
  language: 'en' | 'ar',
  tone: string,
  dialect: string,
  useCharacter: boolean
): Promise<CarouselResponse> => {
  const model = "gemini-3-flash-preview";

  const langInstruction = language === 'ar' 
    ? `Language: Arabic (Dialect/Style: ${dialect || 'Modern Standard Arabic'}). Ensure headlines are catchy in Arabic.`
    : `Language: English. Tone: ${tone}.`;

  const characterInstruction = useCharacter
    ? `Create a consistent character description (e.g., "A friendly 3D robot with a blue tie" or "A minimalist line-art business woman"). Populate 'character_description' with this. Set 'include_character' to true for slides where the character interacts with elements.`
    : `Leave 'character_description' empty. Set 'include_character' to false.`;

  const systemInstruction = `
    Role: You are a Senior Social Media Strategist.
    Objective: Generate a viral ${slideCount}-slide carousel.

    ${langInstruction}
    Target Audience: ${targetAudience}
    Tone: ${tone}
    Visual Style: ${visualStyle}

    ${characterInstruction}

    Structure:
    - Slide 1: Hook.
    - Middle: Value.
    - End: CTA.

    Visual Prompting:
    - In 'visual_description', describe the scene. If a character is used, just say "The Character [doing action]".
  `;

  const prompt = `Topic: ${topic}. Slides: ${slideCount}.`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: CAROUSEL_SCHEMA,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response text from Gemini");

    const data = JSON.parse(text);

    // Enrich with Default Design Properties
    const enrichedSlides = data.slides.map((slide: any) => ({
      ...slide,
      character_custom_prompt: "",
      character_settings: { 
          scale: 'medium', 
          position: 'center',
          opacity: 100,
          rotation: 0,
          expression: 'neutral'
      },
      design: {
        textColor: '#ffffff',
        overlayOpacity: 40,
        fontSize: 'medium',
        textAlign: language === 'ar' ? 'right' : 'left', // Initialize based on language
        xPosition: 50, // Center
        yPosition: 10, // Top area
        textEffect: 'shadow',
        decoration: 'none'
      }
    }));

    // Ensure metadata has all fields
    data.carousel_metadata.language = language;
    data.carousel_metadata.tone = tone;
    data.carousel_metadata.dialect = dialect;

    return {
        ...data,
        slides: enrichedSlides,
        id: crypto.randomUUID(),
        createdAt: Date.now()
    } as CarouselResponse;

  } catch (error) {
    console.error("Error generating script:", error);
    throw error;
  }
};

export const generateSlideImage = async (
  slide: Slide,
  metadata: any
): Promise<string> => {
  const model = "gemini-2.5-flash-image";

  let characterPromptPart = "";
  // Logic: Use per-slide custom prompt if available, otherwise use global description
  if (slide.include_character) {
      const charDesc = slide.character_custom_prompt || metadata.character_description;
      if (charDesc) {
         const s = slide.character_settings || { scale: 'medium', position: 'center', opacity: 100, rotation: 0, expression: 'neutral' };

         // Convert Position Enum to readable string
         const posMap: Record<string, string> = {
             'top-left': 'top left corner', 'top-center': 'top center', 'top-right': 'top right corner',
             'center-left': 'middle left', 'center': 'center', 'center-right': 'middle right',
             'bottom-left': 'bottom left corner', 'bottom-center': 'bottom center', 'bottom-right': 'bottom right corner'
         };
         const posStr = posMap[s.position] || 'center';

         // Opacity and Rotation Logic for Prompt
         let styleMods = "";
         if (s.opacity < 100) styleMods += `The character should look semi-transparent or ghostly (${s.opacity}% opacity). `;
         if (s.rotation !== 0) styleMods += `The character is tilted/rotated by approx ${s.rotation} degrees. `;
         const expressionMod = s.expression ? `Facial Expression: ${s.expression}.` : '';

         characterPromptPart = `Character Reference: ${charDesc}. \nPLACEMENT INSTRUCTION: Show the character at ${s.scale} scale, positioned in the ${posStr} of the frame. ${expressionMod} ${styleMods} The character is interacting with the scene.`;
      }
  }

  // Construct a prompt optimized for image generation
  const imagePrompt = `
    Create a social media background image (Aspect Ratio 4:5 Vertical).
    Style: ${metadata.visual_style}.
    Scene: ${slide.visual_description}.
    ${characterPromptPart}
    Constraint: NO TEXT in the image. High quality, aesthetic, clean background.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: { parts: [{ text: imagePrompt }] },
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
           return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
    }
    throw new Error("No image data found");
  } catch (error) {
    console.error("Error generating image:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Slide, SlideDesign, CharacterSettings, CharacterPosition } from '../types';
import { 
  Image, RefreshCw, Settings2, X, Move,
  Palette, BoxSelect, Sparkles, Layers,
  User, AlignLeft, AlignCenter, AlignRight, AlignJustify,
  Type, Layout, Grid, Frame, RotateCw, Ghost, Smile
} from 'lucide-react';

interface SlideCardProps {
  slide: Slide;
  imageData?: string;
  isGeneratingImage: boolean;
  onGenerateImage: (slideNumber: number) => void;
  onUpdateSlide: (slideNumber: number, field: keyof Slide, value: any) => void;
  onUpdateDesign: (slideNumber: number, field: keyof SlideDesign, value: any) => void;
  readOnly?: boolean;
  language?: 'en' | 'ar';
}

const SlideCard: React.FC<SlideCardProps> = ({ 
  slide, 
  imageData, 
  isGeneratingImage, 
  onGenerateImage,
  onUpdateSlide,
  onUpdateDesign,
  readOnly = false,
  language = 'en'
}) => {
  const [showSettings, setShowSettings] = useState(false);
  const [activeTab, setActiveTab] = useState<'layout' | 'text' | 'style' | 'char'>('layout');
  const design = slide.design;
  const isRTL = language === 'ar';

  const headlineRef = useRef<HTMLTextAreaElement>(null);
  const subheadRef = useRef<HTMLTextAreaElement>(null);

  // Auto-resize textareas
  const autoResize = (elem: HTMLTextAreaElement | null) => {
    if (elem) {
        elem.style.height = 'auto';
        elem.style.height = elem.scrollHeight + 'px';
    }
  };

  useEffect(() => {
    if (!readOnly) {
        autoResize(headlineRef.current);
        autoResize(subheadRef.current);
    }
  }, [slide.headline, slide.sub_headline, readOnly]);


  const getTextStyle = (isHeadline: boolean) => {
    const baseSize = isHeadline ? 'font-bold' : 'font-medium';

    let sizeClass = isHeadline ? 'text-2xl' : 'text-sm';
    if (design.fontSize === 'small') sizeClass = isHeadline ? 'text-xl' : 'text-xs';
    if (design.fontSize === 'large') sizeClass = isHeadline ? 'text-3xl' : 'text-base';
    if (design.fontSize === 'xl') sizeClass = isHeadline ? 'text-4xl' : 'text-lg';

    let effectClass = '';
    if (design.textEffect === 'shadow') effectClass = 'drop-shadow-lg shadow-black';
    if (design.textEffect === 'neon') effectClass = 'drop-shadow-[0_0_5px_rgba(255,255,255,0.8)]';
    if (design.textEffect === 'outline') effectClass = 'outline-text'; 
    if (design.textEffect === 'bg-highlight') effectClass = 'bg-black/50 px-2 rounded box-decoration-clone';
    if (design.textEffect === 'glitch') effectClass = 'glitch-text'; // Would need CSS implementation
    if (design.textEffect === 'retro') effectClass = 'text-yellow-400 drop-shadow-[2px_2px_0_rgba(0,0,0,1)]';

    // Alignment
    let alignClass = 'text-left';
    if (design.textAlign === 'center') alignClass = 'text-center';
    if (design.textAlign === 'right') alignClass = 'text-right';
    if (design.textAlign === 'justify') alignClass = 'text-justify';

    return `${baseSize} ${sizeClass} ${effectClass} ${alignClass}`;
  };

  const applyLayoutPreset = (type: 'default' | 'title-focus' | 'quote' | 'bottom-caption') => {
      if (type === 'default') {
          onUpdateDesign(slide.slide_number, 'textAlign', isRTL ? 'right' : 'left');
          onUpdateDesign(slide.slide_number, 'xPosition', 50);
          onUpdateDesign(slide.slide_number, 'yPosition', 10);
          onUpdateDesign(slide.slide_number, 'fontSize', 'medium');
          onUpdateDesign(slide.slide_number, 'decoration', 'none');
      } else if (type === 'title-focus') {
          onUpdateDesign(slide.slide_number, 'textAlign', 'center');
          onUpdateDesign(slide.slide_number, 'xPosition', 50);
          onUpdateDesign(slide.slide_number, 'yPosition', 40);
          onUpdateDesign(slide.slide_number, 'fontSize', 'xl');
      } else if (type === 'quote') {
          onUpdateDesign(slide.slide_number, 'textAlign', 'center');
          onUpdateDesign(slide.slide_number, 'xPosition', 50);
          onUpdateDesign(slide.slide_number, 'yPosition', 50);
          onUpdateDesign(slide.slide_number, 'fontSize', 'large');
          onUpdateDesign(slide.slide_number, 'decoration', 'accent-line');
      } else if (type === 'bottom-caption') {
          onUpdateDesign(slide.slide_number, 'textAlign', 'center');
          onUpdateDesign(slide.slide_number, 'xPosition', 50);
          onUpdateDesign(slide.slide_number, 'yPosition', 80);
          onUpdateDesign(slide.slide_number, 'fontSize', 'small');
          onUpdateDesign(slide.slide_number, 'decoration', 'none');
      }
  };

  const updateCharacterSetting = (field: keyof CharacterSettings, value: any) => {
      onUpdateSlide(slide.slide_number, 'character_settings', {
          ...slide.character_settings,
          [field]: value
      });
  };

  // Character Counts
  const MAX_HEADLINE = 60;
  const MAX_SUBHEAD = 120;

  const renderCounter = (current: number, max: number) => {
      const isNearLimit = current > max * 0.9;
      return (
          <span className={`text-[9px] absolute right-0 -bottom-4 ${isNearLimit ? 'text-red-400' : 'text-slate-500'}`}>
              {current}/{max}
          </span>
      );
  };

  return (
    <div 
        id={`slide-card-${slide.slide_number}`}
        className="flex-shrink-0 w-[340px] h-[450px] relative rounded-xl overflow-hidden shadow-2xl bg-slate-900 border border-slate-800 group transition-all duration-300 select-none"
    >

      {/* Background Image Layer */}
      <div className="absolute inset-0 z-0 bg-slate-950">
        {imageData ? (
          <img 
            src={imageData} 
            alt={`Slide ${slide.slide_number} visual`} 
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center text-slate-700 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-slate-900 to-slate-950">
            <div className="text-center p-4">
              <Image className="w-12 h-12 mx-auto mb-2 opacity-50 text-slate-600" />
              <p className="text-xs text-slate-600 font-medium">Visual description provided</p>
            </div>
          </div>
        )}

        <div 
          className="absolute inset-0 pointer-events-none transition-all duration-300"
          style={{ backgroundColor: `rgba(15, 23, 42, ${design.overlayOpacity / 100})` }}
        ></div>

        {/* Decorations */}
        {design.decoration === 'circle' && (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-48 h-48 border-4 border-white/20 rounded-full pointer-events-none"></div>
        )}
        {design.decoration === 'square' && (
          <div className="absolute top-4 right-4 bottom-4 left-4 border-2 border-white/20 pointer-events-none"></div>
        )}
        {design.decoration === 'accent-line' && (
           <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-24 h-1 bg-blue-500 pointer-events-none shadow-[0_0_10px_rgba(59,130,246,0.5)]"></div>
        )}
        {design.decoration === 'corner-shape' && (
           <div className="absolute top-0 right-0 w-24 h-24 bg-gradient-to-bl from-blue-500/50 to-transparent rounded-bl-full pointer-events-none"></div>
        )}
        {design.decoration === 'grid' && (
           <div className="absolute inset-0 bg-[linear-gradient(rgba(255,255,255,0.05)_1px,transparent_1px),linear-gradient(90deg,rgba(255,255,255,0.05)_1px,transparent_1px)] bg-[size:20px_20px] pointer-events-none"></div>
        )}
        {design.decoration === 'blob' && (
           <div className="absolute -top-10 -right-10 w-64 h-64 bg-blue-500/20 blur-3xl rounded-full pointer-events-none"></div>
        )}
        {design.decoration === 'frame' && (
           <div className="absolute inset-3 border border-white/30 rounded-lg pointer-events-none"></div>
        )}
      </div>

      {/* Main Content Layer */}
      <div 
        className="absolute z-10 w-[85%] transition-all duration-100 ease-out flex flex-col gap-2"
        style={{ 
            top: `${design.yPosition}%`, 
            left: `${design.xPosition}%`,
            transform: 'translate(-50%, 0)', // Center horizontally relative to left point
            direction: isRTL ? 'rtl' : 'ltr'
        }}
      >
            {readOnly ? (
                <>
                    <h2 
                        className={`leading-tight whitespace-pre-wrap ${getTextStyle(true)}`}
                        style={{ color: design.textColor }}
                    >
                        {slide.headline}
                    </h2>
                    <p 
                        className={`leading-relaxed opacity-90 whitespace-pre-wrap ${getTextStyle(false)}`}
                        style={{ color: design.textColor }}
                    >
                        {slide.sub_headline}
                    </p>
                </>
            ) : (
                <>
                    <div className="relative w-full group/input">
                        <textarea 
                            ref={headlineRef}
                            value={slide.headline}
                            onChange={(e) => onUpdateSlide(slide.slide_number, 'headline', e.target.value)}
                            className={`bg-transparent border border-dashed border-transparent group-hover/input:border-white/20 rounded w-full resize-none focus:outline-none focus:bg-slate-900/40 p-1 overflow-hidden transition-colors ${getTextStyle(true)}`}
                            style={{ color: design.textColor }}
                            rows={1}
                            placeholder={isRTL ? "العنوان الرئيسي" : "Headline"}
                        />
                        {renderCounter(slide.headline.length, MAX_HEADLINE)}
                    </div>

                    <div className="relative w-full group/input">
                        <textarea 
                            ref={subheadRef}
                            value={slide.sub_headline}
                            onChange={(e) => onUpdateSlide(slide.slide_number, 'sub_headline', e.target.value)}
                            className={`bg-transparent border border-dashed border-transparent group-hover/input:border-white/20 rounded w-full resize-none focus:outline-none focus:bg-slate-900/40 p-1 overflow-hidden transition-colors ${getTextStyle(false)}`}
                            style={{ color: design.textColor }}
                            rows={1}
                            placeholder={isRTL ? "العنوان الفرعي" : "Sub-headline"}
                        />
                        {renderCounter(slide.sub_headline.length, MAX_SUBHEAD)}
                    </div>
                </>
            )}
      </div>

      {/* Slide Number Badge */}
      <div className={`absolute top-4 ${isRTL ? 'right-4' : 'left-4'} z-20`}>
             <div className="bg-slate-900/80 text-slate-400 text-[10px] font-bold px-2 py-1 rounded backdrop-blur-sm border border-slate-700 shadow-sm">
                #{slide.slide_number}
             </div>
      </div>

      {/* Edit Button */}
      {!readOnly && (
            <button 
                onClick={() => setShowSettings(!showSettings)}
                className={`absolute top-4 ${isRTL ? 'left-4' : 'right-4'} z-20 p-2 rounded-lg backdrop-blur-md transition-all shadow-sm ${showSettings ? 'bg-blue-600 text-white shadow-blue-900/20' : 'bg-white/10 text-white hover:bg-white/20'}`}
                data-html2canvas-ignore="true"
            >
                {showSettings ? <X size={16} /> : <Settings2 size={16} />}
            </button>
      )}

      {/* Settings Overlay Panel */}
      {showSettings && !readOnly && (
        <div 
            className="absolute bottom-0 left-0 right-0 bg-slate-900/95 backdrop-blur-xl border-t border-slate-700 z-30 animate-in slide-in-from-bottom-10 duration-200 shadow-[0_-5px_20px_rgba(0,0,0,0.3)] h-[320px] overflow-hidden flex flex-col"
            data-html2canvas-ignore="true"
        >
            {/* Tabs */}
            <div className="flex border-b border-slate-800 bg-slate-900 z-10 shrink-0">
                <button onClick={() => setActiveTab('layout')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-1.5 transition-colors ${activeTab === 'layout' ? 'text-blue-400 bg-slate-800/50 border-b-2 border-blue-500' : 'text-slate-500 hover:text-slate-300 hover:bg-slate-800/30'}`}>
