            data-html2canvas-ignore="true"
        >
            {/* Tabs */}
            <div className={`flex border-b border-slate-800 bg-slate-900 z-10 shrink-0 ${isRTL ? 'font-arabic' : ''}`} dir={isRTL ? 'rtl' : 'ltr'}>
