                <button onClick={() => setActiveTab('text')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-1.5 transition-colors ${activeTab === 'text' ? 'text-blue-400 bg-slate-800/50 border-b-2 border-blue-500' : 'text-slate-500 hover:text-slate-300 hover:bg-slate-800/30'}`}>
                    <Type size={12} /> {isRTL ? 'نص' : 'Text'}
                </button>
                <button onClick={() => setActiveTab('style')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-1.5 transition-colors ${activeTab === 'style' ? 'text-blue-400 bg-slate-800/50 border-b-2 border-blue-500' : 'text-slate-500 hover:text-slate-300 hover:bg-slate-800/30'}`}>
                    <Palette size={12} /> {isRTL ? 'تصميم' : 'Style'}
                </button>
                <button onClick={() => setActiveTab('char')} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-1.5 transition-colors ${activeTab === 'char' ? 'text-blue-400 bg-slate-800/50 border-b-2 border-blue-500' : 'text-slate-500 hover:text-slate-300 hover:bg-slate-800/30'}`}>
                    <User size={12} /> {isRTL ? 'شخصية' : 'Char'}
                </button>
            </div>

            <div className={`p-4 overflow-y-auto custom-scrollbar flex-1 ${isRTL ? 'font-arabic' : ''}`} dir={isRTL ? 'rtl' : 'ltr'}>
                {/* --- LAYOUT TAB --- */}
                {activeTab === 'layout' && (
                    <div className="space-y-4">
                        <div className="space-y-2">
                             <label className="text-[10px] text-slate-500 font-bold uppercase block tracking-wider">Presets</label>
                             <div className="grid grid-cols-2 gap-2">
                                 <button onClick={() => applyLayoutPreset('default')} className="text-[10px] p-2 bg-slate-800 border border-slate-700 rounded hover:bg-slate-700 hover:border-slate-600 transition-all text-slate-300">Standard</button>
                                 <button onClick={() => applyLayoutPreset('title-focus')} className="text-[10px] p-2 bg-slate-800 border border-slate-700 rounded hover:bg-slate-700 hover:border-slate-600 transition-all text-slate-300">Headline Focus</button>
                                 <button onClick={() => applyLayoutPreset('quote')} className="text-[10px] p-2 bg-slate-800 border border-slate-700 rounded hover:bg-slate-700 hover:border-slate-600 transition-all text-slate-300 flex items-center justify-center gap-1"><Sparkles size={10} className="text-blue-400"/> Quote Style</button>
                                 <button onClick={() => applyLayoutPreset('bottom-caption')} className="text-[10px] p-2 bg-slate-800 border border-slate-700 rounded hover:bg-slate-700 hover:border-slate-600 transition-all text-slate-300">Bottom Caption</button>
                             </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-[10px] text-slate-500 font-bold uppercase block flex items-center gap-1 tracking-wider"><Move size={10}/> Fine Tune Position</label>
                            <div className="space-y-3 bg-slate-800/30 p-3 rounded border border-slate-800">
                                <div className="flex items-center gap-3">
                                     <span className="text-[9px] text-slate-500 font-mono w-4">X%</span>
                                     <input 
                                        type="range" min="0" max="100" 
                                        value={design.xPosition} 
                                        onChange={(e) => onUpdateDesign(slide.slide_number, 'xPosition', parseInt(e.target.value))}
                                        className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                                    />
                                </div>
                                <div className="flex items-center gap-3">
                                     <span className="text-[9px] text-slate-500 font-mono w-4">Y%</span>
                                     <input 
                                        type="range" min="0" max="100" 
                                        value={design.yPosition} 
                                        onChange={(e) => onUpdateDesign(slide.slide_number, 'yPosition', parseInt(e.target.value))}
                                        className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                                    />
                                </div>
                            </div>
                        </div>
                    </div>
                )}
                 {/* --- TEXT TAB --- */}
                {activeTab === 'text' && (
                    <div className="space-y-4">
                        <div className="space-y-2">
                            <label className="text-[10px] text-slate-500 font-bold uppercase block tracking-wider">Alignment</label>
                            <div className="flex gap-1 bg-slate-800/50 p-1 rounded-lg border border-slate-800">
                                <button onClick={() => onUpdateDesign(slide.slide_number, 'textAlign', 'left')} className={`flex-1 p-1.5 rounded flex justify-center transition-all ${design.textAlign === 'left' ? 'bg-blue-600 text-white shadow-sm' : 'hover:bg-slate-700 text-slate-400'}`}><AlignLeft size={14}/></button>
                                <button onClick={() => onUpdateDesign(slide.slide_number, 'textAlign', 'center')} className={`flex-1 p-1.5 rounded flex justify-center transition-all ${design.textAlign === 'center' ? 'bg-blue-600 text-white shadow-sm' : 'hover:bg-slate-700 text-slate-400'}`}><AlignCenter size={14}/></button>
                                <button onClick={() => onUpdateDesign(slide.slide_number, 'textAlign', 'right')} className={`flex-1 p-1.5 rounded flex justify-center transition-all ${design.textAlign === 'right' ? 'bg-blue-600 text-white shadow-sm' : 'hover:bg-slate-700 text-slate-400'}`}><AlignRight size={14}/></button>
                                <button onClick={() => onUpdateDesign(slide.slide_number, 'textAlign', 'justify')} className={`flex-1 p-1.5 rounded flex justify-center transition-all ${design.textAlign === 'justify' ? 'bg-blue-600 text-white shadow-sm' : 'hover:bg-slate-700 text-slate-400'}`}><AlignJustify size={14}/></button>
                            </div>
                        </div>

                        <div className="space-y-2">
                             <label className="text-[10px] text-slate-500 font-bold uppercase block tracking-wider">Typography</label>
                             <div className="flex gap-2 items-center">
                                <div className="relative w-8 h-8 rounded-full border border-slate-600 overflow-hidden cursor-pointer shadow-sm hover:border-white transition-colors">
                                    <input 
                                        type="color" 
                                        value={design.textColor}
                                        onChange={(e) => onUpdateDesign(slide.slide_number, 'textColor', e.target.value)}
                                        className="absolute -top-2 -left-2 w-16 h-16 cursor-pointer"
                                    />
                                </div>
                                <select 
                                    value={design.fontSize}
                                    onChange={(e) => onUpdateDesign(slide.slide_number, 'fontSize', e.target.value)}
                                    className="bg-slate-800 text-slate-200 text-xs py-1.5 px-3 rounded-lg border border-slate-700 outline-none flex-1 hover:border-slate-500 transition-colors"
                                >
                                    <option value="small">Small Text</option>
                                    <option value="medium">Medium Text</option>
                                    <option value="large">Large Text</option>
                                    <option value="xl">Extra Large</option>
                                </select>
                             </div>
                        </div>

                         <div className="space-y-2">
                             <label className="text-[10px] text-slate-500 font-bold uppercase block tracking-wider">Effects</label>
                             <div className="grid grid-cols-3 gap-1.5">
                                 {['none', 'shadow', 'neon', 'outline', 'bg-highlight', 'glitch', 'retro'].map(eff => (
                                     <button 
                                        key={eff}
                                        onClick={() => onUpdateDesign(slide.slide_number, 'textEffect', eff)}
                                        className={`text-[10px] py-1.5 rounded border transition-all ${design.textEffect === eff ? 'bg-blue-600 border-blue-500 text-white shadow-sm' : 'bg-slate-800 border-slate-800 text-slate-400 hover:border-slate-600 hover:text-slate-300'}`}
                                     >
                                        {eff}
                                     </button>
                                 ))}
                             </div>
                         </div>
                    </div>
                )}
                {/* --- STYLE TAB --- */}
                {activeTab === 'style' && (
                     <div className="space-y-4">
                        <div className="space-y-2">
                             <label className="text-[10px] text-slate-500 font-bold uppercase block tracking-wider">Patterns</label>
                             <div className="grid grid-cols-4 gap-2">
                                 {[
                                     { id: 'none', label: 'None', icon: X },
                                     { id: 'grid', label: 'Grid', icon: Grid },
                                     { id: 'frame', label: 'Frame', icon: Frame },
                                     { id: 'blob', label: 'Blob', icon: Sparkles },
                                     { id: 'circle', label: 'Circle', icon: BoxSelect },
                                     { id: 'square', label: 'Square', icon: BoxSelect },
                                     { id: 'accent-line', label: 'Line', icon: BoxSelect },
                                     { id: 'corner-shape', label: 'Corner', icon: Layers },
                                 ].map((d) => (
                                     <button
                                        key={d.id}
                                        onClick={() => onUpdateDesign(slide.slide_number, 'decoration', d.id)}
                                        className={`flex flex-col items-center justify-center p-2 rounded-lg border gap-1 h-14 transition-all ${design.decoration === d.id ? 'bg-blue-600 border-blue-500 text-white shadow-sm' : 'bg-slate-800 border-slate-800 text-slate-400 hover:border-slate-600 hover:text-slate-300'}`}
                                     >
                                         <d.icon size={12} />
                                         <span className="text-[9px]">{d.label}</span>
                                     </button>
                                 ))}
                             </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-[10px] text-slate-500 font-bold uppercase block tracking-wider">Overlay Darkness</label>
                            <input 
                                type="range" min="0" max="90" 
                                value={design.overlayOpacity} 
                                onChange={(e) => onUpdateDesign(slide.slide_number, 'overlayOpacity', parseInt(e.target.value))}
                                className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                            />
                        </div>
                         <div className="pt-3 border-t border-slate-800">
                             <div className="flex gap-2">
                                <input
                                    value={slide.visual_description}
                                    onChange={(e) => onUpdateSlide(slide.slide_number, 'visual_description', e.target.value)}
                                    className="flex-1 bg-slate-950 text-xs text-slate-300 border border-slate-800 rounded px-3 py-2 focus:border-blue-500 focus:outline-none transition-all placeholder-slate-600"
                                    placeholder="Edit visual prompt..."
                                />
                                <button
                                    onClick={() => onGenerateImage(slide.slide_number)}
                                    disabled={isGeneratingImage}
                                    className="bg-blue-600 hover:bg-blue-500 text-white p-2 rounded disabled:opacity-50 transition-colors shadow-sm"
                                    title="Regenerate Image"
                                >
                                    {isGeneratingImage ? <RefreshCw size={14} className="animate-spin" /> : <Image size={14} />}
                                </button>
                            </div>
                        </div>
                     </div>
                )}
                 {/* --- CHARACTER TAB --- */}
                {activeTab === 'char' && (
                    <div className="space-y-4">
                         <div className="space-y-2">
                            <button
                                onClick={() => onUpdateSlide(slide.slide_number, 'include_character', !slide.include_character)}
                                className={`w-full py-2.5 rounded-lg flex items-center justify-center border text-xs font-bold transition-all ${slide.include_character ? 'bg-blue-600 border-blue-500 text-white shadow-md shadow-blue-900/20' : 'bg-slate-800 border-slate-800 text-slate-500 hover:bg-slate-700'}`}
                            >
                                <User size={14} className="mr-2"/> {slide.include_character ? 'Character Active' : 'Character Disabled'}
                            </button>
                        </div>

                        {slide.include_character && (
                            <div className="space-y-4 animate-in slide-in-from-right-5 duration-200">

                                <div className="space-y-1">
                                    <label className="text-[10px] text-slate-500 font-bold uppercase block tracking-wider">Anchor Position</label>
                                    <div className="grid grid-cols-3 gap-1.5 bg-slate-800/30 p-2 rounded-xl border border-slate-800">
                                        {[
                                            'top-left', 'top-center', 'top-right',
                                            'center-left', 'center', 'center-right',
                                            'bottom-left', 'bottom-center', 'bottom-right'
                                        ].map(pos => {
                                            const active = (slide.character_settings?.position || 'center') === pos;
                                            return (
                                                <button
                                                    key={pos}
                                                    onClick={() => updateCharacterSetting('position', pos)}
                                                    className={`aspect-square rounded flex items-center justify-center transition-all ${active ? 'bg-blue-600 text-white shadow-sm' : 'bg-slate-700/50 hover:bg-slate-600 text-slate-400'}`}
                                                    title={pos}
                                                >
                                                    <div className={`w-1.5 h-1.5 rounded-full ${active ? 'bg-white' : 'bg-slate-500'}`}></div>
                                                </button>
                                            )
                                        })}
                                    </div>
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                     <div className="space-y-1">
                                        <label className="text-[10px] text-slate-500 font-bold uppercase block tracking-wider">Scale</label>
                                        <select 
                                            value={slide.character_settings?.scale || 'medium'}
                                            onChange={(e) => updateCharacterSetting('scale', e.target.value)}
                                            className="w-full bg-slate-800 text-slate-200 text-xs py-1.5 px-2 rounded-lg border border-slate-700 outline-none hover:border-slate-500"
                                        >
                                            <option value="small">Small (Bg)</option>
                                            <option value="medium">Medium</option>
                                            <option value="large">Large (Fg)</option>
                                        </select>
                                     </div>
                                     <div className="space-y-1">
                                        <label className="text-[10px] text-slate-500 font-bold uppercase block tracking-wider flex items-center gap-1"><Smile size={10}/> Expression</label>
                                        <select 
                                            value={slide.character_settings?.expression || 'neutral'}
                                            onChange={(e) => updateCharacterSetting('expression', e.target.value)}
                                            className="w-full bg-slate-800 text-slate-200 text-xs py-1.5 px-2 rounded-lg border border-slate-700 outline-none hover:border-slate-500"
                                        >
                                            <option value="neutral">Neutral</option>
                                            <option value="happy">Happy</option>
                                            <option value="serious">Serious</option>
                                            <option value="surprised">Surprised</option>
                                            <option value="focused">Focused</option>
                                            <option value="excited">Excited</option>
                                        </select>
                                     </div>
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="space-y-1">
                                        <label className="text-[10px] text-slate-500 font-bold uppercase block flex items-center gap-1 tracking-wider"><Ghost size={8}/> Opacity</label>
                                        <input 
                                            type="range" min="10" max="100" 
                                            value={slide.character_settings?.opacity ?? 100} 
                                            onChange={(e) => updateCharacterSetting('opacity', parseInt(e.target.value))}
                                            className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                                            title="Lower values prompt for transparency"
                                        />
                                    </div>
                                    <div className="space-y-1">
                                        <label className="text-[10px] text-slate-500 font-bold uppercase block flex items-center gap-1 tracking-wider"><RotateCw size={8}/> Rotation</label>
                                        <input 
                                            type="range" min="-180" max="180" 
                                            value={slide.character_settings?.rotation ?? 0} 
                                            onChange={(e) => updateCharacterSetting('rotation', parseInt(e.target.value))}
                                            className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                                        />
                                    </div>
                                </div>

                                <div className="space-y-1">
                                    <label className="text-[10px] text-blue-400 font-bold uppercase block tracking-wider">Action Override</label>
                                    <textarea 
                                        value={slide.character_custom_prompt || ''}
                                        onChange={(e) => onUpdateSlide(slide.slide_number, 'character_custom_prompt', e.target.value)}
                                        placeholder="e.g. Holding a magnifying glass..."
                                        className="w-full bg-slate-950/50 border border-blue-500/30 rounded px-2 py-2 text-xs text-slate-300 focus:outline-none focus:border-blue-500 h-14 resize-none placeholder-slate-600"
                                    />
                                    <p className="text-[9px] text-slate-600 text-right">Requires regeneration</p>
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
      )}
    </div>
  );
};

export default SlideCard;

import React, { useState, useEffect } from 'react';
import { Sparkles, Wand2, Layers, Download, Palette, Users, Type, Save, Archive, Play, Trash2, Edit3, Grid, Globe, UserPlus, Zap, FileDown, Check, Lightbulb, MessageSquare, Scaling } from 'lucide-react';
import { generateCarouselScript, generateSlideImage, generateIdeas } from './services/geminiService';
import { CarouselResponse, GenerationStatus, ViewMode, Slide, SlideDesign, CharacterTraits } from './types';
import SlideCard from './components/SlideCard';
// @ts-ignore
import { jsPDF } from "jspdf";
// @ts-ignore
import html2canvas from "html2canvas";

const VISUAL_STYLES = [
  "Minimalist & Clean",
  "Cyberpunk Neon",
  "Corporate Memphis",
  "Dark Mode Gradient",
  "Abstract Geometric",
  "Vintage Paper Texture",
  "3D Claymorphism",
  "Futuristic Tech",
  "Glassmorphism",
  "Brutalism",
  "Retro Pop Art",
  "Swiss International",
  "Doodle & Sketch",
  "Nature & Organic",
  "Hand Drawn", 
  "Collage", 
  "Pixar Style", 
  "Watercolor", 
  "Editorial", 
  "High Contrast", 
  "Isometric 3D"
];

const TONES_EN = [
    "Professional", "Casual", "Humorous", "Inspirational", "Educational", "Controversial", "Empathetic", "Urgent", "Witty"
];

const TONES_AR = [
    "Professional (رسمي)", "Friendly (ودود)", "Inspirational (ملهم)", "Sarcastic (ساخر)", "Educational (تعليمي)", "Urgent (عاجل)", "Serious (جدي)"
];

function App() {
  // --- View State ---
  const [activeView, setActiveView] = useState<ViewMode>('create');

  // --- Input State ---
  const [topic, setTopic] = useState('');
  const [visualStyle, setVisualStyle] = useState(VISUAL_STYLES[0]);
  const [targetAudience, setTargetAudience] = useState('');
  const [slideCount, setSlideCount] = useState<number>(5);
  const [aspectRatio, setAspectRatio] = useState<'4:5' | '1:1' | '16:9'>('4:5');

  // New Input States
  const [language, setLanguage] = useState<'en' | 'ar'>('en');
  const [tone, setTone] = useState(TONES_EN[0]);
  const [dialect, setDialect] = useState(''); // Only for Arabic
  const [mainTheme, setMainTheme] = useState('');
  const [useCharacter, setUseCharacter] = useState(false);
  const [characterDesc, setCharacterDesc] = useState(''); 

  // Character Details
  const [charGender, setCharGender] = useState<'neutral' | 'male' | 'female'>('neutral');
  const [charStyle, setCharStyle] = useState<'3d-render' | 'flat-vector' | 'hand-drawn' | 'anime' | 'realistic' | 'pixel-art'>('3d-render');
  const [charAge, setCharAge] = useState<'child' | 'young-adult' | 'adult' | 'elderly'>('adult');
  const [charColor, setCharColor] = useState('Blue');

  // --- Data State ---
  const [currentCarousel, setCurrentCarousel] = useState<CarouselResponse | null>(null);
  const [generatedImages, setGeneratedImages] = useState<Record<string, Record<number, string>>>({});
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [imageLoadingState, setImageLoadingState] = useState<Record<number, boolean>>({});

  // --- History State ---
  const [library, setLibrary] = useState<CarouselResponse[]>([]);

  // Load library from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('carousel_library');
    if (saved) {
      try {
        setLibrary(JSON.parse(saved));
      } catch (e) { console.error("Failed to load library", e); }
    }
  }, []);

  // Save library when it changes
  useEffect(() => {
    try {
        localStorage.setItem('carousel_library', JSON.stringify(library));
    } catch (e) {
        console.error("Failed to save library (quota exceeded)", e);
    }
  }, [library]);

  const handleLanguageChange = (lang: 'en' | 'ar') => {
      setLanguage(lang);
      // Reset tone to first available for that language to ensure consistency
      setTone(lang === 'en' ? TONES_EN[0] : TONES_AR[0]);
  };

  const handleAutoGenerateIdeas = async () => {
     if (!mainTheme) {
         alert("Please enter a Main Theme first.");
         return;
     }
     setStatus(GenerationStatus.GENERATING_IDEAS);
     try {
         const idea = await generateIdeas(mainTheme, language);
         setTopic(idea.topic);
         setTargetAudience(idea.audience);
     } catch (e) {
         console.error(e);
     } finally {
         setStatus(GenerationStatus.IDLE);
     }
  };

  const handleGenerateScript = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic || !targetAudience) return;

    setStatus(GenerationStatus.GENERATING_SCRIPT);

    const characterTraits: CharacterTraits = {
        gender: charGender,
        style: charStyle,
        age: charAge,
        color_accent: charColor
    };

    try {
      const data = await generateCarouselScript(
          topic, visualStyle, targetAudience, slideCount, 
          language, tone, dialect, useCharacter, aspectRatio, characterTraits
      );

      // If user wants a character, populate the state with what the AI came up with
      if (useCharacter && data.carousel_metadata.character_description) {
          setCharacterDesc(data.carousel_metadata.character_description);
      }

      setCurrentCarousel(data);
      setStatus(GenerationStatus.COMPLETE);
      setActiveView('editor');
    } catch (error) {
      console.error(error);
      setStatus(GenerationStatus.ERROR);
    }
  };

  const handleGenerateImage = async (slideNumber: number) => {
    if (!currentCarousel) return;

    const slide = currentCarousel.slides.find(s => s.slide_number === slideNumber);
    if (!slide) return;

    setImageLoadingState(prev => ({ ...prev, [slideNumber]: true }));

    try {
      const metadata = { 
          ...currentCarousel.carousel_metadata, 
          character_description: characterDesc || currentCarousel.carousel_metadata.character_description 
      };

      const base64Image = await generateSlideImage(slide, metadata);
      setGeneratedImages(prev => ({
        ...prev,
        [currentCarousel.id]: {
            ...(prev[currentCarousel.id] || {}),
            [slideNumber]: base64Image
        }
      }));
    } catch (error) {
      console.error("Failed to generate image", error);
      alert("Failed to generate image. Please try again.");
    } finally {
      setImageLoadingState(prev => ({ ...prev, [slideNumber]: false }));
    }
  };

  const handleGenerateAllImages = async () => {
      if (!currentCarousel) return;
      const promises = currentCarousel.slides.map(slide => handleGenerateImage(slide.slide_number));
      await Promise.all(promises);
  };

  const handleUpdateSlide = (slideNumber: number, field: keyof Slide, value: any) => {
      if (!currentCarousel) return;
      const updatedSlides = currentCarousel.slides.map(slide => {
          if (slide.slide_number === slideNumber) {
              return { ...slide, [field]: value };
          }
          return slide;
      });
      setCurrentCarousel({ ...currentCarousel, slides: updatedSlides });
  };

  const handleUpdateDesign = (slideNumber: number, field: keyof SlideDesign, value: any) => {
    if (!currentCarousel) return;
    const updatedSlides = currentCarousel.slides.map(slide => {
        if (slide.slide_number === slideNumber) {
            return { 
                ...slide, 
                design: { ...slide.design, [field]: value }
            };
        }
        return slide;
    });
    setCurrentCarousel({ ...currentCarousel, slides: updatedSlides });
  };

  const saveToLibrary = () => {
      if (!currentCarousel) return;
      const carouselToSave = {
          ...currentCarousel,
          carousel_metadata: {
              ...currentCarousel.carousel_metadata,
              character_description: characterDesc
          }
      };

      const exists = library.find(c => c.id === carouselToSave.id);
      let newLibrary;
      if (exists) {
          newLibrary = library.map(c => c.id === carouselToSave.id ? carouselToSave : c);
      } else {
          newLibrary = [carouselToSave, ...library];
      }
      setLibrary(newLibrary);
      alert('Saved to Library!');
  };

  const loadFromLibrary = (carousel: CarouselResponse) => {
      setCurrentCarousel(carousel);
      setLanguage(carousel.carousel_metadata.language as 'en' | 'ar');
      setAspectRatio(carousel.carousel_metadata.aspect_ratio || '4:5');
      setCharacterDesc(carousel.carousel_metadata.character_description || '');
      setActiveView('editor');
  };

  const deleteFromLibrary = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (confirm('Are you sure you want to delete this carousel?')) {
          setLibrary(prev => prev.filter(c => c.id !== id));
          const newImages = { ...generatedImages };
          delete newImages[id];
          setGeneratedImages(newImages);
          if (currentCarousel?.id === id) {
              setCurrentCarousel(null);
              setActiveView('create');
          }
      }
  };

  const exportJSON = () => {
      if (!currentCarousel) return;
      const exportData = {
          ...currentCarousel,
          _images: generatedImages[currentCarousel.id] || {}
      };
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", `carousel-${currentCarousel.carousel_metadata.topic.replace(/\s+/g, '-').toLowerCase()}.json`);
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
  };

  const exportPDF = async () => {
    if (!currentCarousel) return;

    // Determine page size based on aspect ratio in POINTS (1 pt = 1/72 inch)
    // IMPORTANT: Must match dimensions in SlideCard.tsx
    let width = 340; 
    let height = 425; 

    if (currentCarousel.carousel_metadata.aspect_ratio === '1:1') {
        height = 340;
    } else if (currentCarousel.carousel_metadata.aspect_ratio === '16:9') {
        width = 560; // Increased width for 16:9 to match SlideCard
        height = 315; 
    }

    const doc = new jsPDF({
        orientation: width > height ? "landscape" : "portrait",
        unit: "pt", // Use Points for better standard PDF compliance
        format: [width, height],
        hotfixes: ["px_scaling"]
    });

    const slideElements = document.querySelectorAll('[id^="slide-card-"]');

    for (let i = 0; i < slideElements.length; i++) {
        const el = slideElements[i] as HTMLElement;
        if (i > 0) doc.addPage([width, height]);

        try {
            // High Scale for crisp text (4x)
            const canvas = await html2canvas(el, { 
                scale: 4, 
                useCORS: true,
                backgroundColor: null,
                logging: false,
                allowTaint: true,
                ignoreElements: (element) => {
                     return element.hasAttribute('data-html2canvas-ignore');
                }
            });
            const imgData = canvas.toDataURL('image/png', 1.0);
            doc.addImage(imgData, 'PNG', 0, 0, width, height, undefined, 'FAST');
        } catch (e) {
            console.error("Error exporting slide " + i, e);
        }
    }
    doc.save(`carousel-${currentCarousel.carousel_metadata.topic.slice(0, 20)}.pdf`);
  };

  return (
    <div className={`min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-blue-500/30 flex flex-col ${language === 'ar' ? 'font-arabic' : ''}`}>

      {/* Top Navigation Header */}
      <header className="sticky top-0 z-50 bg-slate-900/80 backdrop-blur-xl border-b border-slate-800 px-6 py-4 flex items-center justify-between shadow-sm">
         <div className="flex items-center gap-2">
            <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-blue-600 to-indigo-700 flex items-center justify-center shadow-[0_0_20px_rgba(37,99,235,0.3)]">
              <Layers className="w-5 h-5 text-white" />
            </div>
            <h1 className="font-bold text-xl tracking-tight text-white hidden md:block">Carousel<span className="text-blue-500">AI</span></h1>
         </div>

         <div className="flex bg-slate-800/80 rounded-xl p-1 border border-slate-700/50" dir={language === 'ar' ? 'rtl' : 'ltr'}>
             {['create', 'editor', 'library'].map((mode) => (
                 <button 
                    key={mode}
                    onClick={() => setActiveView(mode as ViewMode)} 
                    disabled={mode === 'editor' && !currentCarousel}
                    className={`px-5 py-2 rounded-lg text-sm font-semibold transition-all capitalize ${activeView === mode ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/50' : 'text-slate-400 hover:text-white disabled:opacity-40 disabled:hover:text-slate-400'}`}
                 >
                     {mode}
