                            <div className="space-y-5">
                                <div className="space-y-2">
                                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">{language === 'ar' ? 'النبرة' : 'Voice Tone'}</label>
                                    <div className="flex flex-wrap gap-2">
                                        {(language === 'en' ? TONES_EN : TONES_AR).map((t) => (
                                            <button
                                                key={t}
                                                type="button"
                                                onClick={() => setTone(t)}
                                                className={`px-3 py-1.5 rounded-lg text-xs font-medium border transition-all ${tone === t ? 'bg-purple-600 border-purple-500 text-white shadow-md shadow-purple-900/20' : 'bg-slate-950 border-slate-800 text-slate-400 hover:border-slate-600'}`}
                                            >
                                                {t}
                                            </button>
                                        ))}
                                    </div>
                                </div>

                                {language === 'ar' && (
                                    <div className="space-y-2">
                                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">اللهجة</label>
                                        <input
                                            type="text"
                                            value={dialect}
