import { GoogleGenAI, Type, Schema } from "@google/genai";
import { CarouselResponse, Slide, CharacterTraits, BrandColors } from "../types";

// Initialize Gemini Client
// @ts-ignore - Env variable is injected by the sandbox environment
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

const CAROUSEL_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    carousel_metadata: {
      type: Type.OBJECT,
      properties: {
        topic: { type: Type.STRING },
        visual_style: { type: Type.STRING },
        target_audience: { type: Type.STRING },
        language: { type: Type.STRING, enum: ['en', 'ar'] },
        tone: { type: Type.STRING },
        dialect: { type: Type.STRING },
        character_description: { type: Type.STRING },
      },
      required: ["topic", "visual_style", "target_audience", "character_description"],
    },
    slides: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          slide_number: { type: Type.INTEGER },
          headline: { type: Type.STRING },
          sub_headline: { type: Type.STRING },
          visual_description: { type: Type.STRING },
          layout_hint: { type: Type.STRING },
          include_character: { type: Type.BOOLEAN },
        },
        required: ["slide_number", "headline", "sub_headline", "visual_description", "layout_hint", "include_character"],
      },
    },
  },
  required: ["carousel_metadata", "slides"],
};

export const generateIdeas = async (
    theme: string, 
    language: 'en' | 'ar'
): Promise<{ topic: string, audience: string }> => {
    const model = "gemini-3-flash-preview";
    const langPrompt = language === 'ar' ? 'in Arabic' : 'in English';
    const prompt = `Generate a viral, trending social media topic and a specific target audience based on the theme: "${theme}". Return strictly JSON: { "topic": "...", "audience": "..." } ${langPrompt}.`;

    try {
        const response = await ai.models.generateContent({
            model,
            contents: prompt,
            config: { responseMimeType: "application/json" }
        });
        const text = response.text || "{}";
        return JSON.parse(text);
    } catch (e) {
        console.error("Error generating ideas", e);
        return { topic: "Growth Hacking Strategies", audience: "Startup Founders" };
    }
};

export const generateCarouselScript = async (
  topic: string,
  visualStyle: string,
  target_audience: string,
  slideCount: number,
  language: 'en' | 'ar',
  tone: string,
  dialect: string,
  useCharacter: boolean,
  aspectRatio: '4:5' | '1:1' | '16:9',
  characterTraits?: CharacterTraits,
  brandColors?: BrandColors
): Promise<CarouselResponse> => {
  const model = "gemini-3-flash-preview";

  const langInstruction = language === 'ar' 
    ? `Language: Arabic (Dialect/Style: ${dialect || 'Modern Standard Arabic'}). IMPORTANT: Ensure headlines are catchy, short, and strictly in Arabic script. Use culturally relevant metaphors.`
    : `Language: English. Tone: ${tone}.`;

  // Build a specific character description based on traits
  let charDescInstructions = "";
  if (useCharacter && characterTraits) {
      const baseDesc = `A ${characterTraits.age} ${characterTraits.gender} character, style ${characterTraits.style}, main color ${characterTraits.color_accent}`;
      charDescInstructions = `
      CRITICAL: Create a fixed "Visual DNA" for the character based on: "${baseDesc}".
      In 'character_description', write a prompt that defines IMMUTABLE traits to ensure consistency across multiple images.
      Include:
      1. Precise Hairstyle & Color (e.g., "short messy neon-blue undercut")
      2. Exact Outfit (e.g., "orange oversized hoodie with white drawstrings")
      3. Face/Body Features (e.g., "round face, freckles, wearing aviator sunglasses")
      4. Art Style keywords matching '${characterTraits.style}'.
      Example: "3D render, cute robot with a square head, rusty yellow metal texture, one glowing blue eye, wearing a red scarf, pixar lighting."
      `;
  } else {
      charDescInstructions = `Leave 'character_description' empty. Set 'include_character' to false.`;
  }

  const systemInstruction = `
    Role: You are a Senior Social Media Strategist and Visual Director.
    Objective: Generate a viral ${slideCount}-slide carousel.

    ${langInstruction}
    Target Audience: ${target_audience}
    Tone: ${tone}
    Visual Style: ${visualStyle}
    Aspect Ratio: ${aspectRatio}

    ${charDescInstructions}

    Structure:
    - Slide 1: Hook (High contrast, big text).
    - Middle: Value/Educational.
    - End: CTA.

    Visual Prompting:
    - In 'visual_description', describe the scene layout. Keep it compatible with the character interacting with it.
  `;

  const prompt = `Topic: ${topic}. Slides: ${slideCount}.`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: CAROUSEL_SCHEMA,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response text from Gemini");

    const data = JSON.parse(text);

    // Enrich with Default Design Properties using Brand Colors if provided
    const enrichedSlides = data.slides.map((slide: any) => ({
      ...slide,
      character_custom_prompt: "",
      character_settings: { 
          scale: 'medium', 
          position: 'center',
          opacity: 100,
          rotation: 0,
          expression: 'neutral'
      },
      design: {
        textColor: brandColors?.text || '#ffffff',
        accentColor: brandColors?.accent || '#3b82f6', 
        textBackgroundColor: '#000000', // Default black
        textBackgroundOpacity: 0, // Default transparent
        overlayOpacity: 10, 
        fontSize: 'medium',
        font: 'sans',
        textAlign: language === 'ar' ? 'right' : 'left', // Initialize based on language
        xPosition: 50, // Center
        yPosition: 10, // Top area
        textEffect: 'shadow',
        decoration: 'none'
      }
    }));

    // Ensure metadata has all fields
    data.carousel_metadata.language = language;
    data.carousel_metadata.tone = tone;
    data.carousel_metadata.dialect = dialect;
    data.carousel_metadata.aspect_ratio = aspectRatio;
    data.carousel_metadata.character_traits = characterTraits;
    data.carousel_metadata.brand_colors = brandColors;

    return {
        ...data,
        slides: enrichedSlides,
        id: crypto.randomUUID(),
        createdAt: Date.now()
    } as CarouselResponse;

  } catch (error) {
    console.error("Error generating script:", error);
    throw error;
  }
};

export const generateSlideImage = async (
  slide: Slide,
  metadata: any
): Promise<string> => {
  const model = "gemini-2.5-flash-image";

  let characterPromptPart = "";

  if (slide.include_character) {
      // Prioritize consistency by always including the global character DNA
      const globalCharDNA = metadata.character_description || "";
      const customAction = slide.character_custom_prompt || "Standing confidently";

      if (globalCharDNA) {
         const s = slide.character_settings || { scale: 'medium', position: 'center', opacity: 100, rotation: 0, expression: 'neutral' };

         const posMap: Record<string, string> = {
             'top-left': 'top left corner', 'top-center': 'top center', 'top-right': 'top right corner',
             'center-left': 'middle left', 'center': 'center', 'center-right': 'middle right',
             'bottom-left': 'bottom left corner', 'bottom-center': 'bottom center', 'bottom-right': 'bottom right corner'
         };
         const posStr = posMap[s.position] || 'center';

         let styleMods = "";
         if (s.opacity < 100) styleMods += `(Appearance: semi-transparent/holographic at ${s.opacity}% opacity). `;
         if (s.rotation !== 0) styleMods += `(Orientation: tilted ${s.rotation} degrees). `;
         const expressionMod = s.expression ? `Expression: ${s.expression}.` : '';

         // Construct a Prompt that emphasizes the DNA
         // STRICT CONSISTENCY PATTERN
         characterPromptPart = `
         *** CHARACTER REFERENCE SHEET (MUST MATCH EXACTLY) ***
         Visual DNA: ${globalCharDNA}.

         *** CURRENT SCENE ACTION ***
         Action: ${customAction}. ${expressionMod}
         Camera/Framing: Subject is at ${s.scale} scale, positioned in the ${posStr}. ${styleMods}
         `;
      }
  }

  const ar = metadata.aspect_ratio || '4:5';
  const aspectRatioPrompt = ar === '1:1' ? 'Square Aspect Ratio 1:1' : ar === '16:9' ? 'Wide Aspect Ratio 16:9' : 'Vertical Aspect Ratio 4:5';

  const imagePrompt = `
    Task: Generate a high-quality social media background image (${aspectRatioPrompt}).

    Visual Style: ${metadata.visual_style}.
    Environment/Background: ${slide.visual_description}.

    ${characterPromptPart}

    Constraint: NO TEXT in the image. Pure visual art.
  `;

  // Determine Aspect Ratio for API
  let apiAspectRatio = "4:5"; 
  if (ar === '1:1') apiAspectRatio = "1:1";
  if (ar === '16:9') apiAspectRatio = "16:9";

  try {
    const response = await ai.models.generateContent({
      model,
      contents: { parts: [{ text: imagePrompt }] },
      config: {
          imageConfig: {
              aspectRatio: apiAspectRatio as any
          }
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
           return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
    }
    throw new Error("No image data found");
  } catch (error) {
    console.error("Error generating image:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Slide, SlideDesign } from '../types';
import { Image, ImagePlus, AlertCircle, RefreshCw } from 'lucide-react';

interface SlideCardProps {
  slide: Slide;
  imageData?: string;
  isGeneratingImage: boolean;
  isError?: boolean;
  onGenerateImage: () => void;
  onUpdateSlide: (slideNumber: number, field: keyof Slide, value: any) => void;
  readOnly?: boolean;
  language?: 'en' | 'ar';
  aspectRatio?: '4:5' | '1:1' | '16:9';
  isSelected?: boolean;
  onSelect?: () => void;
}

const SlideCard: React.FC<SlideCardProps> = ({ 
  slide, 
  imageData, 
  isGeneratingImage, 
  isError = false,
  onGenerateImage,
  onUpdateSlide,
  readOnly = false,
  language = 'en',
  aspectRatio = '4:5',
  isSelected = false,
  onSelect
}) => {
  const design = slide.design;
  const isRTL = language === 'ar';
  const headlineRef = useRef<HTMLTextAreaElement>(null);
  const subheadRef = useRef<HTMLTextAreaElement>(null);

  // Auto-resize
  const autoResize = (elem: HTMLTextAreaElement | null) => {
    if (elem) {
        elem.style.height = 'auto'; 
        elem.style.height = `${elem.scrollHeight + 4}px`;
    }
  };

  useEffect(() => {
    const timer = setTimeout(() => {
        autoResize(headlineRef.current);
        autoResize(subheadRef.current);
    }, 10);
    return () => clearTimeout(timer);
  }, [slide.headline, slide.sub_headline, aspectRatio, design.font]);

  const getTextStyle = (isHeadline: boolean) => {
    const baseSize = isHeadline ? 'font-bold' : 'font-medium';
    let sizeClass = isHeadline ? 'text-2xl' : 'text-sm';
    if (design.fontSize === 'small') sizeClass = isHeadline ? 'text-xl' : 'text-xs';
    if (design.fontSize === 'large') sizeClass = isHeadline ? 'text-3xl' : 'text-base';
    if (design.fontSize === 'xl') sizeClass = isHeadline ? 'text-4xl' : 'text-lg';

    let effectClass = '';
    if (design.textEffect === 'shadow') effectClass = 'drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)]'; 
    if (design.textEffect === 'neon') effectClass = 'drop-shadow-[0_0_5px_rgba(255,255,255,0.8)]';
    if (design.textEffect === 'outline') effectClass = '[text-shadow:_-1px_-1px_0_#000,_1px_-1px_0_#000,_-1px_1px_0_#000,_1px_1px_0_#000]'; 
    // Removed bg-highlight from here to handle it via dynamic styles or keep it as a preset effect combo
    if (design.textEffect === 'bg-highlight') effectClass = 'drop-shadow-sm'; 
    if (design.textEffect === 'retro') effectClass = 'drop-shadow-[2px_2px_0_rgba(0,0,0,1)]';

    let alignClass = 'text-left';
    if (design.textAlign === 'center') alignClass = 'text-center';
    if (design.textAlign === 'right') alignClass = 'text-right';
    if (design.textAlign === 'justify') alignClass = 'text-justify';

    const lineHeight = isRTL ? 'leading-relaxed' : 'leading-normal';

    // Font handling
    let fontClass = 'font-sans';
    if (!isRTL) {
        if (design.font === 'serif') fontClass = 'font-serif';
        if (design.font === 'mono') fontClass = 'font-mono';
        if (design.font === 'display') fontClass = 'font-[system-ui] tracking-tighter';
    }

    return `${baseSize} ${sizeClass} ${effectClass} ${alignClass} ${lineHeight} ${fontClass}`;
  };

  const getDimensions = () => {
      switch(aspectRatio) {
          case '1:1': return { width: '340px', height: '340px' };
          case '16:9': return { width: '560px', height: '315px' }; 
          case '4:5': 
          default: return { width: '340px', height: '425px' };
      }
  };

  const dim = getDimensions();

  // Helper for hex to rgba
  const hexToRgba = (hex: string, alpha: number) => {
      let c: any;
      if(/^#([A-Fa-f0-9]{3}){1,2}$/.test(hex)){
          c = hex.substring(1).split('');
          if(c.length === 3){
              c= [c[0], c[0], c[1], c[1], c[2], c[2]];
          }
          c = '0x'+c.join('');
          return 'rgba('+[(c>>16)&255, (c>>8)&255, c&255].join(',')+',' + (alpha/100) +')';
      }
      return hex; // Fallback
  };

  const textBgStyle = {
      backgroundColor: hexToRgba(design.textBackgroundColor || '#000000', design.textBackgroundOpacity || 0),
      boxDecorationBreak: 'clone' as any,
      WebkitBoxDecorationBreak: 'clone' as any,
      padding: '0.25rem 0.5rem',
      borderRadius: '0.25rem'
  };

  // Helper to convert hex to rgba for backgrounds requiring opacity if needed
  const accentStyle = { color: design.accentColor };
  const accentBgStyle = { backgroundColor: design.accentColor };
  const accentBorderStyle = { borderColor: design.accentColor };

  return (
    <div 
        id={`slide-card-${slide.slide_number}`}
        onClick={onSelect}
        className={`flex-shrink-0 relative rounded-xl overflow-hidden bg-slate-900 group transition-all duration-300 select-none print:shadow-none cursor-pointer border-2 ${isSelected ? 'border-blue-500 shadow-[0_0_30px_rgba(59,130,246,0.3)] scale-[1.01]' : 'border-slate-800 hover:border-slate-600'}`}
        style={{ width: dim.width, height: dim.height }}
    >

      {/* Background Layer */}
      <div className="absolute inset-0 z-0 bg-slate-950">
        {imageData ? (
          <img 
            src={imageData} 
            alt={`Slide ${slide.slide_number} visual`} 
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center text-slate-700 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-slate-900 to-slate-950">
            <div className="text-center p-4 flex flex-col items-center gap-3">
              {isGeneratingImage ? (
                  <>
                    <div className="animate-spin w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full mx-auto"/>
                    <p className="text-xs text-slate-500 font-medium">Generating...</p>
                  </>
              ) : isError ? (
                  <>
                    <AlertCircle className="w-10 h-10 text-red-500 opacity-80" />
                    <p className="text-xs text-red-400 font-medium max-w-[150px]">Image generation failed.</p>
                    <button 
                        onClick={(e) => { e.stopPropagation(); onGenerateImage(); }}
                        className="flex items-center gap-1 text-[10px] bg-red-900/50 hover:bg-red-900 border border-red-800 text-red-200 px-3 py-1.5 rounded-full transition-colors mt-1"
                    >
                        <RefreshCw size={12} /> Retry
                    </button>
                  </>
              ) : (
                  <>
                    <ImagePlus className="w-12 h-12 mx-auto opacity-30 text-slate-600" />
                    <p className="text-xs text-slate-600 font-medium">No Image</p>
                  </>
              )}
            </div>
          </div>
        )}

        {/* Overlay */}
        <div 
          className="absolute inset-0 pointer-events-none transition-all duration-300 z-0"
          style={{ backgroundColor: `rgba(15, 23, 42, ${design.overlayOpacity / 100})` }}
        ></div>

        {/* Decorations using Dynamic Accent Color */}
        {design.decoration === 'circle' && (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-48 h-48 border-4 rounded-full pointer-events-none opacity-50" style={accentBorderStyle}></div>
        )}
        {design.decoration === 'square' && (
          <div className="absolute top-4 right-4 bottom-4 left-4 border-2 pointer-events-none opacity-50" style={accentBorderStyle}></div>
        )}
        {design.decoration === 'accent-line' && (
           <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-24 h-1 pointer-events-none shadow-lg" style={accentBgStyle}></div>
        )}
        {design.decoration === 'corner-shape' && (
           <div className="absolute top-0 right-0 w-24 h-24 rounded-bl-full pointer-events-none opacity-50" style={{ background: `linear-gradient(to bottom left, ${design.accentColor}, transparent)` }}></div>
        )}
        {design.decoration === 'grid' && (
           <div className="absolute inset-0 bg-[linear-gradient(rgba(255,255,255,0.05)_1px,transparent_1px),linear-gradient(90deg,rgba(255,255,255,0.05)_1px,transparent_1px)] bg-[size:20px_20px] pointer-events-none"></div>
        )}
        {design.decoration === 'blob' && (
           <div className="absolute -top-10 -right-10 w-64 h-64 blur-3xl rounded-full pointer-events-none opacity-30" style={accentBgStyle}></div>
        )}
        {design.decoration === 'frame' && (
           <div className="absolute inset-3 border rounded-lg pointer-events-none opacity-50" style={accentBorderStyle}></div>
        )}
      </div>

      {/* Main Content Layer */}
      <div 
        className={`absolute z-10 w-[85%] transition-all duration-100 ease-out flex flex-col gap-3 ${isRTL ? 'font-arabic' : ''}`}
        style={{ 
            top: `${design.yPosition}%`, 
            left: `${design.xPosition}%`,
            transform: 'translate(-50%, 0)', 
            direction: isRTL ? 'rtl' : 'ltr'
        }}
        dir={isRTL ? 'rtl' : 'ltr'}
      >
            {readOnly ? (
                <>
                    {/* Render with span to apply background to the inline text only if needed, 
                        but block display with width is usually better for background box. 
                        Here we use a block wrapper for the background style. */}
                    <div style={design.textBackgroundOpacity > 0 ? textBgStyle : {}}>
                        <h2 
                            className={`whitespace-pre-wrap ${getTextStyle(true)}`}
                            style={{ color: design.textColor, ...(design.textEffect === 'neon' ? { textShadow: `0 0 10px ${design.accentColor}` } : {}) }}
                        >
                            {slide.headline}
                        </h2>
                    </div>
                    <div style={design.textBackgroundOpacity > 0 ? textBgStyle : {}}>
                        <p 
                            className={`opacity-90 whitespace-pre-wrap ${getTextStyle(false)}`}
                            style={{ color: design.textColor }}
                        >
                            {slide.sub_headline}
                        </p>
                    </div>
                </>
            ) : (
                <>
                    <div className="relative w-full group/input">
                        <textarea 
                            ref={headlineRef}
                            value={slide.headline}
                            onChange={(e) => onUpdateSlide(slide.slide_number, 'headline', e.target.value)}
                            className={`bg-transparent border border-dashed border-transparent hover:border-white/30 focus:border-blue-500/50 rounded w-full resize-none focus:outline-none focus:ring-0 p-1 overflow-hidden transition-all ${getTextStyle(true)}`}
                            style={{ 
                                color: design.textColor, 
                                ...(design.textEffect === 'neon' ? { textShadow: `0 0 10px ${design.accentColor}` } : {}),
                                ...(design.textBackgroundOpacity > 0 ? textBgStyle : {})
                            }}
                            rows={1}
                            placeholder={isRTL ? "العنوان الرئيسي" : "Headline"}
                            dir={isRTL ? 'rtl' : 'ltr'}
                        />
                    </div>

                    <div className="relative w-full group/input">
                        <textarea 
                            ref={subheadRef}
                            value={slide.sub_headline}
                            onChange={(e) => onUpdateSlide(slide.slide_number, 'sub_headline', e.target.value)}
                            className={`bg-transparent border border-dashed border-transparent hover:border-white/30 focus:border-blue-500/50 rounded w-full resize-none focus:outline-none focus:ring-0 p-1 overflow-hidden transition-all ${getTextStyle(false)}`}
                            style={{ 
                                color: design.textColor,
                                ...(design.textBackgroundOpacity > 0 ? textBgStyle : {})
                            }}
                            rows={1}
                            placeholder={isRTL ? "العنوان الفرعي" : "Sub-headline"}
                            dir={isRTL ? 'rtl' : 'ltr'}
                        />
                    </div>
                </>
            )}
      </div>

      {/* Slide Number Badge */}
      <div 
        className={`absolute top-4 ${isRTL ? 'right-4' : 'left-4'} z-20`}
        data-html2canvas-ignore="true"
      >
             <div className="bg-slate-900/80 text-slate-400 text-[10px] font-bold px-2 py-1 rounded backdrop-blur-sm border border-slate-700 shadow-sm flex items-center gap-1">
                #{slide.slide_number}
                {isError && <AlertCircle size={10} className="text-red-500" />}
             </div>
      </div>
    </div>
  );
};

export default SlideCard;

import React, { useState, useEffect, useRef } from 'react';
import { Sparkles, Layers, Download, Palette, Type, Save, Archive, Trash2, Grid, UserPlus, Zap, FileDown, Check, Lightbulb, MessageSquare, Scaling, Layout, Move, AlignLeft, AlignCenter, AlignRight, AlignJustify, X, Frame, BoxSelect, User, Smile, Ghost, RotateCw, RefreshCw, Image as ImageIcon, Camera, AlertTriangle } from 'lucide-react';
import { generateCarouselScript, generateSlideImage, generateIdeas } from './services/geminiService';
import { CarouselResponse, GenerationStatus, ViewMode, Slide, SlideDesign, CharacterTraits, CharacterSettings, BrandColors } from './types';
import SlideCard from './components/SlideCard';
// @ts-ignore
import { jsPDF } from "jspdf";
// @ts-ignore
import html2canvas from "html2canvas";

// Categorized Visual Styles for better variety
const VISUAL_STYLES_CATEGORIES = {
    "Professional": ["Minimalist Clean", "Tech Startup", "Corporate Blue", "Modern SaaS", "Swiss International", "Editorial"],
    "Creative & Artistic": ["Hand Drawn Sketch", "Watercolor", "Pop Art", "Collage", "Doodle Style", "Oil Painting", "Pastel Dream"],
    "3D & Textured": ["3D Claymorphism", "Glassmorphism", "3D Isometric", "Paper Cutout", "Fabric Texture", "Plastic Sheen", "Matte 3D"],
    "Dark & Vibrant": ["Cyberpunk Neon", "Dark Mode Gradient", "Holographic", "Vaporwave", "Neon Noir", "Glowwave", "High Contrast Dark"],
    "Retro & Vintage": ["Vintage 90s", "Retro 80s", "Bauhaus", "Grunge", "Lo-Fi Aesthetic", "Film Grain", "Noir"],
    "Nature & Soft": ["Organic Green", "Earthy Tones", "Botanical", "Soft Gradient", "Warm Beige"]
};

// Flatten for dropdown but keep categorized logic if needed later
const ALL_VISUAL_STYLES = Object.values(VISUAL_STYLES_CATEGORIES).flat();

const TONES_EN = ["Professional", "Casual", "Humorous", "Inspirational", "Educational", "Controversial", "Empathetic", "Urgent", "Witty"];
const TONES_AR = ["Professional (رسمي)", "Friendly (ودود)", "Inspirational (ملهم)", "Sarcastic (ساخر)", "Educational (تعليمي)", "Urgent (عاجل)", "Serious (جدي)"];

const DIALECTS = [
    { id: 'msa', label: 'Modern Standard (الفصحى)' },
    { id: 'egyptian', label: 'Egyptian (المصرية)' },
    { id: 'saudi', label: 'Saudi/Gulf (السعودية/الخليجية)' },
    { id: 'levantine', label: 'Levantine (الشامية)' },
    { id: 'maghrebi', label: 'Maghrebi (المغربية/الجزائرية)' }
];

const COLOR_PALETTES = [
    { name: "Default", text: "#ffffff", accent: "#3b82f6" },
    { name: "Ocean", text: "#e0f2fe", accent: "#0284c7" },
    { name: "Sunset", text: "#fff7ed", accent: "#f97316" },
    { name: "Forest", text: "#f0fdf4", accent: "#16a34a" },
    { name: "Berry", text: "#fdf2f8", accent: "#db2777" },
    { name: "Monochrome", text: "#ffffff", accent: "#94a3b8" },
    { name: "Dark", text: "#0f172a", accent: "#64748b" }, // For light backgrounds
    { name: "Gold", text: "#ffffff", accent: "#fbbf24" },
];

function App() {
  const [activeView, setActiveView] = useState<ViewMode>('create');

  // Create State
  const [topic, setTopic] = useState('');
  const [visualStyle, setVisualStyle] = useState(ALL_VISUAL_STYLES[0]);
  const [targetAudience, setTargetAudience] = useState('');
  const [slideCount, setSlideCount] = useState<number>(5);
  const [aspectRatio, setAspectRatio] = useState<'4:5' | '1:1' | '16:9'>('4:5');
  const [language, setLanguage] = useState<'en' | 'ar'>('en');
  const [tone, setTone] = useState(TONES_EN[0]);
  const [dialect, setDialect] = useState('');
  const [mainTheme, setMainTheme] = useState('');
  const [brandColors, setBrandColors] = useState<BrandColors>({ text: '#ffffff', accent: '#3b82f6' });
  const [useCharacter, setUseCharacter] = useState(false);
  const [characterDesc, setCharacterDesc] = useState(''); 
  const [charGender, setCharGender] = useState<'neutral' | 'male' | 'female'>('neutral');
  const [charStyle, setCharStyle] = useState<CharacterTraits['style']>('3d-render');
  const [charAge, setCharAge] = useState<'child' | 'young-adult' | 'adult' | 'elderly'>('adult');
  const [charColor, setCharColor] = useState('Blue');

  // Editor State
  const [currentCarousel, setCurrentCarousel] = useState<CarouselResponse | null>(null);
  const [generatedImages, setGeneratedImages] = useState<Record<string, Record<number, string>>>({});
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [imageLoadingState, setImageLoadingState] = useState<Record<number, boolean>>({});
  const [imageErrorState, setImageErrorState] = useState<Record<number, boolean>>({});
  const [selectedSlideIndex, setSelectedSlideIndex] = useState<number>(0);
  const [activeTab, setActiveTab] = useState<'layout' | 'text' | 'style' | 'char'>('layout');
  const [isExporting, setIsExporting] = useState(false);

  // History
  const [library, setLibrary] = useState<CarouselResponse[]>([]);

  useEffect(() => {
    const saved = localStorage.getItem('carousel_library');
    if (saved) { try { setLibrary(JSON.parse(saved)); } catch (e) { console.error(e); } }
  }, []);

  useEffect(() => {
    try { localStorage.setItem('carousel_library', JSON.stringify(library)); } catch (e) { console.error(e); }
  }, [library]);

  const handleLanguageChange = (lang: 'en' | 'ar') => {
      setLanguage(lang);
      setTone(lang === 'en' ? TONES_EN[0] : TONES_AR[0]);
      if (currentCarousel) {
          setCurrentCarousel({
              ...currentCarousel,
              carousel_metadata: { ...currentCarousel.carousel_metadata, language: lang }
          });
      }
  };

  const handleAutoGenerateIdeas = async () => {
     if (!mainTheme) { alert("Please enter a Main Theme first."); return; }
     setStatus(GenerationStatus.GENERATING_IDEAS);
     try {
         const idea = await generateIdeas(mainTheme, language);
         setTopic(idea.topic);
         setTargetAudience(idea.audience);
     } catch (e) { console.error(e); } finally { setStatus(GenerationStatus.IDLE); }
  };

  const handleGenerateScript = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic || !targetAudience) return;

    setStatus(GenerationStatus.GENERATING_SCRIPT);

    const characterTraits: CharacterTraits = {
        gender: charGender, style: charStyle, age: charAge, color_accent: charColor
    };

    try {
      const data = await generateCarouselScript(
          topic, visualStyle, targetAudience, slideCount, 
          language, tone, dialect, useCharacter, aspectRatio, characterTraits, brandColors
      );
      if (useCharacter && data.carousel_metadata.character_description) {
          setCharacterDesc(data.carousel_metadata.character_description);
      }
      setCurrentCarousel(data);
      setStatus(GenerationStatus.COMPLETE);
      setActiveView('editor');
      setSelectedSlideIndex(0); // Select first slide
    } catch (error) {
      console.error(error);
      setStatus(GenerationStatus.ERROR);
    }
  };

  const handleGenerateImage = async (slideNumber: number) => {
    if (!currentCarousel) return;
    const slide = currentCarousel.slides.find(s => s.slide_number === slideNumber);
    if (!slide) return;

    setImageLoadingState(prev => ({ ...prev, [slideNumber]: true }));
    setImageErrorState(prev => ({ ...prev, [slideNumber]: false }));

    try {
      const metadata = { 
          ...currentCarousel.carousel_metadata, 
          character_description: characterDesc || currentCarousel.carousel_metadata.character_description 
      };
      const base64Image = await generateSlideImage(slide, metadata);
      setGeneratedImages(prev => ({
        ...prev,
        [currentCarousel.id]: { ...(prev[currentCarousel.id] || {}), [slideNumber]: base64Image }
      }));
    } catch (error) {
      console.error("Failed to generate image", error);
      setImageErrorState(prev => ({ ...prev, [slideNumber]: true }));
    } finally {
      setImageLoadingState(prev => ({ ...prev, [slideNumber]: false }));
    }
  };

  const handleGenerateAllImages = async () => {
      if (!currentCarousel) return;
      const promises = currentCarousel.slides.map(slide => handleGenerateImage(slide.slide_number));
      await Promise.all(promises);
  };

  const updateSlide = (slideIndex: number, updater: (s: Slide) => Slide) => {
      if (!currentCarousel) return;
      const updatedSlides = currentCarousel.slides.map((s, idx) => 
          idx === slideIndex ? updater(s) : s
      );
      setCurrentCarousel({ ...currentCarousel, slides: updatedSlides });
  };

  const handleUpdateSlideField = (slideNumber: number, field: keyof Slide, value: any) => {
      if (!currentCarousel) return;
      const idx = currentCarousel.slides.findIndex(s => s.slide_number === slideNumber);
      if (idx !== -1) updateSlide(idx, s => ({ ...s, [field]: value }));
  };

  const handleDesignUpdate = (field: keyof SlideDesign, value: any) => {
      updateSlide(selectedSlideIndex, s => ({ ...s, design: { ...s.design, [field]: value } }));
  };

  const handleCharacterUpdate = (field: keyof CharacterSettings, value: any) => {
      updateSlide(selectedSlideIndex, s => ({ ...s, character_settings: { ...s.character_settings, [field]: value } }));
  };

  // Preset Logic
  const applyLayoutPreset = (type: 'default' | 'title-focus' | 'quote' | 'bottom-caption') => {
      const isRTL = language === 'ar';
      if (type === 'default') {
          updateSlide(selectedSlideIndex, s => ({ ...s, design: { ...s.design, textAlign: isRTL ? 'right' : 'left', xPosition: 50, yPosition: 10, fontSize: 'medium', decoration: 'none' } }));
      } else if (type === 'title-focus') {
          updateSlide(selectedSlideIndex, s => ({ ...s, design: { ...s.design, textAlign: 'center', xPosition: 50, yPosition: 40, fontSize: 'xl' } }));
      } else if (type === 'quote') {
          updateSlide(selectedSlideIndex, s => ({ ...s, design: { ...s.design, textAlign: 'center', xPosition: 50, yPosition: 50, fontSize: 'large', decoration: 'accent-line' } }));
      } else if (type === 'bottom-caption') {
          updateSlide(selectedSlideIndex, s => ({ ...s, design: { ...s.design, textAlign: 'center', xPosition: 50, yPosition: 80, fontSize: 'small', decoration: 'none' } }));
      }
  };

  const applyStylePreset = (type: 'cyber' | 'lux' | 'bold' | 'minimal') => {
      if (type === 'cyber') {
          updateSlide(selectedSlideIndex, s => ({ ...s, design: { ...s.design, textColor: '#00ffcc', accentColor: '#00ffcc', textEffect: 'neon', decoration: 'grid', overlayOpacity: 80 } }));
      } else if (type === 'lux') {
          updateSlide(selectedSlideIndex, s => ({ ...s, design: { ...s.design, textColor: '#ffd700', accentColor: '#ffd700', textEffect: 'shadow', decoration: 'frame', overlayOpacity: 60, font: 'serif' } }));
      } else if (type === 'bold') {
          updateSlide(selectedSlideIndex, s => ({ ...s, design: { ...s.design, textColor: '#ffffff', accentColor: '#ef4444', textEffect: 'bg-highlight', decoration: 'circle', overlayOpacity: 20, font: 'display' } }));
      } else if (type === 'minimal') {
          updateSlide(selectedSlideIndex, s => ({ ...s, design: { ...s.design, textColor: '#ffffff', accentColor: '#94a3b8', textEffect: 'none', decoration: 'none', overlayOpacity: 10, font: 'sans' } }));
      }
  }

  const applyColorPalette = (palette: { text: string, accent: string }) => {
      updateSlide(selectedSlideIndex, s => ({
          ...s,
          design: {
              ...s.design,
              textColor: palette.text,
              accentColor: palette.accent
          }
      }));
  };

  const activeSlide = currentCarousel?.slides[selectedSlideIndex];

  const saveToLibrary = () => {
      if (!currentCarousel) return;
      const carouselToSave = { ...currentCarousel, carousel_metadata: { ...currentCarousel.carousel_metadata, character_description: characterDesc } };
      const exists = library.find(c => c.id === carouselToSave.id);
      setLibrary(exists ? library.map(c => c.id === carouselToSave.id ? carouselToSave : c) : [carouselToSave, ...library]);
      alert('Saved!');
  };

  const loadFromLibrary = (carousel: CarouselResponse) => {
      setCurrentCarousel(carousel);
      setLanguage(carousel.carousel_metadata.language as any);
      setAspectRatio(carousel.carousel_metadata.aspect_ratio || '4:5');
      setCharacterDesc(carousel.carousel_metadata.character_description || '');
      setBrandColors(carousel.carousel_metadata.brand_colors || { text: '#ffffff', accent: '#3b82f6' });
      setActiveView('editor');
      setSelectedSlideIndex(0);
  };

  const deleteFromLibrary = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (confirm('Delete?')) {
          setLibrary(prev => prev.filter(c => c.id !== id));
          if (currentCarousel?.id === id) { setCurrentCarousel(null); setActiveView('create'); }
      }
  };

  const exportJSON = () => {
      if (!currentCarousel) return;
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify({ ...currentCarousel, _images: generatedImages[currentCarousel.id] || {} }, null, 2));
      const a = document.createElement('a'); a.href = dataStr; a.download = `carousel.json`; a.click();
  };

  const downloadSlideImage = async () => {
      if(!activeSlide) return;
      const el = document.getElementById(`slide-card-${activeSlide.slide_number}`);
      if(el) {
          try {
            const canvas = await html2canvas(el, { scale: 3, useCORS: true, backgroundColor: null, ignoreElements: (e:any) => e.hasAttribute('data-html2canvas-ignore') });
            const link = document.createElement('a');
            link.download = `slide-${activeSlide.slide_number}.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
          } catch(e) {
              console.error(e);
          }
      }
  }

  const exportPDF = async () => {
    if (!currentCarousel) return;
    setIsExporting(true);

    // Allow React to render the hidden export container
    await new Promise(resolve => setTimeout(resolve, 500));

    let width = 340, height = 425;
    if (currentCarousel.carousel_metadata.aspect_ratio === '1:1') height = 340;
    else if (currentCarousel.carousel_metadata.aspect_ratio === '16:9') { width = 560; height = 315; }

    const doc = new jsPDF({ orientation: width > height ? "landscape" : "portrait", unit: "pt", format: [width, height], hotfixes: ["px_scaling"] });

    // IMPORTANT: Target the hidden export container elements
    const slideElements = document.querySelectorAll('[id^="export-slide-"]');

    for (let i = 0; i < slideElements.length; i++) {
        const el = slideElements[i] as HTMLElement;
        if (i > 0) doc.addPage([width, height]);
        try {
            const canvas = await html2canvas(el, { scale: 3, useCORS: true, backgroundColor: null, ignoreElements: (e:any) => e.hasAttribute('data-html2canvas-ignore') });
            doc.addImage(canvas.toDataURL('image/png', 1.0), 'PNG', 0, 0, width, height, undefined, 'FAST');
        } catch (e) { console.error(e); }
    }
    doc.save(`carousel.pdf`);
    setIsExporting(false);
  };

  return (
    <div className={`min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-blue-500/30 flex flex-col ${language === 'ar' ? 'font-arabic' : ''}`}>

      {/* Off-screen Render Container for PDF Export */}
      {currentCarousel && (
          <div className="absolute top-0 left-[-9999px] flex flex-col gap-10 pointer-events-none" aria-hidden="true">
              {currentCarousel.slides.map((slide) => (
                  <div key={slide.slide_number} id={`export-slide-${slide.slide_number}`}>
                      <SlideCard 
                          slide={slide}
                          imageData={generatedImages[currentCarousel.id]?.[slide.slide_number]}
                          isGeneratingImage={false}
                          onUpdateSlide={() => {}} 
                          onGenerateImage={() => {}}
                          readOnly={true}
                          language={language}
                          aspectRatio={aspectRatio}
                      />
                  </div>
              ))}
          </div>
      )}

      {/* Header */}
