                                 <button onClick={() => setPreviewPlatform('instagram')} className={`p-1.5 rounded text-slate-400 hover:text-white ${previewPlatform === 'instagram' ? 'bg-slate-600 text-white' : ''}`}><Smartphone size={14}/></button>
