                    {/* Bottom Slide Strip */}
                    <div className="h-24 bg-slate-900 border-t border-slate-800 flex items-center gap-4 px-4 overflow-x-auto custom-scrollbar">
                        {currentCarousel.slides.map((s, idx) => (
