                      <SlideCard 
                          slide={slide}
                          imageData={generatedImages[currentCarousel.id]?.[slide.slide_number]}
                          isGeneratingImage={false}
                          onUpdateSlide={() => {}} 
                          onGenerateImage={() => {}}
                          onUpdateDesign={() => {}}
                          readOnly={true}
                          language={language}
                          aspectRatio={aspectRatio}
                          personalBranding={personalBranding}
