                            </div>
                        ))}
                    </div>
                </div>

                {/* RIGHT: Editor Panel (Sidebar) */}
                <div className="w-full md:w-80 bg-slate-900 border-l border-slate-800 flex flex-col shadow-2xl z-20 h-[45vh] md:h-full order-2 md:order-2">
                    {/* Sidebar Tabs */}
                    <div className="flex border-b border-slate-800">
                        {['layout', 'text', 'style', 'char'].map(tab => (
                            <button 
                                key={tab} 
                                onClick={() => setActiveTab(tab as any)}
                                className={`flex-1 py-3 text-[10px] font-bold uppercase flex flex-col items-center gap-1 border-b-2 transition-colors ${activeTab === tab ? 'border-blue-500 text-blue-400 bg-slate-800/50' : 'border-transparent text-slate-500 hover:text-slate-300'}`}
                            >
                                {tab === 'layout' && <Layout size={14}/>}
                                {tab === 'text' && <Type size={14}/>}
                                {tab === 'style' && <Palette size={14}/>}
                                {tab === 'char' && <User size={14}/>}
                                {tab}
                            </button>
                        ))}
                    </div>

                    {/* Sidebar Content */}
                    <div className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar">

                        {activeTab === 'layout' && (
                            <div className="space-y-6 animate-in fade-in duration-300">
                                <div className="space-y-3">
                                     <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Presets</h4>
                                     <div className="grid grid-cols-2 gap-2">
                                         <button onClick={() => applyLayoutPreset('default')} className="text-[10px] p-2 bg-slate-800 border border-slate-700 rounded hover:bg-slate-700 text-slate-300">Standard</button>
                                         <button onClick={() => applyLayoutPreset('title-focus')} className="text-[10px] p-2 bg-slate-800 border border-slate-700 rounded hover:bg-slate-700 text-slate-300">Focus</button>
                                         <button onClick={() => applyLayoutPreset('quote')} className="text-[10px] p-2 bg-slate-800 border border-slate-700 rounded hover:bg-slate-700 text-slate-300">Quote</button>
                                         <button onClick={() => applyLayoutPreset('bottom-caption')} className="text-[10px] p-2 bg-slate-800 border border-slate-700 rounded hover:bg-slate-700 text-slate-300">Caption</button>
                                     </div>
                                </div>
                                <div className="space-y-3">
                                    <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Layout Style</h4>
                                    <div className="grid grid-cols-2 gap-2">
                                        {['none', 'glass', 'card', 'paper', 'gradient-bottom'].map(s => (
                                            <button 
                                                key={s} 
                                                onClick={() => handleDesignUpdate('containerStyle', s)}
                                                className={`text-[10px] py-2 px-1 capitalize border rounded transition-all ${activeSlide.design.containerStyle === s ? 'bg-blue-600/20 border-blue-500 text-blue-400' : 'bg-slate-950 border-slate-800 text-slate-500 hover:border-slate-600'}`}
                                            >
                                                {s.replace('-', ' ')}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                                <div className="space-y-3">
                                    <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Position & Size</h4>
                                    <div className="bg-slate-950 p-4 rounded-xl border border-slate-800 space-y-4">
                                        <div className="space-y-1">
                                            <div className="flex justify-between text-[10px] text-slate-500"><span>Box Width</span><span>{activeSlide.design.textWidth || 85}%</span></div>
                                            <input type="range" min="20" max="100" value={activeSlide.design.textWidth || 85} onChange={(e) => handleDesignUpdate('textWidth', parseInt(e.target.value))} className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-500"/>
                                        </div>
                                        <div className="space-y-1">
                                            <div className="flex justify-between text-[10px] text-slate-500"><span>Horizontal (X)</span><span>{activeSlide.design.xPosition}%</span></div>
                                            <input type="range" min="0" max="100" value={activeSlide.design.xPosition} onChange={(e) => handleDesignUpdate('xPosition', parseInt(e.target.value))} className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-500"/>
                                        </div>
                                        <div className="space-y-1">
                                            <div className="flex justify-between text-[10px] text-slate-500"><span>Vertical (Y)</span><span>{activeSlide.design.yPosition}%</span></div>
                                            <input type="range" min="0" max="100" value={activeSlide.design.yPosition} onChange={(e) => handleDesignUpdate('yPosition', parseInt(e.target.value))} className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-500"/>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}

                        {activeTab === 'text' && (
                            <div className="space-y-6 animate-in fade-in duration-300">
                                <div className="space-y-3">
                                    <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Alignment</h4>
                                    <div className="flex bg-slate-950 p-1 rounded-lg border border-slate-800">
                                        {['left', 'center', 'right', 'justify'].map((align: any) => (
                                            <button key={align} onClick={() => handleDesignUpdate('textAlign', align)} 
                                                className={`flex-1 py-2 rounded flex justify-center transition-all ${activeSlide.design.textAlign === align ? 'bg-slate-800 text-white' : 'text-slate-500 hover:text-slate-300'}`}>
                                                {align === 'left' && <AlignLeft size={14}/>}
                                                {align === 'center' && <AlignCenter size={14}/>}
                                                {align === 'right' && <AlignRight size={14}/>}
                                                {align === 'justify' && <AlignJustify size={14}/>}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                                <div className="space-y-3">
                                    <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Font Family</h4>
                                    <select value={activeSlide.design.font || 'sans'} onChange={e => handleDesignUpdate('font', e.target.value)} className="w-full bg-slate-950 border border-slate-800 rounded-lg text-sm px-3 py-2 focus:border-blue-500 outline-none mb-2">
                                        <option value="sans">Sans Serif (Inter/Cairo)</option>
                                        <option value="serif">Serif (Elegant)</option>
                                        <option value="mono">Monospace (Code)</option>
                                        <option value="display">Display (Bold)</option>
                                        <option value="custom">Custom Google Font</option>
                                    </select>
                                    {activeSlide.design.font === 'custom' && (
                                        <div className="animate-in fade-in">
                                            <input 
                                                type="text" 
                                                value={activeSlide.design.customFont || ''} 
                                                onChange={e => handleDesignUpdate('customFont', e.target.value)}
                                                placeholder="e.g. Roboto, Open Sans, Lato" 
                                                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-xs focus:border-blue-500 outline-none"
                                            />
                                            <p className="text-[10px] text-slate-500 mt-1">Type exact name from Google Fonts.</p>
                                        </div>
                                    )}
                                </div>
                                <div className="space-y-3">
                                    <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Size & Color</h4>
                                    <div className="flex gap-3">
                                        <div className="w-12 h-10 rounded-lg border border-slate-700 overflow-hidden relative cursor-pointer">
                                            <input type="color" value={activeSlide.design.textColor} onChange={e => handleDesignUpdate('textColor', e.target.value)} className="absolute -top-2 -left-2 w-20 h-20 cursor-pointer"/>
                                        </div>
                                        <select value={activeSlide.design.fontSize} onChange={e => handleDesignUpdate('fontSize', e.target.value)} className="flex-1 bg-slate-950 border border-slate-800 rounded-lg text-sm px-3 focus:border-blue-500 outline-none">
                                            <option value="small">Small</option><option value="medium">Medium</option><option value="large">Large</option><option value="xl">Extra Large</option>
                                        </select>
                                    </div>
                                </div>
                                {/* Text Background Section */}
                                <div className="space-y-3">
                                    <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Text Background</h4>
                                    <div className="flex gap-3 bg-slate-950 p-3 rounded-xl border border-slate-800">
                                        <div className="space-y-1 flex-1">
                                             <label className="text-[10px] text-slate-500 font-bold">Color</label>
                                             <div className="h-8 rounded-lg border border-slate-700 relative overflow-hidden bg-slate-900">
                                                <input type="color" value={activeSlide.design.textBackgroundColor || '#000000'} onChange={e => handleDesignUpdate('textBackgroundColor', e.target.value)} className="absolute -top-4 -left-4 w-20 h-20 cursor-pointer"/>
                                             </div>
                                        </div>
                                        <div className="space-y-1 flex-[2]">
                                             <label className="text-[10px] text-slate-500 font-bold">Opacity: {activeSlide.design.textBackgroundOpacity}%</label>
                                             <input type="range" min="0" max="100" value={activeSlide.design.textBackgroundOpacity || 0} onChange={e => handleDesignUpdate('textBackgroundOpacity', parseInt(e.target.value))} className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-500 mt-2"/>
                                        </div>
                                    </div>
                                </div>

                                <div className="space-y-3">
                                    <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Effects</h4>
                                    <div className="grid grid-cols-2 gap-2">
                                        {['none', 'shadow', 'neon', 'outline', 'bg-highlight', 'retro'].map(eff => (
                                            <button key={eff} onClick={() => handleDesignUpdate('textEffect', eff)} 
                                                className={`py-2 px-3 rounded-lg text-xs font-medium border transition-all ${activeSlide.design.textEffect === eff ? 'bg-blue-600/20 border-blue-500 text-blue-400' : 'bg-slate-950 border-slate-800 text-slate-500 hover:border-slate-600'}`}>
                                                {eff}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        )}

                        {activeTab === 'style' && (
                            <div className="space-y-6 animate-in fade-in duration-300">
                                <div className="space-y-3">
                                    <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Theme Presets</h4>
                                    <div className="grid grid-cols-2 gap-2">
                                        <button onClick={() => applyStylePreset('cyber')} className="text-[10px] py-2 bg-slate-950 border border-slate-800 rounded hover:bg-slate-800 text-teal-400 font-bold border-l-2 border-l-teal-500">Cyber</button>
                                        <button onClick={() => applyStylePreset('lux')} className="text-[10px] py-2 bg-slate-950 border border-slate-800 rounded hover:bg-slate-800 text-yellow-500 font-serif font-bold border-l-2 border-l-yellow-500">Luxury</button>
                                        <button onClick={() => applyStylePreset('bold')} className="text-[10px] py-2 bg-slate-950 border border-slate-800 rounded hover:bg-slate-800 text-white font-bold border-l-2 border-l-white">Bold</button>
                                        <button onClick={() => applyStylePreset('minimal')} className="text-[10px] py-2 bg-slate-950 border border-slate-800 rounded hover:bg-slate-800 text-slate-400 border-l-2 border-l-slate-400">Minimal</button>
                                    </div>
                                </div>

                                {/* Personal Branding Section */}
                                <div className="space-y-3">
                                    <div className="flex items-center justify-between">
                                        <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Personal Branding</h4>
                                        <button onClick={() => setPersonalBranding(prev => ({...prev, enabled: !prev.enabled}))} className={`w-8 h-4 rounded-full p-0.5 transition-colors ${personalBranding.enabled ? 'bg-blue-600' : 'bg-slate-700'}`}><div className={`w-3 h-3 bg-white rounded-full shadow transition-transform ${personalBranding.enabled ? 'translate-x-4' : 'translate-x-0'}`}/></button>
                                    </div>
                                    {personalBranding.enabled && (
                                        <div className="bg-slate-950 p-4 rounded-xl border border-slate-800 space-y-3">
                                            <div>
                                                <label className="text-[10px] text-slate-500 font-bold">Name</label>
                                                <input value={personalBranding.name} onChange={e => setPersonalBranding({...personalBranding, name: e.target.value})} className="w-full bg-slate-900 border border-slate-800 rounded px-2 py-1 text-xs" placeholder="John Doe"/>
                                            </div>
                                            <div>
                                                <label className="text-[10px] text-slate-500 font-bold">Handle (@)</label>
                                                <div className="relative">
                                                    <AtSign size={12} className="absolute left-2 top-1.5 text-slate-500"/>
                                                    <input value={personalBranding.handle} onChange={e => setPersonalBranding({...personalBranding, handle: e.target.value})} className="w-full bg-slate-900 border border-slate-800 rounded pl-7 pr-2 py-1 text-xs" placeholder="@johndoe"/>
                                                </div>
                                            </div>
                                        </div>
                                    )}
                                </div>

                                <div className="space-y-3">
                                    <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Color Palette</h4>
                                    <div className="grid grid-cols-4 gap-2 mb-3">
                                        {COLOR_PALETTES.map((p, i) => (
                                            <button 
                                                key={i} 
                                                onClick={() => applyColorPalette(p)}
                                                className="h-8 rounded-lg border border-slate-700 overflow-hidden relative group"
                                                title={p.name}
                                            >
                                                <div className="absolute inset-0 flex">
                                                    <div className="w-1/2 h-full" style={{ backgroundColor: p.text }}></div>
                                                    <div className="w-1/2 h-full" style={{ backgroundColor: p.accent }}></div>
                                                </div>
                                            </button>
                                        ))}
                                    </div>
                                    <div className="flex gap-2">
                                        <div className="flex-1 space-y-1">
                                            <label className="text-[10px] text-slate-500 font-bold">Text</label>
                                            <div className="h-8 rounded-lg border border-slate-700 relative overflow-hidden bg-slate-900">
                                                <input type="color" value={activeSlide.design.textColor} onChange={e => handleDesignUpdate('textColor', e.target.value)} className="absolute -top-4 -left-4 w-20 h-20 cursor-pointer"/>
                                            </div>
                                        </div>
                                        <div className="flex-1 space-y-1">
                                            <label className="text-[10px] text-slate-500 font-bold">Accent</label>
                                             <div className="h-8 rounded-lg border border-slate-700 relative overflow-hidden bg-slate-900">
                                                <input type="color" value={activeSlide.design.accentColor || '#3b82f6'} onChange={e => handleDesignUpdate('accentColor', e.target.value)} className="absolute -top-4 -left-4 w-20 h-20 cursor-pointer"/>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                                <div className="space-y-3">
                                    <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Decorations</h4>
                                    <div className="grid grid-cols-3 gap-2">
                                        {[{id:'none',i:X},{id:'grid',i:Grid},{id:'frame',i:Frame},{id:'circle',i:BoxSelect},{id:'blob',i:Sparkles}].map(d => (
                                            <button key={d.id} onClick={() => handleDesignUpdate('decoration', d.id)}
                                                className={`h-12 rounded-lg border flex items-center justify-center text-slate-500 transition-all ${activeSlide.design.decoration === d.id ? 'bg-blue-600/20 border-blue-500 text-blue-400' : 'bg-slate-950 border-slate-800 hover:border-slate-600'}`}>
                                                <d.i size={16}/>
                                            </button>
                                        ))}
                                    </div>
                                </div>
                                <div className="space-y-3">
                                    <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Image Overlay</h4>
                                    <input type="range" min="0" max="90" value={activeSlide.design.overlayOpacity} onChange={e => handleDesignUpdate('overlayOpacity', parseInt(e.target.value))} className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-500"/>
                                </div>
                                <div className="space-y-2 pt-4 border-t border-slate-800">
                                    <label className="text-xs font-bold text-slate-400">Visual Prompt</label>
                                    <textarea value={activeSlide.visual_description} onChange={e => handleUpdateSlideField(activeSlide.slide_number, 'visual_description', e.target.value)} className="w-full h-24 bg-slate-950 border border-slate-800 rounded-lg p-3 text-xs resize-none focus:border-blue-500 outline-none"/>
                                </div>
                            </div>
                        )}

                        {activeTab === 'char' && (
                            <div className="space-y-6 animate-in fade-in duration-300">
                                <div className="flex items-center justify-between p-3 bg-slate-950 rounded-xl border border-slate-800">
                                    <span className="text-sm font-bold flex items-center gap-2"><User size={16}/> Include Character</span>
                                    <button onClick={() => handleUpdateSlideField(activeSlide.slide_number, 'include_character', !activeSlide.include_character)} className={`w-10 h-5 rounded-full p-0.5 transition-colors ${activeSlide.include_character ? 'bg-blue-600' : 'bg-slate-700'}`}><div className={`w-4 h-4 bg-white rounded-full shadow transition-transform ${activeSlide.include_character ? 'translate-x-5' : 'translate-x-0'}`}/></button>
                                </div>

                                {activeSlide.include_character && (
                                    <>
                                        <div className="space-y-3">
                                            <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Anchor Position</h4>
                                            <div className="grid grid-cols-3 gap-2 p-3 bg-slate-950 rounded-xl border border-slate-800 w-full aspect-square">
                                                {['top-left', 'top-center', 'top-right', 'center-left', 'center', 'center-right', 'bottom-left', 'bottom-center', 'bottom-right'].map(pos => (
                                                    <button key={pos} onClick={() => handleCharacterUpdate('position', pos)} className={`w-full h-full rounded flex items-center justify-center transition-all ${activeSlide.character_settings.position === pos ? 'bg-blue-600 text-white' : 'bg-slate-800 hover:bg-slate-700 text-slate-500'}`}>
                                                        <div className={`w-2 h-2 rounded-full ${activeSlide.character_settings.position === pos ? 'bg-white' : 'bg-slate-500'}`}/>
                                                    </button>
                                                ))}
                                            </div>
                                        </div>

                                        <div className="space-y-3">
                                            <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Appearance</h4>
                                            <div className="grid grid-cols-2 gap-3">
                                                <div className="space-y-1">
                                                    <label className="text-[10px] text-slate-500 font-bold">Expression</label>
                                                    <select value={activeSlide.character_settings?.expression} onChange={e => handleCharacterUpdate('expression', e.target.value)} className="w-full bg-slate-950 text-xs py-2 px-2 rounded-lg border border-slate-800"><option value="neutral">Neutral</option><option value="happy">Happy</option><option value="serious">Serious</option></select>
                                                </div>
                                                <div className="space-y-1">
                                                    <label className="text-[10px] text-slate-500 font-bold">Scale</label>
                                                    <select value={activeSlide.character_settings?.scale} onChange={e => handleCharacterUpdate('scale', e.target.value)} className="w-full bg-slate-950 text-xs py-2 px-2 rounded-lg border border-slate-800"><option value="small">Small</option><option value="medium">Medium</option><option value="large">Large</option></select>
                                                </div>
                                            </div>
                                            <div className="space-y-1">
                                                <div className="flex justify-between text-[10px] text-slate-500"><span>Opacity</span><span>{activeSlide.character_settings?.opacity ?? 100}%</span></div>
                                                <input type="range" min="10" max="100" value={activeSlide.character_settings?.opacity ?? 100} onChange={e => handleCharacterUpdate('opacity', parseInt(e.target.value))} className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-500"/>
                                            </div>
                                             <div className="space-y-1">
                                                <div className="flex justify-between text-[10px] text-slate-500"><span>Rotation</span><span>{activeSlide.character_settings?.rotation ?? 0}°</span></div>
                                                <input type="range" min="-180" max="180" value={activeSlide.character_settings?.rotation ?? 0} onChange={e => handleCharacterUpdate('rotation', parseInt(e.target.value))} className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-500"/>
                                            </div>
                                        </div>

                                        <div className="space-y-2 pt-4 border-t border-slate-800">
                                            <label className="text-xs font-bold text-blue-400">Custom Action (Override)</label>
                                            <textarea value={activeSlide.character_custom_prompt || ''} onChange={e => handleUpdateSlideField(activeSlide.slide_number, 'character_custom_prompt', e.target.value)} placeholder="e.g. Jumping in the air..." className="w-full h-20 bg-slate-950 border border-slate-800 rounded-lg p-3 text-xs resize-none focus:border-blue-500 outline-none"/>
                                        </div>
                                    </>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </div>
        )}

        {activeView === 'library' && (
            <div className="flex-1 overflow-y-auto p-6 md:p-12">
                 <div className="max-w-6xl mx-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {library.map((item) => (
                        <div key={item.id} onClick={() => loadFromLibrary(item)} className="bg-slate-900 border border-slate-800 rounded-2xl p-6 cursor-pointer hover:border-blue-500 transition-all hover:-translate-y-1 group relative">
                            <button onClick={(e) => deleteFromLibrary(item.id, e)} className="absolute top-4 right-4 p-2 text-slate-600 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={16}/></button>
                            <h3 className="font-bold text-white text-lg mb-2 line-clamp-2">{item.carousel_metadata.topic}</h3>
                            <div className="flex gap-2 text-xs text-slate-500"><span className="bg-slate-800 px-2 py-1 rounded">{item.slides.length} Slides</span></div>
                        </div>
                    ))}
                 </div>
            </div>
        )}

      </main>
    </div>
  );
}

export default App;

export interface CharacterTraits {
  style: '3d-render' | 'flat-vector' | 'hand-drawn' | 'anime' | 'realistic' | 'pixel-art' | 'clay' | 'cyberpunk' | 'vaporwave' | 'noir' | 'ghibli' | 'paper-cutout' | 'steampunk' | 'watercolor' | 'sketch' | 'disney';
  gender: 'neutral' | 'male' | 'female';
  age: 'child' | 'young-adult' | 'adult' | 'elderly';
  color_accent: string;
}

export interface BrandColors {
  text: string;
  accent: string;
}

export interface PersonalBranding {
  name: string;
  handle: string;
  avatarUrl?: string; // We will use a placeholder or generic avatar for now
  enabled: boolean;
}

export interface CarouselMetadata {
  topic: string;
  visual_style: string;
  target_audience: string;
  language: 'en' | 'ar';
  tone: string;
  aspect_ratio: '4:5' | '1:1' | '16:9';
  dialect?: string;
  main_theme?: string;
  character_description?: string; // Global character prompt
  character_traits?: CharacterTraits;
  brand_colors?: BrandColors;
  personal_branding?: PersonalBranding;
}

export interface SlideNumberDesign {
    show: boolean;
    style: 'minimal' | 'circle' | 'square' | 'outline' | 'tag';
    position: 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right';
}

export interface SlideDesign {
  textColor: string;
  accentColor: string; 
  textBackgroundColor: string; 
  textBackgroundOpacity: number; 
  containerStyle: 'none' | 'glass' | 'card' | 'paper' | 'gradient-bottom'; 
  overlayOpacity: number;
  fontSize: 'small' | 'medium' | 'large' | 'xl';
  font: 'sans' | 'serif' | 'mono' | 'display' | 'custom';
  customFont?: string; // New: For Google Fonts
  textWidth: number; // New: Percentage 20-100
  textAlign: 'left' | 'center' | 'right' | 'justify';
  xPosition: number; // 0 to 100 percentage
  yPosition: number; // 0 to 100 percentage
  textEffect: 'none' | 'shadow' | 'neon' | 'outline' | 'bg-highlight' | 'glitch' | 'retro';
  decoration: 'none' | 'circle' | 'square' | 'accent-line' | 'corner-shape' | 'grid' | 'blob' | 'frame';
  slideNumberDesign?: SlideNumberDesign;
}

export type CharacterPosition = 
  'top-left' | 'top-center' | 'top-right' | 
  'center-left' | 'center' | 'center-right' | 
  'bottom-left' | 'bottom-center' | 'bottom-right';

export interface CharacterSettings {
    scale: 'small' | 'medium' | 'large';
    position: CharacterPosition;
    opacity: number; // 0-100
    rotation: number; // -180 to 180
    expression: 'neutral' | 'happy' | 'serious' | 'surprised' | 'focused' | 'excited' | 'confused';
}

export interface Slide {
  slide_number: number;
  headline: string;
  sub_headline: string;
  visual_description: string;
  layout_hint: string;
  include_character: boolean; 
  character_custom_prompt?: string;
  character_settings: CharacterSettings;
  design: SlideDesign;
}

export interface CarouselResponse {
  id: string;
  createdAt: number;
  carousel_metadata: CarouselMetadata;
  slides: Slide[];
}

export enum GenerationStatus {
  IDLE = 'IDLE',
  GENERATING_IDEAS = 'GENERATING_IDEAS',
  GENERATING_SCRIPT = 'GENERATING_SCRIPT',
  GENERATING_IMAGES = 'GENERATING_IMAGES',
  COMPLETE = 'COMPLETE',
  ERROR = 'ERROR'
}

export type ViewMode = 'create' | 'editor' | 'library';

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { CarouselResponse, Slide, CharacterTraits, BrandColors } from "../types";

// Initialize Gemini Client
// @ts-ignore - Env variable is injected by the sandbox environment
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

const CAROUSEL_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    carousel_metadata: {
      type: Type.OBJECT,
      properties: {
        topic: { type: Type.STRING },
        visual_style: { type: Type.STRING },
        target_audience: { type: Type.STRING },
        language: { type: Type.STRING, enum: ['en', 'ar'] },
        tone: { type: Type.STRING },
        dialect: { type: Type.STRING },
        character_description: { type: Type.STRING },
      },
      required: ["topic", "visual_style", "target_audience", "character_description"],
    },
    slides: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          slide_number: { type: Type.INTEGER },
          headline: { type: Type.STRING },
          sub_headline: { type: Type.STRING },
          visual_description: { type: Type.STRING },
          layout_hint: { type: Type.STRING },
          include_character: { type: Type.BOOLEAN },
        },
        required: ["slide_number", "headline", "sub_headline", "visual_description", "layout_hint", "include_character"],
      },
    },
  },
  required: ["carousel_metadata", "slides"],
};

export const generateIdeas = async (
    theme: string, 
    language: 'en' | 'ar'
): Promise<{ topic: string, audience: string }> => {
    const model = "gemini-3-flash-preview";
    const langPrompt = language === 'ar' ? 'in Arabic' : 'in English';
    const prompt = `Generate a viral, trending social media topic and a specific target audience based on the theme: "${theme}". Return strictly JSON: { "topic": "...", "audience": "..." } ${langPrompt}.`;

    try {
        const response = await ai.models.generateContent({
            model,
            contents: prompt,
            config: { responseMimeType: "application/json" }
        });
        const text = response.text || "{}";
        return JSON.parse(text);
    } catch (e) {
        console.error("Error generating ideas", e);
        return { topic: "Growth Hacking Strategies", audience: "Startup Founders" };
    }
};

export const generateCarouselScript = async (
  topic: string,
  visualStyle: string,
  target_audience: string,
  slideCount: number,
  language: 'en' | 'ar',
  tone: string,
  dialect: string,
  useCharacter: boolean,
  aspectRatio: '4:5' | '1:1' | '16:9',
  characterTraits?: CharacterTraits,
  brandColors?: BrandColors
): Promise<CarouselResponse> => {
  const model = "gemini-3-flash-preview";

  const langInstruction = language === 'ar' 
    ? `Language: Arabic (Dialect/Style: ${dialect || 'Modern Standard Arabic'}). IMPORTANT: Ensure headlines are catchy, short, and strictly in Arabic script. Use culturally relevant metaphors.`
    : `Language: English. Tone: ${tone}.`;

  // Build a specific character description based on traits
  let charDescInstructions = "";
  if (useCharacter && characterTraits) {
      const baseDesc = `A ${characterTraits.age} ${characterTraits.gender} character, style ${characterTraits.style}, main color ${characterTraits.color_accent}`;
      charDescInstructions = `
      CRITICAL: Create a fixed "Visual DNA" for the character based on: "${baseDesc}".
      In 'character_description', write a prompt that defines IMMUTABLE traits to ensure consistency across multiple images.
      Include:
      1. Precise Hairstyle & Color (e.g., "short messy neon-blue undercut")
      2. Exact Outfit (e.g., "orange oversized hoodie with white drawstrings")
      3. Face/Body Features (e.g., "round face, freckles, wearing aviator sunglasses")
      4. Art Style keywords matching '${characterTraits.style}'.
      Example: "3D render, cute robot with a square head, rusty yellow metal texture, one glowing blue eye, wearing a red scarf, pixar lighting."
      `;
  } else {
      charDescInstructions = `Leave 'character_description' empty. Set 'include_character' to false.`;
  }

  const systemInstruction = `
    Role: You are a Senior Social Media Strategist and Visual Director.
    Objective: Generate a viral ${slideCount}-slide carousel.

    ${langInstruction}
    Target Audience: ${target_audience}
    Tone: ${tone}
    Visual Style: ${visualStyle}
    Aspect Ratio: ${aspectRatio}

    ${charDescInstructions}

    Structure:
    - Slide 1: Hook (High contrast, big text).
    - Middle: Value/Educational.
    - End: CTA.

    Visual Prompting:
    - In 'visual_description', describe the scene layout. Keep it compatible with the character interacting with it.
  `;

  const prompt = `Topic: ${topic}. Slides: ${slideCount}.`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: CAROUSEL_SCHEMA,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response text from Gemini");

    const data = JSON.parse(text);

    // Enrich with Default Design Properties using Brand Colors if provided
    const enrichedSlides = data.slides.map((slide: any) => ({
      ...slide,
      character_custom_prompt: "",
      character_settings: { 
          scale: 'medium', 
          position: 'center',
          opacity: 100,
          rotation: 0,
          expression: 'neutral'
      },
      design: {
        textColor: brandColors?.text || '#ffffff',
        accentColor: brandColors?.accent || '#3b82f6', 
        textBackgroundColor: '#000000', 
        textBackgroundOpacity: 0, 
        containerStyle: 'none', // Default
        overlayOpacity: 10, 
        fontSize: 'medium',
        font: 'sans',
        textAlign: language === 'ar' ? 'right' : 'left', // Initialize based on language
        xPosition: 50, // Center
        yPosition: 10, // Top area
        textWidth: 85, // Default width percentage
        textEffect: 'shadow',
        decoration: 'none',
        slideNumberDesign: {
            show: true,
            style: 'minimal',
            position: language === 'ar' ? 'top-right' : 'top-left'
        }
      }
    }));

    // Ensure metadata has all fields
    data.carousel_metadata.language = language;
    data.carousel_metadata.tone = tone;
    data.carousel_metadata.dialect = dialect;
    data.carousel_metadata.aspect_ratio = aspectRatio;
    data.carousel_metadata.character_traits = characterTraits;
    data.carousel_metadata.brand_colors = brandColors;
    data.carousel_metadata.personal_branding = { name: '', handle: '', enabled: false };

    return {
        ...data,
        slides: enrichedSlides,
        id: crypto.randomUUID(),
        createdAt: Date.now()
    } as CarouselResponse;

  } catch (error) {
    console.error("Error generating script:", error);
    throw error;
  }
};

export const generateSlideImage = async (
  slide: Slide,
  metadata: any
): Promise<string> => {
  const model = "gemini-2.5-flash-image";

  let characterPromptPart = "";

  if (slide.include_character) {
      // Prioritize consistency by always including the global character DNA
      const globalCharDNA = metadata.character_description || "";
      const customAction = slide.character_custom_prompt || "Standing confidently";

      if (globalCharDNA) {
         const s = slide.character_settings || { scale: 'medium', position: 'center', opacity: 100, rotation: 0, expression: 'neutral' };

         const posMap: Record<string, string> = {
             'top-left': 'top left corner', 'top-center': 'top center', 'top-right': 'top right corner',
             'center-left': 'middle left', 'center': 'center', 'center-right': 'middle right',
             'bottom-left': 'bottom left corner', 'bottom-center': 'bottom center', 'bottom-right': 'bottom right corner'
         };
         const posStr = posMap[s.position] || 'center';

         let styleMods = "";
         if (s.opacity < 100) styleMods += `(Appearance: semi-transparent/holographic at ${s.opacity}% opacity). `;
         if (s.rotation !== 0) styleMods += `(Orientation: tilted ${s.rotation} degrees). `;
         const expressionMod = s.expression ? `Expression: ${s.expression}.` : '';

         // Construct a Prompt that emphasizes the DNA
         // STRICT CONSISTENCY PATTERN
         characterPromptPart = `
         *** CHARACTER REFERENCE SHEET (MUST MATCH EXACTLY) ***
         Visual DNA: ${globalCharDNA}.

         *** CURRENT SCENE ACTION ***
         Action: ${customAction}. ${expressionMod}
         Camera/Framing: Subject is at ${s.scale} scale, positioned in the ${posStr}. ${styleMods}
         `;
      }
  }

  const ar = metadata.aspect_ratio || '4:5';
  const aspectRatioPrompt = ar === '1:1' ? 'Square Aspect Ratio 1:1' : ar === '16:9' ? 'Wide Aspect Ratio 16:9' : 'Vertical Aspect Ratio 4:5';

  const imagePrompt = `
    Task: Generate a high-quality social media background image (${aspectRatioPrompt}).

    Visual Style: ${metadata.visual_style}.
    Environment/Background: ${slide.visual_description}.

    ${characterPromptPart}

    Constraint: NO TEXT in the image. Pure visual art.
  `;

  // Determine Aspect Ratio for API
  let apiAspectRatio = "4:5"; 
  if (ar === '1:1') apiAspectRatio = "1:1";
  if (ar === '16:9') apiAspectRatio = "16:9";

  try {
    const response = await ai.models.generateContent({
      model,
      contents: { parts: [{ text: imagePrompt }] },
      config: {
          imageConfig: {
              aspectRatio: apiAspectRatio as any
          }
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
           return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
    }
    throw new Error("No image data found");
  } catch (error) {
    console.error("Error generating image:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Slide, SlideDesign, PersonalBranding } from '../types';
import { Image, ImagePlus, AlertCircle, RefreshCw, Smartphone, Linkedin, Instagram, Move } from 'lucide-react';

interface SlideCardProps {
  slide: Slide;
  imageData?: string;
  isGeneratingImage: boolean;
  isError?: boolean;
  onGenerateImage: () => void;
  onUpdateSlide: (slideNumber: number, field: keyof Slide, value: any) => void;
  // New callback for design updates specifically for drag operations
  onUpdateDesign: (slideNumber: number, field: keyof SlideDesign, value: any) => void;
  readOnly?: boolean;
  language?: 'en' | 'ar';
  aspectRatio?: '4:5' | '1:1' | '16:9';
  isSelected?: boolean;
  onSelect?: () => void;
  personalBranding?: PersonalBranding;
  previewPlatform?: 'none' | 'instagram' | 'linkedin';
}

const SlideCard: React.FC<SlideCardProps> = ({ 
  slide, 
  imageData, 
  isGeneratingImage, 
  isError = false,
  onGenerateImage,
  onUpdateSlide,
  onUpdateDesign,
  readOnly = false,
  language = 'en',
  aspectRatio = '4:5',
  isSelected = false,
  onSelect,
  personalBranding,
  previewPlatform = 'none'
}) => {
  const design = slide.design;
  const isRTL = language === 'ar';
  const headlineRef = useRef<HTMLTextAreaElement>(null);
  const subheadRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Drag State
  const [isDragging, setIsDragging] = useState(false);
  const dragStart = useRef({ x: 0, y: 0 });
  const startPos = useRef({ x: 0, y: 0 });

  // Auto-resize
  const autoResize = (elem: HTMLTextAreaElement | null) => {
    if (elem) {
        elem.style.height = 'auto'; 
        elem.style.height = `${elem.scrollHeight + 4}px`;
    }
  };

  useEffect(() => {
    const timer = setTimeout(() => {
        autoResize(headlineRef.current);
        autoResize(subheadRef.current);
    }, 10);
    return () => clearTimeout(timer);
  }, [slide.headline, slide.sub_headline, aspectRatio, design.font, design.containerStyle, design.textWidth]);

  // Google Fonts Injection
  useEffect(() => {
    if (design.font === 'custom' && design.customFont) {
        const fontName = design.customFont;
        const linkId = `font-${fontName.replace(/\s+/g, '-')}`;
        if (!document.getElementById(linkId)) {
            const link = document.createElement('link');
            link.id = linkId;
            link.rel = 'stylesheet';
            link.href = `https://fonts.googleapis.com/css2?family=${fontName.replace(/\s+/g, '+')}:wght@400;700&display=swap`;
            document.head.appendChild(link);
        }
    }
  }, [design.font, design.customFont]);

  // Drag Handlers
  const handleDragStart = (e: React.MouseEvent | React.TouchEvent) => {
      if (readOnly) return;
      // Only start dragging if clicking the move handle or container background (not the textarea)
      const target = e.target as HTMLElement;
      if (target.tagName === 'TEXTAREA') return;

      setIsDragging(true);
      const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
      const clientY = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;

      dragStart.current = { x: clientX, y: clientY };
      startPos.current = { x: design.xPosition, y: design.yPosition };

      // Add global listeners
      document.addEventListener('mousemove', handleDragMove as any);
      document.addEventListener('mouseup', handleDragEnd);
      document.addEventListener('touchmove', handleDragMove as any);
      document.addEventListener('touchend', handleDragEnd);
  };

  const handleDragMove = (e: MouseEvent | TouchEvent) => {
      if (!isDragging) return;
      const clientX = 'touches' in e ? e.touches[0].clientX : (e as MouseEvent).clientX;
      const clientY = 'touches' in e ? e.touches[0].clientY : (e as MouseEvent).clientY;

      const cardRect = containerRef.current?.getBoundingClientRect();
      if (!cardRect) return;

      const deltaX = clientX - dragStart.current.x;
      const deltaY = clientY - dragStart.current.y;

      // Convert pixels to percentage based on card dimensions
      const percentX = (deltaX / cardRect.width) * 100;
      const percentY = (deltaY / cardRect.height) * 100;

      let newX = startPos.current.x + percentX;
      let newY = startPos.current.y + percentY;

      // Clamp
      newX = Math.max(0, Math.min(100, newX));
      newY = Math.max(0, Math.min(100, newY));

      onUpdateDesign(slide.slide_number, 'xPosition', Math.round(newX));
      onUpdateDesign(slide.slide_number, 'yPosition', Math.round(newY));
  };

  const handleDragEnd = () => {
      setIsDragging(false);
      document.removeEventListener('mousemove', handleDragMove as any);
      document.removeEventListener('mouseup', handleDragEnd);
      document.removeEventListener('touchmove', handleDragMove as any);
      document.removeEventListener('touchend', handleDragEnd);
  };


  const getTextStyle = (isHeadline: boolean) => {
    const baseSize = isHeadline ? 'font-bold' : 'font-medium';
    let sizeClass = isHeadline ? 'text-2xl' : 'text-sm';
    if (design.fontSize === 'small') sizeClass = isHeadline ? 'text-xl' : 'text-xs';
    if (design.fontSize === 'large') sizeClass = isHeadline ? 'text-3xl' : 'text-base';
    if (design.fontSize === 'xl') sizeClass = isHeadline ? 'text-4xl' : 'text-lg';

    let effectClass = '';
    if (design.containerStyle === 'none') {
        if (design.textEffect === 'shadow') effectClass = 'drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)]'; 
        if (design.textEffect === 'neon') effectClass = 'drop-shadow-[0_0_5px_rgba(255,255,255,0.8)]';
        if (design.textEffect === 'outline') effectClass = '[text-shadow:_-1px_-1px_0_#000,_1px_-1px_0_#000,_-1px_1px_0_#000,_1px_1px_0_#000]'; 
        if (design.textEffect === 'retro') effectClass = 'drop-shadow-[2px_2px_0_rgba(0,0,0,1)]';
    } else {
        effectClass = 'drop-shadow-sm';
    }

    let alignClass = 'text-left';
    if (design.textAlign === 'center') alignClass = 'text-center';
    if (design.textAlign === 'right') alignClass = 'text-right';
    if (design.textAlign === 'justify') alignClass = 'text-justify';

    const lineHeight = isRTL ? 'leading-relaxed' : 'leading-normal';

    // Font handling
    let fontStyle: React.CSSProperties = {};
    let fontClass = 'font-sans';

    if (design.font === 'custom' && design.customFont) {
        fontStyle = { fontFamily: `"${design.customFont}", sans-serif` };
        fontClass = ''; // Clear default class
    } else if (!isRTL) {
        if (design.font === 'serif') fontClass = 'font-serif';
        if (design.font === 'mono') fontClass = 'font-mono';
        if (design.font === 'display') fontClass = 'font-[system-ui] tracking-tighter';
    }

    return { className: `${baseSize} ${sizeClass} ${effectClass} ${alignClass} ${lineHeight} ${fontClass}`, style: fontStyle };
  };

  const getDimensions = () => {
      switch(aspectRatio) {
          case '1:1': return { width: '340px', height: '340px' };
          case '16:9': return { width: '560px', height: '315px' }; 
          case '4:5': 
          default: return { width: '340px', height: '425px' };
      }
  };

  const dim = getDimensions();

  // Helper for hex to rgba
  const hexToRgba = (hex: string, alpha: number) => {
      let c: any;
      if(/^#([A-Fa-f0-9]{3}){1,2}$/.test(hex)){
          c = hex.substring(1).split('');
          if(c.length === 3){
              c= [c[0], c[0], c[1], c[1], c[2], c[2]];
          }
          c = '0x'+c.join('');
          return 'rgba('+[(c>>16)&255, (c>>8)&255, c&255].join(',')+',' + (alpha/100) +')';
      }
      return hex; // Fallback
  };

  const getContainerStyle = () => {
      const style: React.CSSProperties = {
          padding: '1.5rem',
          display: 'flex',
          flexDirection: 'column',
          gap: '0.75rem',
          transition: 'all 0.1s ease-out', // Faster transition for dragging
          width: '100%',
          cursor: isSelected && !readOnly ? 'grab' : 'default'
      };

      if (design.containerStyle === 'glass') {
          style.backgroundColor = 'rgba(255, 255, 255, 0.1)';
          style.backdropFilter = 'blur(12px)';
          style.WebkitBackdropFilter = 'blur(12px)';
          style.borderRadius = '1rem';
          style.border = '1px solid rgba(255, 255, 255, 0.2)';
          style.boxShadow = '0 4px 30px rgba(0, 0, 0, 0.1)';
      } else if (design.containerStyle === 'card') {
          style.backgroundColor = hexToRgba(design.textBackgroundColor || '#000000', 95); 
          style.borderRadius = '0.75rem';
          style.boxShadow = '0 10px 15px -3px rgba(0, 0, 0, 0.3)';
          style.border = `1px solid ${design.accentColor}40`;
      } else if (design.containerStyle === 'paper') {
          style.backgroundColor = '#f8fafc';
          style.borderRadius = '2px';
          style.color = '#1e293b'; 
          style.boxShadow = '2px 2px 5px rgba(0,0,0,0.2)';
          style.transform = 'rotate(-1deg)';
      } else if (design.containerStyle === 'gradient-bottom') {
          style.background = `linear-gradient(to top, ${hexToRgba(design.textBackgroundColor || '#000000', 90)}, transparent)`;
          style.paddingTop = '4rem';
          style.paddingBottom = '2rem';
          style.width = '120%';
          style.marginLeft = '-10%';
      }

      return style;
  };

  const textBgStyle = design.containerStyle === 'none' && design.textBackgroundOpacity > 0 ? {
      backgroundColor: hexToRgba(design.textBackgroundColor || '#000000', design.textBackgroundOpacity || 0),
      boxDecorationBreak: 'clone' as any,
      WebkitBoxDecorationBreak: 'clone' as any,
      padding: '0.25rem 0.5rem',
      borderRadius: '0.25rem'
  } : {};

  const effectiveTextColor = design.containerStyle === 'paper' ? '#0f172a' : design.textColor;
  const headlineStyle = getTextStyle(true);
  const subheadStyle = getTextStyle(false);

  // Render Slide Number Design
  const renderSlideNumber = () => {
    const numDesign = design.slideNumberDesign || { show: true, style: 'minimal', position: isRTL ? 'top-right' : 'top-left' };
    if (!numDesign.show) return null;

    let posClass = '';
    switch(numDesign.position) {
        case 'top-left': posClass = 'top-4 left-4'; break;
        case 'top-right': posClass = 'top-4 right-4'; break;
        case 'bottom-left': posClass = 'bottom-6 left-4'; break;
        case 'bottom-right': posClass = 'bottom-6 right-4'; break;
        default: posClass = 'top-4 left-4';
    }

    const numberText = slide.slide_number < 10 ? `0${slide.slide_number}` : `${slide.slide_number}`;
    const accent = design.accentColor;

    if (numDesign.style === 'minimal') {
        return (
            <div className={`absolute ${posClass} z-20 text-white drop-shadow-md font-bold text-lg font-mono tracking-wider opacity-80`}>
                {numberText}
            </div>
        );
    }
    if (numDesign.style === 'circle') {
        return (
            <div className={`absolute ${posClass} z-20 w-8 h-8 rounded-full border border-white/40 flex items-center justify-center backdrop-blur-sm bg-black/20 text-white font-bold text-xs shadow-lg`}>
                {slide.slide_number}
            </div>
        );
    }
    if (numDesign.style === 'square') {
        return (
            <div className={`absolute ${posClass} z-20 w-8 h-8 border border-white/40 flex items-center justify-center backdrop-blur-sm bg-black/20 text-white font-bold text-xs shadow-lg`} style={{borderRadius: '4px'}}>
                {slide.slide_number}
            </div>
        );
    }
    if (numDesign.style === 'outline') {
        return (
            <div className={`absolute ${posClass} z-20 font-bold text-5xl opacity-40`} 
                 style={{ WebkitTextStroke: '1px white', color: 'transparent' }}>
                {numberText}
            </div>
        );
    }
    if (numDesign.style === 'tag') {
        const isRight = numDesign.position.includes('right');
        const isBottom = numDesign.position.includes('bottom');
        // Simple tag shape
        return (
             <div className={`absolute z-20 px-3 py-1 text-xs font-bold text-white shadow-md
                ${isBottom ? 'bottom-8' : 'top-8'}
                ${isRight ? 'right-0 rounded-l-md' : 'left-0 rounded-r-md'}
             `} style={{ backgroundColor: accent }}>
                #{slide.slide_number}
             </div>
        );
    }

    return null;
  };

  // Helper UI Badge for Errors (Kept Separate from Design)
  const renderStatusBadge = () => {
      if (isError) {
          return (
             <div className="absolute top-2 right-2 z-30 bg-red-500/90 text-white text-[10px] p-1 rounded-full shadow-lg" title="Error generating image" data-html2canvas-ignore="true">
                 <AlertCircle size={12} />
             </div>
          );
      }
      return null;
  };


  return (
    <div 
        id={`slide-card-${slide.slide_number}`}
        ref={containerRef}
        onClick={onSelect}
        className={`flex-shrink-0 relative rounded overflow-hidden bg-slate-900 group transition-all duration-300 select-none print:shadow-none cursor-pointer border-2 ${isSelected ? 'border-blue-500 shadow-[0_0_30px_rgba(59,130,246,0.3)] scale-[1.01]' : 'border-slate-800 hover:border-slate-600'}`}
        style={{ width: dim.width, height: dim.height }}
    >

      {/* Background Layer */}
      <div className="absolute inset-0 z-0 bg-slate-950">
        {imageData ? (
          <img 
            src={imageData} 
            alt={`Slide ${slide.slide_number} visual`} 
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center text-slate-700 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-slate-900 to-slate-950">
            <div className="text-center p-4 flex flex-col items-center gap-3">
              {isGeneratingImage ? (
                  <>
                    <div className="animate-spin w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full mx-auto"/>
                    <p className="text-xs text-slate-500 font-medium">Generating...</p>
                  </>
              ) : isError ? (
                  <>
                    <AlertCircle className="w-10 h-10 text-red-500 opacity-80" />
                    <p className="text-xs text-red-400 font-medium max-w-[150px]">Image generation failed.</p>
                    <button 
                        onClick={(e) => { e.stopPropagation(); onGenerateImage(); }}
                        className="flex items-center gap-1 text-[10px] bg-red-900/50 hover:bg-red-900 border border-red-800 text-red-200 px-3 py-1.5 rounded-full transition-colors mt-1"
                    >
                        <RefreshCw size={12} /> Retry
                    </button>
                  </>
              ) : (
                  <>
                    <ImagePlus className="w-12 h-12 mx-auto opacity-30 text-slate-600" />
                    <p className="text-xs text-slate-600 font-medium">No Image</p>
                  </>
              )}
            </div>
          </div>
        )}

        {/* Overlay */}
        <div 
          className="absolute inset-0 pointer-events-none transition-all duration-300 z-0"
          style={{ backgroundColor: `rgba(15, 23, 42, ${design.overlayOpacity / 100})` }}
        ></div>

        {/* Decorations */}
        {design.decoration === 'circle' && (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-48 h-48 border-4 rounded-full pointer-events-none opacity-50" style={{borderColor: design.accentColor}}></div>
        )}
        {design.decoration === 'square' && (
          <div className="absolute top-4 right-4 bottom-4 left-4 border-2 pointer-events-none opacity-50" style={{borderColor: design.accentColor}}></div>
        )}
        {design.decoration === 'accent-line' && (
           <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-24 h-1 pointer-events-none shadow-lg" style={{backgroundColor: design.accentColor}}></div>
        )}
        {design.decoration === 'corner-shape' && (
           <div className="absolute top-0 right-0 w-24 h-24 rounded-bl-full pointer-events-none opacity-50" style={{ background: `linear-gradient(to bottom left, ${design.accentColor}, transparent)` }}></div>
        )}
        {design.decoration === 'grid' && (
           <div className="absolute inset-0 bg-[linear-gradient(rgba(255,255,255,0.05)_1px,transparent_1px),linear-gradient(90deg,rgba(255,255,255,0.05)_1px,transparent_1px)] bg-[size:20px_20px] pointer-events-none"></div>
        )}
        {design.decoration === 'blob' && (
           <div className="absolute -top-10 -right-10 w-64 h-64 blur-3xl rounded-full pointer-events-none opacity-30" style={{backgroundColor: design.accentColor}}></div>
        )}
        {design.decoration === 'frame' && (
           <div className="absolute inset-3 border rounded-lg pointer-events-none opacity-50" style={{borderColor: design.accentColor}}></div>
        )}
      </div>

      {/* Main Content Layer (Draggable) */}
      <div 
        onMouseDown={handleDragStart}
        onTouchStart={handleDragStart}
        className={`absolute z-10 transition-none ease-out flex flex-col justify-center ${isRTL ? 'font-arabic' : ''}`}
        style={{ 
            top: `${design.yPosition}%`, 
            left: `${design.xPosition}%`,
            width: `${design.textWidth || 85}%`, // Dynamic Width
            transform: 'translate(-50%, 0)', // Position based on center of X
            direction: isRTL ? 'rtl' : 'ltr'
        }}
        dir={isRTL ? 'rtl' : 'ltr'}
      >
          {/* Drag Handle - Only visible when selected and not readonly */}
          {isSelected && !readOnly && (
            <div className="absolute -top-6 left-1/2 -translate-x-1/2 bg-blue-600 text-white p-1 rounded cursor-move opacity-0 group-hover:opacity-100 transition-opacity z-50 shadow-md">
                <Move size={12} />
            </div>
          )}

          <div style={getContainerStyle()} className={`${design.containerStyle !== 'none' ? 'backdrop-blur-sm' : ''} ${isSelected && !readOnly ? 'ring-1 ring-blue-500/50' : ''}`}>
            {readOnly ? (
                <>
                    <div style={textBgStyle}>
                        <h2 
                            className={`whitespace-pre-wrap ${headlineStyle.className}`}
                            style={{ ...headlineStyle.style, color: effectiveTextColor, ...(design.textEffect === 'neon' ? { textShadow: `0 0 10px ${design.accentColor}` } : {}) }}
                        >
                            {slide.headline}
                        </h2>
                    </div>
                    <div style={textBgStyle}>
                        <p 
                            className={`opacity-90 whitespace-pre-wrap ${subheadStyle.className}`}
                            style={{ ...subheadStyle.style, color: effectiveTextColor }}
                        >
                            {slide.sub_headline}
                        </p>
                    </div>
                </>
            ) : (
                <>
                    <div className="relative w-full group/input">
                        <textarea 
                            ref={headlineRef}
                            value={slide.headline}
                            onChange={(e) => onUpdateSlide(slide.slide_number, 'headline', e.target.value)}
                            className={`bg-transparent border border-dashed border-transparent hover:border-white/30 focus:border-blue-500/50 rounded w-full resize-none focus:outline-none focus:ring-0 p-1 overflow-hidden transition-all ${headlineStyle.className}`}
                            style={{ 
                                ...headlineStyle.style,
                                color: effectiveTextColor, 
                                ...(design.textEffect === 'neon' ? { textShadow: `0 0 10px ${design.accentColor}` } : {}),
                                ...textBgStyle
                            }}
                            rows={1}
                            placeholder={isRTL ? "العنوان الرئيسي" : "Headline"}
                            dir={isRTL ? 'rtl' : 'ltr'}
                        />
                    </div>

                    <div className="relative w-full group/input">
                        <textarea 
                            ref={subheadRef}
                            value={slide.sub_headline}
                            onChange={(e) => onUpdateSlide(slide.slide_number, 'sub_headline', e.target.value)}
                            className={`bg-transparent border border-dashed border-transparent hover:border-white/30 focus:border-blue-500/50 rounded w-full resize-none focus:outline-none focus:ring-0 p-1 overflow-hidden transition-all ${subheadStyle.className}`}
                            style={{ 
                                ...subheadStyle.style,
                                color: effectiveTextColor,
                                ...textBgStyle
                            }}
                            rows={1}
                            placeholder={isRTL ? "العنوان الفرعي" : "Sub-headline"}
                            dir={isRTL ? 'rtl' : 'ltr'}
                        />
                    </div>
                </>
            )}
          </div>
      </div>

      {/* Render Slide Number */}
      {renderSlideNumber()}
      {renderStatusBadge()}

      {/* PERSONAL BRANDING FOOTER */}
      {personalBranding?.enabled && (
          <div className={`absolute bottom-6 left-0 right-0 z-20 px-6 flex items-center gap-2 opacity-80 ${design.textAlign === 'center' ? 'justify-center' : design.textAlign === 'right' ? 'justify-end' : 'justify-start'}`}>
              {personalBranding.avatarUrl ? (
                  <img src={personalBranding.avatarUrl} className="w-6 h-6 rounded-full border border-white/20 shadow-sm object-cover"/>
              ) : (
                  <div className="w-6 h-6 rounded-full bg-gradient-to-br from-blue-500 to-purple-500 border border-white/20 flex items-center justify-center text-[10px] font-bold text-white">
                      {personalBranding.name.charAt(0) || 'U'}
                  </div>
              )}
              <div className="flex flex-col leading-none shadow-sm">
                  <span className="text-[10px] font-bold text-white drop-shadow-md">{personalBranding.name}</span>
                  <span className="text-[8px] text-white/80 drop-shadow-md">{personalBranding.handle}</span>
              </div>
          </div>
      )}

      {/* PLATFORM PREVIEW OVERLAY (SAFE ZONES) */}
      {previewPlatform === 'instagram' && (
          <div className="absolute inset-0 pointer-events-none z-30 border-[14px] border-transparent border-t-[60px] border-b-[80px] opacity-30 bg-black/10 mix-blend-multiply flex flex-col justify-between">
              <div className="w-full h-full border-dashed border border-white/30 flex items-center justify-center">
                  <Instagram className="text-white/20" size={48}/>
              </div>
          </div>
      )}
      {previewPlatform === 'linkedin' && (
          <div className="absolute inset-0 pointer-events-none z-30 border-[10px] border-transparent border-b-[60px] opacity-30 bg-black/10 mix-blend-multiply flex flex-col justify-between">
              <div className="w-full h-full border-dashed border border-white/30 flex items-center justify-center">
                  <Linkedin className="text-white/20" size={48}/>
              </div>
          </div>
      )}

    </div>
  );
};

export default SlideCard;

import React, { useState, useEffect, useRef } from 'react';
import { Sparkles, Layers, Download, Palette, Type, Save, Archive, Trash2, Grid, UserPlus, Zap, FileDown, Check, Lightbulb, MessageSquare, Scaling, Layout, Move, AlignLeft, AlignCenter, AlignRight, AlignJustify, X, Frame, BoxSelect, User, Smile, Ghost, RotateCw, RefreshCw, Image as ImageIcon, Camera, AlertTriangle, ArrowLeft, ArrowRight, Smartphone, AtSign, FileOutput, Hash } from 'lucide-react';
